INSERT INTO `sanpham` (`id`, `ten_sp`, `ma_sp`, `gia`, `gia_khuyen_mai`, `chat_lieu`, `da_chinh`, `trong_luong`, `mo_ta`, `hinh_anh`, `danh_muc_id`, `thuong_hieu_id`, `trang_thai`, `ngay_tao`) VALUES
(26, 'Nhẫn Nơ Vàng Tinh Khôi', 'PNJNR001', 15000000.00, 14500000.00, 'Vàng 18K', 'Kim cương', 3.20, 'Sự kết hợp hoàn hảo giữa nét mềm mại của dải lụa và sự cứng cáp của chất liệu vàng cao cấp, mang lại vẻ đẹp thanh lịch cho đôi tay', 'nhan1.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(27, 'Nhẫn Monogram Tinh Tuyển', 'PNJNR002', 12000000.00, NULL, 'Vàng 18K', 'Không', 3.50, 'Một biểu tượng của cá tính riêng biệt. Với thiết kế mặt phẳng tinh tế khắc chữ cái đại diện cho chính bạn, sản phẩm là sự giao thoa hoàn hảo giữa thẩm mỹ hiện đại và giá trị cá nhân độc bản.', 'nhan02.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(28, 'Nhẫn Kim Cương Hoàng Kim', 'PNJNR003', 1800000.00, 1600000.00, 'Vàng Trắng', 'Đá CZ', 2.00, 'Với thiết kế 6 chấu giữ trọn viên đá chủ rực rỡ, kết hợp cùng dải đá tấm lấp lánh dọc đai nhẫn, đây là biểu tượng hoàn hảo cho một tình yêu bền vững và sang trọng. Một tuyệt tác không thể thiếu trong bộ sưu tập của những quý cô tinh tế.', 'nhan03.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(29, 'Nhẫn Hoa Xuân Tinh Khôi', 'PNJNR004', 13500000.00, NULL, 'Vàng trắng', 'Không', 4.00, 'Lấy cảm hứng từ những cánh hoa chớm nở dưới nắng mai, mẫu nhẫn là sự kết hợp tinh tế giữa nghệ thuật chạm khắc hình khối và những viên đá nhỏ li ti lấp lánh. Một biểu tượng của sự nữ tính, thanh khiết dành riêng cho những quý cô yêu kiều của Luxury Jewelry.', 'nhan4.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(30, 'Nhẫn Hoàng Gia Lấp Lánh', 'PNJNR005', 25000000.00, 24000000.00, 'Vàng trắng', 'Kim cương tự nhiên', 3.80, 'Thiết kế Halo kinh điển với viên đá chủ được ôm trọn bởi vòng đá tấm rực rỡ, giúp nhân đôi kích thước và sự lấp lánh. Kết hợp cùng đai nhẫn nạm đá tinh xảo, mỗi chuyển động của đôi tay sẽ thu hút mọi ánh nhìn. Đây chính là tuyên ngôn cho vẻ đẹp quyền quý và đẳng cấp của bạn.', 'nhan05.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(31, 'Nhẫn Khởi Đầu Vĩnh Cửu', 'PNJNR006', 16000000.00, NULL, 'Vàng 18K', 'Kim cương', 3.00, 'Sự kết hợp hoàn mỹ giữa sắc vàng nồng ấm và viên đá chủ rực rỡ được chế tác tinh xảo. Đai nhẫn đính đá tấm thủ công tạo nên dải ánh sáng liên tục, tôn vinh nét đẹp quý phái và cổ điển của người phụ nữ hiện đại. Một biểu tượng cho sự sang trọng và tình yêu vĩnh cửu.', 'nhan06.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(32, 'Nhẫn Vàng Butterfly Grace', 'PNJNR007', 11000000.00, NULL, 'Vàng 18K', 'Không', 3.40, 'Lấy cảm hứng từ vẻ đẹp mong manh và thanh tú của cánh bướm, mẫu nhẫn này mang đến sự nhẹ nhàng tuyệt đối cho đôi tay quý cô. Thiết kế tối giản với chất liệu vàng sáng bóng, Papillon Grace chính là món phụ kiện hoàn hảo để diện hàng ngày, tôn vinh vẻ đẹp tự nhiên và nữ tính.', 'nhan07.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(33, 'Nhẫn Tinh Tuyển', 'PNJNR008', 1500000.00, NULL, 'Bạc 925', 'Đá CZ', 2.10, 'Đơn giản nhưng đầy quyền năng, thiết kế  kinh điển với 4 chấu nâng cao viên đá chủ, cho phép ánh sáng đi qua tối đa để tạo nên sự lấp lánh tuyệt mỹ. Đai nhẫn trơn mảnh được chế tác tinh xảo giúp tôn vinh trọn vẹn vẻ đẹp của viên đá và nét thanh tú của đôi tay. Một lựa chọn không thể hoàn hảo hơn cho thời khắc quan trọng nhất cuộc đời.', 'nhan08.jpg', 1, 2, '1', '2026-02-25 16:06:21'),
(34, 'Nhẫn Kim Cương Vòm Ánh Sáng', 'PNJNR009', 27000000.00, 26000000.00, 'Vàng trắng', 'Kim cương', 3.90, 'Không chỉ là một chiếc nhẫn, đây là một công trình nghệ thuật thu nhỏ. Với thiết kế đai nhẫn đan chéo độc đáo được nạm hàng trăm viên đá tấm li ti, dẫn lối ánh sáng đến viên đá chủ rực rỡ ở tâm điểm. Sản phẩm là sự lựa chọn hoàn hảo cho những quý cô kiếm tìm sự khác biệt, lộng lẫy và đẳng cấp tuyệt đối tại Luxury Jewelry.', 'nhan09.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(35, 'Nhẫn Hồ Điệp Ngân Kim', 'PNJNR010', 14000000.00, NULL, 'Vàng trắng ', 'Không', 4.20, 'Một thiết kế phá cách đầy nghệ thuật với những đường cong uốn lượn như một dải lụa mềm mại bao quanh ngón tay. Được nạm đá tinh xảo trên từng milimet, mẫu nhẫn này không chỉ là trang sức mà còn là biểu tượng của sự nữ tính, kiêu kỳ. Phù hợp cho những buổi tiệc tối sang trọng hay món quà đặc biệt dành tặng nàng thơ của bạn.', 'nhan010.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(36, 'Nhẫn Xoắn Tinh Thượng', 'PNJNR011', 15500000.00, NULL, 'Vàng 18K', 'Kim cương', 3.10, 'Không cần những viên đá lấp lánh, mẫu nhẫn này khẳng định đẳng cấp qua kỹ thuật chế tác nút thắt tinh xảo. Hình ảnh hai dải vàng đan chặt vào nhau tượng trưng cho một tình cảm bền chặt, không có điểm kết thúc. Một món phụ kiện hoàn hảo cho những ai yêu thích vẻ đẹp đơn giản, ý nghĩa và trường tồn với thời gian.', 'nhan11.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(37, 'Nhẫn Kim Tiền Đắc Lộc', 'PNJNR012', 9800000.00, NULL, 'Vàng 18K', 'Không', 2.80, 'Không chỉ là món trang sức tinh xảo, mẫu nhẫn Kim Tiền với các đồng xu vàng nối liền không điểm kết là biểu tượng của sự may mắn và tài lộc dồi dào. Thiết kế thanh lịch, sắc nét trên từng đường nét chế tác, sản phẩm là người đồng hành hoàn hảo mang lại vượng khí cho chủ nhân trong công việc và cuộc sống. Một tuyệt phẩm phong thủy không thể thiếu tại Luxury Jewelry.', 'nhan12.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(38, 'Nhẫn  Trái Tim Hoàng Kim', 'PNJNR013', 17500000.00, 16500000.00, 'Vàng 18K', 'Kim cương', 3.70, 'Một tuyệt tác tôn vinh vẻ đẹp lãng mạn với tâm điểm là viên đá hình trái tim được ôm trọn bởi vòng hào quang lấp lánh. Thiết kế đai nhẫn nạm đá tấm tinh xảo giúp đôi tay quý cô thêm phần thanh tú và sang trọng. Sweetheart Halo chính là lời khẳng định cho một tình yêu bền vững và ngọt ngào.', 'nhan13.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(39, 'Nhẫn Kim Cương Lục Bảo Tinh Khôi', 'PNJNR014', 13500000.00, NULL, 'Vàng trắng', 'Không', 3.60, 'Với tâm điểm là viên đá chủ giác cắt  kinh điển, mẫu nhẫn mang lại vẻ ngoài mạnh mẽ nhưng không kém phần thanh lịch. Hai viên đá Baguette bên cạnh giúp tôn vinh chiều sâu và độ trong suốt tuyệt đối của viên đá chính. Đây là lựa chọn hoàn hảo cho những quý cô muốn sở hữu một món trang sức mang vẻ đẹp trí tuệ và sự sang trọng bền vững.', 'nhan14.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(40, 'Nhẫn Vàng Thiên Thần Duyên Dáng', 'PNJNR015', 14500000.00, NULL, 'Vàng 18K', 'Kim cương', 3.30, 'Khơi nguồn cảm hứng từ vẻ đẹp kiêu sa của cánh bướm, mẫu nhẫn sử dụng các viên đá giác cắt Marquise tinh xảo để tạo nên hiệu ứng thị giác đỉnh cao. Thiết kế đai hở nạm đá tấm không chỉ mang lại vẻ hiện đại, phá cách mà còn giúp quý cô dễ dàng điều chỉnh kích thước vừa vặn. Một món trang sức tuyên ngôn cho vẻ đẹp nữ tính và đẳng cấp tại Luxury Jewelry.', 'nhan15.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(41, 'Nhẫn Hoàng Kim Chạm Khắc Cổ Điển', 'PNJNR016', 21000000.00, 20000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 3.90, 'Một kiệt tác dành cho những người yêu quý giá trị truyền thống và sự tinh xảo trong từng đường nét. Mẫu nhẫn gây ấn tượng bởi phần đai được chạm khắc rỗng thủ công theo phong cách Art Deco, kết hợp cùng 6 chấu vươn cao giữ trọn viên đá chủ rực rỡ như một đóa hoa đang khoe sắc. Sản phẩm không chỉ là trang sức, mà là một kỷ vật mang đậm dấu ấn di sản và tình yêu bền chặt tại Luxury Jewelry.', 'nhan16.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(42, 'Nhẫn Khối Hiện Đại', 'PNJNR017', 12500000.00, NULL, 'Vàng 18K', 'Không', 3.00, 'Không cần đến những viên đá quý phô trương, Prism Faceted Band tự tỏa sáng nhờ kỹ thuật cắt vát đa diện đỉnh cao trên chất liệu vàng sáng bóng. Mỗi chuyển động của đôi tay là một lần ánh sáng được phản chiếu rực rỡ từ những mặt cắt sắc sảo. Một thiết kế tối giản, hiện đại và cực kỳ dễ phối đồ (stackable), mang lại vẻ đẹp cá tính nhưng không kém phần quý phái cho chủ nhân tại Luxury Jewelry.', 'nhan17.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(43, 'Nhẫn Bypass Tinh Xảo', 'PNJNR018', 19000000.00, NULL, 'Vàng 18K', 'Kim cương', 3.40, 'Phá vỡ những quy tắc truyền thống, Asymmetric Flow Ring là tuyên ngôn của sự tự do và phong cách riêng biệt. Thiết kế đai kép bất đối xứng với một nhánh nạm đá tấm rực rỡ đan chéo qua nhánh vàng trơn mượt mà, tạo nên sự tương phản đầy cuốn hút trên đôi tay. Một tuyệt tác dành cho những quý cô yêu thích vẻ đẹp tinh tế, sang trọng nhưng không kém phần phá cách tại Luxury Jewelry.', 'nhan18.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(44, 'Nhẫn Vàng Trắng Nhám Mờ', 'PNJNR019', 13000000.00, NULL, 'Vàng trắng', 'Không', 3.50, 'Không phô trương, không cầu kỳ, mẫu nhẫn khẳng định vị thế bằng chất liệu cao cấp với bề mặt phay xước mờ (Brushed Finish) thời thượng. Sự tinh túy nằm ở mặt trong đai nhẫn với những viên đá nhỏ được đính thủ công, đại diện cho những giá trị riêng tư và quý giá nhất của chủ nhân. Một sự lựa chọn hoàn hảo cho những ai kiếm tìm vẻ đẹp tối giản, bền bỉ và giàu ý nghĩa cá nhân tại Luxury Jewelry.', 'nhan19.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(45, 'Nhẫn Kim Cương Hoàng Kim Song Hành', 'PNJNR020', 14500000.00, NULL, 'Vàng 18K', 'Kim cương', 3.20, 'Sự kết hợp hoàn hảo giữa thiết kế đai xẻ đôi (Split Shank) độc đáo và viên đá chủ rực rỡ tạo nên một kiệt tác không thể rời mắt. Với một nhánh nạm đá tấm tinh xảo đan xen nhánh vàng trơn mượt mà, mẫu nhẫn tôn vinh trọn vẹn nét thanh tú và đẳng cấp của quý cô hiện đại. Thiết kế đai hở tinh tế giúp dễ dàng điều chỉnh, đây chính là món quà tuyệt vời dành tặng bản thân hoặc người thương tại Luxury Jewelry.', 'nhan020.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(46, 'Nhẫn Đá Chủ Ánh Dương', 'PNJNR021', 15000000.00, NULL, 'Vàng 18K', 'Kim cương', 3.10, 'Phá bỏ những giới hạn của thiết kế chấu truyền thống, Golden Embrace mang đến một cái nhìn mới lạ với viên đá chủ được ôm ấp tinh tế bởi hai dải vàng nạm đá tấm lấp lánh. Những đường cong mượt mà không chỉ tôn vinh vẻ đẹp của viên đá mà còn tạo cảm giác thanh tú cho đôi tay quý cô. Một thiết kế đầy tính nghệ thuật, đại diện cho tình yêu nồng nàn và sự bảo bọc bền vững.', 'nhan21.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(47, 'Nhẫn Kim Cương Hoàng Kim Đại Phát', 'PNJNR022', 17000000.00, NULL, 'Vàng 18K', 'Kim cương', 3.60, 'Không chỉ là một chiếc nhẫn, đây là một tuyên ngôn về sự sang trọng tuyệt đối. Majestic Crown gây ấn tượng mạnh với đai nhẫn bản rộng nạm đá tấm tinh xảo, tạo nên một dải ánh sáng liên tục bao quanh ngón tay. Tâm điểm là viên đá chủ rực rỡ được nâng đỡ bởi 6 chấu hoàng kim chắc chắn, mang lại vẻ đẹp lộng lẫy và kiêu sa nhất dành cho quý cô của Luxury Jewelry.', 'nhan22.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(48, 'Nhẫn Vàng Trái Tim Tinh Khôi', 'PNJNR023', 10000000.00, NULL, 'Vàng 18K', 'Không', 2.90, 'Một tuyệt tác dành cho những ai yêu thích sự tinh tế \"không phô trương\". Với thiết kế đai nhẫn trơn bóng mượt mà hướng về tâm điểm là viên đá chủ rực rỡ, điểm nhấn đặc biệt nằm ở tạo hình trái tim ẩn giấu ngay dưới bệ đá. Hidden Heart không chỉ tôn vinh nét thanh tú của đôi tay mà còn là biểu trưng cho một tình yêu chân thành, sâu sắc và bền vững tại Luxury Jewelry.', 'nhan23.jpg', 1, 1, '1', '2026-02-25 16:06:21'),
(49, 'Nhẫn Vàng Hồng Tinh Khôi', 'PNJNR024', 26000000.00, 25000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 4.00, 'Sự kết hợp hoàn hảo giữa tông vàng hồng thời thượng và thiết kế 6 chấu kinh điển mang đến vẻ đẹp ngọt ngào đầy quý phái. Đai nhẫn được chế tác thuôn nhẹ về phía tâm điểm, giúp tôn vinh trọn vẹn sự lộng lẫy của viên đá chủ và nét thanh tú cho đôi bàn tay quý cô. Một lựa chọn tinh tế để đánh dấu những khoảnh khắc yêu thương tại Luxury Jewelry.', 'nhan24.jpg', 1, 1, '0', '2026-02-25 16:06:21'),
(51, 'Dây Chuyền Giọt Sương Ban Mai', 'PNJDC001', 18000000.00, 17000000.00, 'Vàng 18K', 'Kim cương', 5.20, 'Lấy cảm hứng từ sự thanh khiết của những giọt sương sớm, mẫu dây chuyền sở hữu mặt đá hình giọt nước được bao bọc tinh tế trong viền vàng sáng bóng. Thiết kế tối giản nhưng không kém phần sang trọng, đây là món phụ kiện hoàn hảo để tôn vinh vùng cổ thanh tú, mang lại vẻ đẹp nhẹ nhàng và đầy lôi cuốn cho phái đẹp.', 'day01.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(52, 'Dây Chuyền Hồ Lô Như Ý', 'PNJDC002', 15000000.00, NULL, 'Vàng 18K', 'Không', 4.80, 'Hồ lô từ lâu đã là biểu tượng của sự bảo bọc và sức khỏe dồi dào. Với thiết kế hiện đại kết hợp cùng tua rua chuông nhỏ mềm mại, mẫu dây chuyền không chỉ mang lại vẻ lộng lẫy cho phái đẹp mà còn là món trang sức phong thủy tuyệt vời, giúp xua tan vận rủi và mang đến bình an. Một món quà ý nghĩa dành tặng cho chính bạn hoặc những người thân yêu tại Luxury Jewelry.', 'day02.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(53, 'Dây Chuyền Tâm Hoa Hoàng Kim', 'PNJDC003', 25000000.00, 24000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 5.50, 'Mẫu này có thiết kế rất độc đáo với mặt dây chuyền hình trái tim được chạm trổ hoa văn tinh xảo, đính kèm một đóa hoa nhỏ có tâm là đá sáng. Sợi dây dạng mắt xích dẹt (dây lá) tạo độ bắt sáng lấp lánh cực tốt.', 'day03.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(54, 'dây chuyền Ngọc Trai Quý Tộc', 'PNJDC004', 9500000.00, NULL, 'Vàng 18K', 'Ngọc trai', 6.00, 'thiết kế mang phong cách \"Goddess\" (Nữ thần). Viên ngọc trai lớn được ôm trọn bởi dải vàng hồng uốn lượn nạm đá tấm lấp lánh theo hình giọt nước cách điệu. Đây là biểu tượng của sự sang trọng, tinh tế và quyền quý.', 'day04.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(55, 'Dây Chuyền Ánh Kim Tinh Tú', 'PNJDC005', 1800000.00, 1600000.00, 'Bạc 925', 'Đá CZ', 3.20, 'Khơi nguồn từ sự tối giản đỉnh cao, mẫu dây chuyền tập trung làm nổi bật viên đá chủ rực rỡ nhất. Phần khoen được đính đá tấm tỉ mỉ tạo nên sự kết nối mềm mại, giúp mặt dây chuyền chuyển động tự nhiên và bắt sáng hoàn hảo ở mọi góc nhìn. Đây là món trang sức \"vượt thời gian\", dễ dàng đồng hành cùng quý cô từ văn phòng thanh lịch đến những bữa tiệc tối sang trọng tại Luxury Jewelry.', 'day05.jpg', 2, 2, '1', '2026-02-25 16:06:52'),
(56, 'Dây Chuyền Nơ Lụa Mềm Mại', 'PNJDC006', 16500000.00, NULL, 'Vàng trắng ', 'Không', 5.00, 'Không cần đến những viên đá lấp lánh, mẫu dây chuyền Nơ Lụa Satin khẳng định đẳng cấp qua kỹ thuật tạo hình nếp gấp tinh tế và bề mặt phay nhám mờ sang trọng. Thiết kế lấy cảm hứng từ những dải ruy băng lụa mềm mại, ôm lấy vùng cổ thanh tú để tôn vinh vẻ đẹp ngọt ngào và nữ tính. Một món phụ kiện hoàn hảo cho những quý cô yêu thích phong cách tối giản nhưng vẫn đầy cá tính tại Luxury Jewelry.', 'day06.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(57, 'Dây Chuyền Ánh Dương Hoàng Kim', 'PNJDC007', 27000000.00, 26000000.00, 'Vàng 18K', 'Kim cương', 5.80, 'Tối giản nhưng đầy uy quyền, mẫu dây chuyền tập trung toàn bộ ánh nhìn vào viên đá chủ giác cắt tròn hoàn hảo. Phần khoen chữ V tinh tế không chỉ tạo điểm nhấn hiện đại mà còn giúp mặt dây cân bằng tuyệt đối khi đeo. Sắc vàng nồng nàn kết hợp cùng độ bắt sáng rực rỡ của viên đá tạo nên một món trang sức đẳng cấp, tôn vinh khí chất sang trọng và sự tự tin của người phụ nữ Luxury Jewelry.', 'day07.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(58, 'Dây Chuyền Cỏ Bốn Lá May Mắn', 'PNJDC008', 12000000.00, 11000000.00, 'Vàng 18K', 'Không', 4.50, 'Không cần những viên đá lấp lánh, mẫu dây chuyền Cỏ Bốn Lá chinh phục phái đẹp bởi thiết kế tối giản, tinh tế trên chất liệu vàng sáng bóng. Từng cánh hoa được chế tác cân xứng, mềm mại, đại diện cho Niềm tin – Hy vọng – Tình yêu và sự May mắn. Đây là món trang sức tinh tế giúp tô điểm cho vùng cổ thanh tú, đồng thời là chiếc \"bùa hộ mệnh\" nhỏ bé mang lại năng lượng tích cực cho quý cô mỗi ngày tại Luxury Jewelry.', 'day08.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(59, 'Dây Chuyền Cát Tường Hào Quang', 'PNJDC009', 14000000.00, 12000000.00, 'Vàng 18K', 'Kim cương', 4.90, 'Không chỉ dừng lại ở ý nghĩa may mắn của biểu tượng cỏ bốn lá, mẫu dây chuyền Cát Tường Hào Quang là một bản giao hưởng giữa nét chế tác thủ công tinh xảo và ánh sáng lộng lẫy. Sự kết hợp giữa những dải vàng trơn mềm mại và dải nạm đá tấm bao quanh viên đá chủ tạo nên chiều sâu và sự cuốn hút khó cưỡng. Cùng với sợi dây lá lấp lánh, đây là lựa chọn hoàn hảo để quý cô tỏa sáng trong những bữa tiệc sang trọng hay các dịp đặc biệt tại Luxury Jewelry.', 'day09.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(60, 'Dây Chuyền Vô Cực Tình Thân', 'PNJDC010', 11000000.00, 10000000.00, 'Vàng 18K', 'Không', 4.30, 'Phá bỏ mọi giới hạn của thiết kế truyền thống, Infinity Drop mang đến một vẻ đẹp thanh thoát và đầy kiêu sa. Sự kết hợp tinh tế giữa biểu tượng vô cực và mặt dây giọt nước thả dài tạo hiệu ứng chữ Y giúp vùng cổ trông thon gọn và cuốn hút hơn. Với chất liệu vàng trơn bóng bẩy, mẫu dây chuyền này chính là lời khẳng định về một phong cách hiện đại, tinh tế và một tình yêu không có điểm dừng tại Luxury Jewelry.', 'day10.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(61, 'Dây Chuyền Bản Giao Hưởng Ánh Sáng', 'PNJDC011', 20000000.00, 19000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 5.60, 'Không tuân theo bất kỳ một quy tắc đối xứng nào, mẫu dây chuyền chinh phục trái tim giới mộ điệu bởi sự kết hợp táo bạo giữa các giác cắt đá Emerald, Princess và Round. Từng viên đá được tuyển chọn kỹ lưỡng, đan xen vào nhau tạo nên một dải ánh sáng rực rỡ và đa chiều. Đây không chỉ là trang sức, mà là một tác phẩm nghệ thuật hiện đại tôn vinh cá tính độc bản và sự kiêu sa của quý cô Luxury Jewelry trong những buổi tiệc tối thượng lưu.', 'day11.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(62, 'Dây Chuyền Nụ Hoa Tinh Khôi', 'PNJDC012', 17500000.00, NULL, 'Vàng 18K', 'Kim cương', 5.10, 'Khẳng định gu thẩm mỹ tinh tế với mẫu dây chuyền sở hữu đường cong tuyệt mỹ. Mặt dây được chế tác thủ công với hai dải vàng uốn lượn ôm trọn viên đá chủ rực rỡ, tạo nên hiệu ứng thị giác giúp vùng cổ trông thon dài và thanh tú hơn. Sự kết hợp giữa nét hiện đại và vẻ đẹp cổ điển làm nên một món trang sức đa năng, dễ dàng phối hợp cùng trang phục công sở hay váy dự tiệc sang trọng tại Luxury Jewelry.', 'day12.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(63, 'Dây Chuyền Cánh bướm vàng duyên dáng', 'PNJDC013', 9800000.00, NULL, 'Vàng 14K', 'Không', 4.00, 'Lấy cảm hứng từ vẻ đẹp mong manh và sống động của những chú bướm xuân, mẫu dây chuyền chữ Y độc đáo này là một tuyệt tác dành riêng cho những tâm hồn lãng mạn. Từng cánh bướm được chạm khắc vân nổi tinh xảo, đan xen cùng những hạt phối vàng tròn trịa, tạo nên dải phụ kiện lung linh và thanh thoát. Với chất liệu vàng rực rỡ, sản phẩm không chỉ tôn vinh nét duyên dáng mà còn mang lại sự trẻ trung, tràn đầy sức sống cho quý cô Luxury Jewelry.', 'day13.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(64, 'Dây Chuyền Ổ khóa vàng tinh khôi', 'PNJDC014', 8500000.00, NULL, 'Vàng 14K', 'Không', 3.80, 'Lấy cảm hứng từ những chiếc \"khóa tình yêu\" trên các cây cầu huyền thoại, mẫu dây chuyền mang thiết kế Padlock tối giản là biểu tượng của sự gắn kết bền chặt. Sợi dây được điểm xuyết những hạt bi vàng tinh tế, tạo độ bắt sáng nhẹ nhàng và nét trẻ trung cho người đeo. Đây không chỉ là món trang sức thời thượng mà còn là vật phẩm ý nghĩa để \"khóa chặt\" những kỷ niệm tuyệt vời nhất tại Luxury Jewelry.', 'day14.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(65, 'Dây Chuyền Vĩnh Kết', 'PNJDC015', 23000000.00, 22000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 5.90, 'Lấy cảm hứng từ hình ảnh hai vòng tròn giao hòa – biểu tượng của sự gắn kết và vĩnh cửu – mẫu dây chuyền mang thiết kế Interlock hiện đại, tối giản nhưng đầy tinh tế. Một vòng tròn vàng trơn bóng kết hợp cùng vòng tròn đính đá lấp lánh, tạo nên sự đối lập hài hòa giữa giản dị và sang trọng. Sợi dây mảnh mai càng tôn lên vẻ thanh lịch, giúp người đeo dễ dàng kết hợp trong nhiều phong cách khác nhau. Đây không chỉ là món trang sức thời thượng mà còn là lời nhắn gửi về sự kết nối bền chặt và tình cảm vĩnh hằng tại Luxury Jewelry.', 'day15.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(66, 'Dây Chuyền Tình Yêu Vĩnh Cửu', 'PNJDC016', 19000000.00, NULL, 'Vàng 18K', 'Kim cương', 5.20, 'Infinity Heart là một kiệt tác tôn vinh những giá trị vĩnh cửu. Với thiết kế trái tim nạm đá lấp lánh đan quyện cùng biểu tượng vô cực bằng vàng mềm mại, mẫu dây chuyền truyền tải thông điệp về một tình yêu bền chặt, vượt qua mọi giới hạn của thời gian. Sợi dây chuyền mắt xích chắc chắn đi kèm giúp mang lại vẻ ngoài hiện đại, đẳng cấp, là món quà tặng không thể tuyệt vời hơn để dành cho \"người duy nhất\" của bạn tại Luxury Jewelry.', 'day16.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(67, 'Dây Chuyền Song Kết', 'PNJDC017', 13000000.00, NULL, 'Vàng 18K', 'Không', 4.40, 'Vượt qua những thiết kế cầu kỳ, Golden Interlock chinh phục quý cô bởi vẻ đẹp nguyên bản của những vòng tròn vàng bóng bẩy. Hai vòng tròn đan lồng vào nhau không rời là biểu tượng cho sự gắn kết vô hình nhưng bền chặt của tình thân, tình yêu hay tình tri kỷ. Với độ mảnh vừa phải và sắc vàng nồng nàn, mẫu dây chuyền này là món phụ kiện hoàn hảo để diện cùng những trang phục tối giản, giúp tôn lên khí chất thanh lịch và sự tinh tế của người phụ nữ Luxury Jewelry.', 'day17.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(68, 'Dây Chuyền Nơ Ánh Kim', 'PNJDC018', 21000000.00, 20000000.00, 'Vàng 18K', 'Kim cương', 5.40, 'Dây chuyền vàng tinh xảo với mặt dây hình chiếc nơ duyên dáng, được đính đá lấp lánh tạo nên vẻ sang trọng và nữ tính. Hai dải xích nhỏ thả xuống từ tâm nơ mang đến sự mềm mại, uyển chuyển, như điểm nhấn đầy tinh tế trên cổ người đeo. Thiết kế kết hợp giữa nét cổ điển và hiện đại, vừa thanh lịch vừa thời thượng, là món trang sức lý tưởng để tôn vinh phong cách quý phái và ngọt ngào.', 'day18.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(69, 'Dây Chuyền Trái Tim Nghệ Thuật', 'PNJDC019', 9000000.00, NULL, 'Vàng 14K', 'Không', 3.70, 'Dây chuyền vàng thanh mảnh với mặt dây hình trái tim cách điệu rỗng ruột, mang phong cách hiện đại và tinh tế. Bề mặt nhẵn bóng, phản chiếu ánh sáng sang trọng, kết hợp cùng chuỗi hạt nhỏ nhắn tạo nên vẻ đẹp mềm mại và trẻ trung. Thiết kế tối giản nhưng giàu tính nghệ thuật, vừa là món trang sức thời thượng vừa là biểu tượng của tình yêu được thể hiện theo cách độc đáo và khác biệt.', 'day19.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(70, 'Dây Chuyền Trái Tim Vô Cực', 'PNJDC020', 1500000.00, NULL, 'Bạc 925', 'Đá CZ', 3.10, 'Dây chuyền bạc sang trọng với mặt dây hình trái tim kết hợp biểu tượng vô cực, được đính đá sáng lấp lánh tạo hiệu ứng hào quang rực rỡ. Viên đá chủ đạo tròn lớn ở trung tâm được bao quanh bởi những viên đá nhỏ tinh xảo, tôn lên vẻ đẹp lấp lánh và thanh lịch. Thiết kế mang ý nghĩa tình yêu bất tận, sự gắn kết vĩnh cửu, vừa hiện đại vừa đầy cảm xúc. Đây là món trang sức hoàn hảo để làm quà tặng, lưu giữ những khoảnh khắc yêu thương và khẳng định phong cách thời thượng.', 'day20.jpg', 2, 2, '1', '2026-02-25 16:06:52'),
(71, 'Dây Chuyền Hoa Ánh Kim', 'PNJDC021', 17500000.00, NULL, 'Vàng 18K', 'Kim cương', 5.00, 'Dây chuyền vàng sang trọng với mặt dây hình hoa cách điệu, gồm năm viên đá sáng lấp lánh được sắp xếp đối xứng, tạo nên vẻ đẹp tinh tế và cân bằng. Sợi dây dạng xoắn mềm mại càng làm nổi bật sự độc đáo của thiết kế, mang đến cảm giác vừa cổ điển vừa hiện đại. Đây là món trang sức mang ý nghĩa tỏa sáng và thanh khiết, thích hợp để làm quà tặng hoặc điểm nhấn cho phong cách thời thượng.', 'day21.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(72, 'Dây Chuyền Song Tâm', 'PNJDC022', 14500000.00, NULL, 'Vàng 18K', 'Không', 4.60, 'Dây chuyền vàng tinh xảo với mặt dây hình trái tim đôi, một trái tim trơn bóng phía trước và một trái tim họa tiết uốn lượn phía sau. Thiết kế chồng lớp tạo chiều sâu và sự khác biệt, vừa thanh lịch vừa nghệ thuật. Sợi dây vàng mảnh mai càng làm nổi bật vẻ sang trọng, là món trang sức mang ý nghĩa tình yêu song hành – sự hòa quyện giữa giản dị và tinh tế.', 'day22.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(73, 'Dây Chuyền Ánh Kim Vĩnh Cửu', 'PNJDC023', 24000000.00, 23000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 5.70, 'Dây chuyền vàng tinh xảo với mặt dây hình giọt dài cách điệu, phần trên đính nhiều viên đá nhỏ lấp lánh, phía dưới nổi bật với một viên đá tròn lớn rực rỡ. Thiết kế mang đến sự cân bằng giữa nét mềm mại và sự sang trọng, tạo điểm nhấn nổi bật trên cổ người đeo. Sợi dây vàng mảnh mai càng làm tôn lên vẻ thanh lịch, là món trang sức hoàn hảo để khẳng định phong cách tinh tế và quý phái.', 'day23.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(74, 'Dây Chuyền Cỏ Bốn Lá May Mắn', 'PNJDC024', 10500001.00, NULL, 'Vàng 14K', 'Không', 4.20, 'Dây chuyền vàng tinh tế với mặt dây hình cỏ bốn lá, mỗi cánh được chế tác từ chất liệu trắng ngọc ngà viền vàng sang trọng, điểm nhấn là viên đá nhỏ sáng lấp lánh ở trung tâm. Thiết kế mang ý nghĩa may mắn, hạnh phúc và sự viên mãn, đồng thời toát lên vẻ đẹp thanh lịch và hiện đại. Sợi dây mảnh mai càng làm nổi bật sự tinh xảo, là món trang sức hoàn hảo để làm quà tặng hoặc giữ bên mình như một biểu tượng của sự may mắn và tình yêu.', 'day24.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(75, 'Dây Chuyền Tam Sáng', 'PNJDC025', 16000000.00, NULL, 'Vàng 18K', 'Kim cương', 5.30, 'Dây chuyền vàng tinh tế với ba viên kim cương cắt tròn được sắp xếp thành hình tam giác cân đối, viên trung tâm lớn hơn tạo điểm nhấn nổi bật. Thiết kế tối giản nhưng sang trọng, tôn vinh sự cân bằng và ánh sáng rực rỡ của đá quý. Sợi dây mảnh mai càng làm nổi bật vẻ thanh lịch, là món trang sức lý tưởng cho những ai yêu thích phong cách tinh giản nhưng đầy cuốn hút.', 'day25.jpg', 2, 1, '1', '2026-02-25 16:06:52'),
(76, 'Bông Tai Tinh Quang', 'PNJBT001', 12500000.00, 12000000.00, 'Vàng 18K', 'Kim cương', 2.50, 'Đôi hoa tai vàng sang trọng với viên đá tròn sáng lấp lánh được gắn chắc chắn trong ngàm bốn chấu tinh xảo. Thiết kế tối giản nhưng thanh lịch, tôn vinh vẻ đẹp thuần khiết và sự rực rỡ của ánh sáng. Nền vải hồng mềm mại càng làm nổi bật sự tinh tế, biến đôi hoa tai trở thành điểm nhấn hoàn hảo cho phong cách quý phái và hiện đại. Đây là món trang sức lý tưởng để khẳng định sự tự tin và cuốn hút trong mọi khoảnh khắc.', 'bt01.jpg', 3, 1, '1', '2026-02-25 16:08:10'),
(77, 'Bông Tai Vàng Vòng Ánh Kim', 'PNJBT002', 9800000.00, NULL, 'Vàng 18K', 'Không', 2.30, 'Đôi hoa tai vàng dạng vòng tròn dày dặn, bề mặt nhẵn bóng phản chiếu ánh sáng sang trọng. Thiết kế tối giản nhưng đầy tinh tế, mang đến vẻ đẹp hiện đại và thanh lịch. Kiểu dáng tròn trịa tượng trưng cho sự viên mãn và gắn kết, dễ dàng kết hợp với nhiều phong cách thời trang khác nhau. Đây là món trang sức lý tưởng để khẳng định phong cách cá nhân, vừa trẻ trung vừa quý phái.', 'bt02.jpg', 3, 1, '1', '2026-02-25 16:08:10'),
(78, 'Bông Tai Kim Cương Vuông Ánh Vàng', 'PNJBT003', 18500000.00, 17500000.00, 'Vàng 18K', 'Kim cương tự nhiên', 2.80, 'Đôi hoa tai vàng tinh tế với viên đá vuông sáng lấp lánh, được cố định bằng ngàm bốn chấu chắc chắn. Thiết kế đơn giản nhưng sang trọng, tôn vinh sự sắc nét và rực rỡ của đá quý. Nền vải satin hồng nhẹ càng làm nổi bật vẻ đẹp thanh lịch, biến đôi hoa tai trở thành điểm nhấn hoàn hảo cho phong cách quý phái và hiện đại. Đây là món trang sức lý tưởng để khẳng định sự tinh tế và cá tính trong mọi dịp.', 'bt03.jpg', 3, 1, '1', '2026-02-25 16:08:10'),
(79, 'Ngọc Trai Ánh Vàng', 'PNJBT004', 6500000.00, NULL, 'Vàng 18K', 'Ngọc trai', 2.60, 'Đôi hoa tai sang trọng với viên ngọc trai tròn lớn được bao bọc trong khung vàng uốn lượn bất đối xứng, tạo nên vẻ đẹp hiện đại và nghệ thuật. Sự kết hợp giữa sắc trắng tinh khôi của ngọc trai và ánh vàng sang trọng mang đến phong cách thanh lịch, tinh tế nhưng vẫn đầy cá tính. Đây là món trang sức lý tưởng để tôn vinh vẻ đẹp tự nhiên, đồng thời khẳng định phong cách thời thượng của người đeo.', 'bt04.jpg', 3, 1, '1', '2026-02-25 16:08:10'),
(80, 'Bông Tai  Cánh Bướm Ngọc Quang', 'PNJBT005', 1500000.00, 1300000.00, 'Bạc 925', 'Đá CZ', 1.80, 'Đôi hoa tai tinh xảo với họa tiết bướm nhỏ nhắn ở phần trên, đôi cánh ánh sắc óng ánh kết hợp nền vàng sang trọng. Phía dưới là vòng tròn cân đối gồm những viên ngọc trai xen kẽ đá quý lấp lánh, tạo nên vẻ đẹp hài hòa và nữ tính. Thiết kế mang đến cảm giác thanh thoát, sang trọng, vừa ngọt ngào vừa quý phái, là món trang sức lý tưởng cho những dịp đặc biệt, tôn vinh vẻ đẹp duyên dáng và tinh tế của người đeo.', 'bt05.jpg', 3, 2, '1', '2026-02-25 16:08:10'),
(81, 'Bông Tai Giọt Sáng Kim Cương', 'PNJBT006', 11000000.00, NULL, 'Vàng trắng ', 'Không', 2.40, 'Đôi hoa tai sang trọng với viên kim cương tròn lớn rực rỡ được treo từ phần thân mảnh mai đính nhiều viên đá nhỏ lấp lánh. Thiết kế dạng thả dài mang đến sự thanh thoát, tinh tế và tôn vinh vẻ đẹp rạng ngời của người đeo. Sự kết hợp giữa sự tối giản và sự xa hoa tạo nên phong cách vừa hiện đại vừa quý phái, thích hợp cho những buổi tiệc sang trọng hoặc khoảnh khắc đặc biệt.', 'bt06.jpg', 3, 1, '1', '2026-02-25 16:08:10'),
(82, 'Bông Tai Vòng Ngọc Kim Cương', 'PNJBT007', 21000000.00, 20000000.00, 'Vàng 18K', 'Kim cương', 2.90, 'Đôi hoa tai vàng dạng vòng tròn sang trọng, điểm nhấn là viên kim cương tròn sáng lấp lánh treo ở giữa, được cố định trong khung viền tinh xảo. Thiết kế kết hợp sự mềm mại của vòng vàng bóng mượt với vẻ rực rỡ của đá quý, tạo nên phong cách vừa hiện đại vừa quý phái. Đây là món trang sức lý tưởng để tôn vinh sự thanh lịch và khẳng định phong cách thời thượng trong mọi dịp.', 'bt07.jpg', 3, 1, '1', '2026-02-25 16:08:10'),
(83, 'Bông Tai Hòa Âm Ánh Kim', 'PNJBT008', 7500000.00, NULL, 'Vàng 14K', 'Không', 2.10, 'Đôi hoa tai tinh xảo với thiết kế uốn lượn nhiều lớp, kết hợp sắc vàng và bạc xen kẽ tạo hiệu ứng phản chiếu sang trọng. Kiểu dáng cong mềm mại mang đến sự hiện đại nhưng vẫn giữ nét cổ điển, dễ dàng trở thành điểm nhấn nổi bật trong phong cách thời trang. Đây là món trang sức lý tưởng cho những ai yêu thích sự độc đáo, vừa thanh lịch vừa thời thượng.', 'bt08.jpg', 3, 1, '1', '2026-02-25 16:08:10'),
(84, 'Bông Tai Trái Tim Vàng Lấp Lánh', 'PNJBT009', 8900000.00, NULL, 'Vàng 18K', 'Đá CZ', 2.20, 'Đôi hoa tai vàng dạng vòng nhỏ đính đá sáng dọc viền, kết hợp cùng chuỗi mảnh tinh tế treo ba trái tim vàng nhỏ xinh. Thiết kế vừa nữ tính vừa sang trọng, mang đến vẻ đẹp duyên dáng và thanh lịch. Sự kết hợp giữa ánh sáng lấp lánh của đá quý và biểu tượng trái tim tạo nên ý nghĩa tình yêu, sự gắn kết và hạnh phúc. Đây là món trang sức lý tưởng cho những dịp đặc biệt, giúp người đeo tỏa sáng và khẳng định phong cách thời thượng.', 'bt09.jpg', 3, 1, '1', '2026-02-25 16:08:10'),
(85, 'Bông Tai Tháp Sáng Kim Cương', 'PNJBT010', 13500000.00, NULL, 'Vàng 18K', 'Kim cương', 2.70, 'Đôi hoa tai vàng sang trọng với thiết kế thả dài, nổi bật bởi viên đá tròn lớn ở phía dưới, phía trên là hàng năm viên đá nhỏ xếp dọc tinh xảo. Kiểu dáng thanh mảnh nhưng rực rỡ, tôn vinh sự cân đối và ánh sáng lấp lánh của đá quý. Đây là món trang sức mang phong cách hiện đại, quý phái, lý tưởng cho những buổi tiệc sang trọng hoặc khoảnh khắc đặc biệt, giúp người đeo tỏa sáng và khẳng định phong cách tinh tế.', 'bt10.jpg', 3, 1, '1', '2026-02-25 16:08:10'),
(86, 'Bông Tai Hoa Quang Vàng', 'PNJBT011', 17000000.00, 16000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 2.80, 'Đôi hoa tai vàng tinh xảo với thiết kế dạng thanh dọc đính đá lấp lánh, kết hợp cùng mặt hoa nhỏ phủ đầy đá quý sáng rực. Kiểu dáng vừa nữ tính vừa sang trọng, mang đến vẻ đẹp thanh thoát và quý phái. Sự kết hợp giữa ánh sáng của đá và sắc vàng sang trọng tạo nên phong cách hiện đại, tinh tế, lý tưởng cho những dịp đặc biệt. Đây là món trang sức giúp người đeo tỏa sáng và khẳng định phong cách thời thượng.', 'bt11.jpg', 3, 1, '1', '2026-02-25 16:08:10'),
(87, 'Bông Tai Khúc Vàng Song Sắc', 'PNJBT012', 8200000.00, NULL, 'Vàng 14K', 'Không', 2.00, 'Đôi hoa tai vòng nhỏ tinh xảo với thiết kế phân đoạn độc đáo, xen kẽ sắc vàng sang trọng và điểm nhấn xanh nhạt nhẹ nhàng. Kiểu dáng hiện đại nhưng vẫn giữ nét thanh lịch, tạo hiệu ứng phản chiếu nổi bật dưới ánh sáng. Đây là món trang sức mang phong cách trẻ trung, thời thượng, dễ dàng kết hợp với nhiều phong cách khác nhau, từ thanh lịch đến cá tính.', 'bt12.jpg', 3, 1, '1', '2026-02-25 16:08:10'),
(88, 'Bông Tai Lam Ngọc Quang Hoa', 'PNJBT013', 9500000.00, NULL, 'Vàng 18K', 'Đá CZ', 2.30, 'Đôi hoa tai vàng tinh xảo với viên đá xanh tròn ở trung tâm, được bao quanh bởi những viên đá trắng nhỏ xếp đối xứng, tạo nên hiệu ứng lấp lánh sang trọng. Thiết kế mang vẻ đẹp quý phái, vừa nổi bật vừa thanh lịch, tôn vinh sự tinh tế và sự rực rỡ của người đeo. Sự kết hợp giữa sắc xanh huyền bí và ánh sáng trong trẻo của đá trắng khiến đôi hoa tai trở thành điểm nhấn hoàn hảo cho những dịp đặc biệt.', 'bt13.jpg', 3, 1, '1', '2026-02-25 16:08:10'),
(89, 'Bông Tai Vầng Sáng Vàng', 'PNJBT014', 22000000.00, 21000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 3.00, 'Đôi hoa tai vàng tinh tế với phần vòng cong mềm mại phía dưới, kết hợp cùng phần trên thon gọn đính đá sáng lấp lánh. Thiết kế hài hòa giữa sự bóng mượt của vàng và ánh sáng lung linh của đá quý, tạo nên vẻ đẹp sang trọng và hiện đại. Đây là món trang sức lý tưởng để tôn vinh sự thanh lịch, giúp người đeo nổi bật trong những dịp đặc biệt.', 'bt14.jpg', 3, 1, '1', '2026-02-25 16:08:10'),
(90, 'Bông Tai Vòng Vàng Khắc Dấu', 'PNJBT015', 10500000.00, NULL, 'Vàng 18K', 'Không', 2.40, 'Đôi hoa tai vòng nhỏ màu vàng sang trọng với bề mặt bóng mượt, được trang trí bằng các họa tiết tròn đều đặn tựa như dấu khắc tinh xảo. Thiết kế đơn giản nhưng độc đáo, mang đến phong cách hiện đại xen lẫn nét cổ điển. Nền vải mềm mại càng làm nổi bật sự sang trọng, biến đôi hoa tai trở thành điểm nhấn thanh lịch và cá tính cho người đeo.', 'bt15.jpg', 3, 1, '1', '2026-02-25 16:08:10'),
(91, 'Bông Tai Hoa Kim Quang', 'PNJBT016', 14000000.00, NULL, 'Vàng 18K', 'Kim cương', 2.60, 'Đôi hoa tai vàng tinh xảo với cụm đá nhỏ sáng rực rỡ được sắp xếp thành hình hoa, tạo nên vẻ đẹp nữ tính và sang trọng. Thiết kế mang phong cách thanh lịch, kết hợp ánh sáng lung linh của đá quý với sắc vàng quý phái, khiến đôi hoa tai trở thành điểm nhấn hoàn hảo cho những dịp đặc biệt. Đây là món trang sức lý tưởng để tôn vinh sự duyên dáng và khẳng định phong cách thời thượng của người đeo.', 'bt16.jpg', 3, 1, '1', '2026-02-25 16:08:10'),
(92, 'Bông Tai Cỏ Bốn Lá Vàng', 'PNJBT017', 7200000.00, NULL, 'Vàng 14K', 'Không', 2.10, 'Đôi hoa tai vàng tinh xảo với thiết kế hình cỏ bốn lá, từng chi tiết được chạm khắc tỉ mỉ tạo hiệu ứng tỏa sáng từ tâm. Bề mặt bóng mượt kết hợp cùng hoa văn lan tỏa mang đến vẻ đẹp vừa cổ điển vừa hiện đại. Đây là món trang sức mang ý nghĩa may mắn, hạnh phúc và thịnh vượng, đồng thời khẳng định phong cách sang trọng và tinh tế của người đeo.', 'bt17.jpg', 3, 1, '1', '2026-02-25 16:08:10'),
(93, 'Bông Tai Vòng Hoa Ngọc Quang', 'PNJBT018', 16500000.00, 15500000.00, 'Vàng 18K', 'Kim cương', 2.70, 'Đôi hoa tai vòng nhỏ bằng vàng, điểm xuyết cụm hoa đá sáng rực rỡ treo duyên dáng. Thiết kế kết hợp sự mềm mại của vòng tròn với vẻ lấp lánh của hoa đá, mang đến phong cách vừa nữ tính vừa sang trọng. Đây là món trang sức tinh tế, dễ dàng trở thành điểm nhấn trong những dịp đặc biệt, giúp người đeo tỏa sáng và khẳng định phong cách thời thượng.', 'bt18.jpg', 3, 1, '1', '2026-02-25 16:08:10'),
(94, 'Bông Tai Tháp Ngọc Rực Rỡ', 'PNJBT019', 900000.00, NULL, 'Bạc 925', 'Đá CZ', 1.60, 'Đôi hoa tai vàng sang trọng với viên đá tròn lớn ở phía dưới, phía trên là hàng năm viên đá nhỏ xếp dọc tinh tế. Thiết kế thanh mảnh nhưng nổi bật, tôn vinh ánh sáng lấp lánh và sự cân đối hoàn hảo. Đây là món trang sức mang phong cách hiện đại, quý phái, lý tưởng cho những buổi tiệc sang trọng hoặc khoảnh khắc đặc biệt, giúp người đeo tỏa sáng và khẳng định phong cách tinh tế.', 'bt19.jpg', 3, 2, '1', '2026-02-25 16:08:10'),
(95, 'Bông Tai Trái Tim Ánh Bạc', 'PNJBT020', 1300000.00, NULL, 'Bạc 925', 'Không', 1.70, 'Đôi hoa tai bạc hình trái tim rỗng, viền ngoài đính đá nhỏ lấp lánh, mang đến vẻ đẹp tinh tế và nữ tính. Thiết kế nhẹ nhàng nhưng sang trọng, dễ dàng trở thành điểm nhấn trong phong cách thường ngày lẫn những dịp đặc biệt. Sự kết hợp giữa hình trái tim – biểu tượng tình yêu – và ánh sáng lung linh của đá quý khiến đôi hoa tai trở thành món trang sức đầy ý nghĩa và cuốn hút', 'bt20.jpg', 3, 2, '1', '2026-02-25 16:08:10'),
(96, 'Bông Tai Vầng Ngọc Song Hoàn', 'PNJBT021', 17500000.00, NULL, 'Vàng 18K', 'Kim cương', 2.90, 'Đôi hoa tai vàng tinh xảo với phần trên là vòng tròn nhỏ đính đá sáng, kết hợp cùng vòng tròn lớn hơn phía dưới có họa tiết bề mặt độc đáo. Thiết kế mang tính hình học hiện đại nhưng vẫn giữ nét sang trọng, tạo hiệu ứng phản chiếu nổi bật dưới ánh sáng. Đây là món trang sức lý tưởng cho những ai yêu thích sự cân bằng giữa tinh tế và cá tính, giúp người đeo tỏa sáng trong mọi dịp đặc biệt.', 'bt21.jpg', 3, 1, '1', '2026-02-25 16:08:10'),
(97, 'Bông Tai Hoàn Vàng Khắc Cạnh', 'PNJBT022', 8800000.00, NULL, 'Vàng 14K', 'Không', 2.20, 'Đôi hoa tai vòng nhỏ bằng vàng với thiết kế hình học đa diện, bề mặt cắt khía tinh xảo tạo hiệu ứng phản chiếu ánh sáng rực rỡ. Kiểu dáng đơn giản nhưng hiện đại, mang đến phong cách sang trọng và thanh lịch. Đây là món trang sức lý tưởng cho những ai yêu thích sự tinh tế, dễ dàng kết hợp với nhiều phong cách thời trang khác nhau, từ thường ngày đến những dịp đặc biệt.', 'bt22.jpg', 3, 1, '1', '2026-02-25 16:08:10'),
(98, 'Bông Tai Ong Vàng Ngọc Sáng', 'PNJBT023', 24000000.00, 23000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 3.10, 'Đôi hoa tai vàng hình chú ong nhỏ, toàn thân được đính đá sáng lấp lánh, cánh và thân ong được chế tác tinh xảo, tạo nên vẻ đẹp vừa sang trọng vừa độc đáo. Thiết kế lấy cảm hứng từ thiên nhiên, mang ý nghĩa về sự chăm chỉ, may mắn và sức sống. Đây là món trang sức lý tưởng cho những ai yêu thích phong cách tinh tế, khác biệt, đồng thời muốn khẳng định cá tính thời thượng.', 'bt23.jpg', 3, 1, '1', '2026-02-25 16:08:10'),
(99, 'Bông Tai Giọt Ngọc Lấp Lánh', 'PNJBT024', 950000.00, NULL, 'Bạc 925', 'Đá CZ', 1.50, 'Đôi hoa tai bạc sang trọng với thiết kế giọt lệ mềm mại, trung tâm là viên đá tròn lớn sáng rực rỡ, được bao quanh bởi những viên đá nhỏ tinh xảo. Phần nối phía trên cũng điểm xuyết đá sáng, tạo sự liên kết hài hòa và tôn vinh vẻ đẹp thanh lịch. Đây là món trang sức mang phong cách quý phái, lý tưởng cho những buổi tiệc sang trọng hoặc khoảnh khắc đặc biệt, giúp người đeo tỏa sáng và khẳng định phong cách tinh tế.', 'bt24.jpg', 3, 2, '1', '2026-02-25 16:08:10'),
(100, 'Bông Tai Ngọc Quang Song Viên', 'PNJBT025', 15000000.00, NULL, 'Vàng 18K', 'Kim cương', 2.80, 'Đôi hoa tai vàng sang trọng với thiết kế hai phần nổi bật: vòng oval trên đính đá sáng lấp lánh, kết nối với mặt tròn trung tâm được bao quanh bởi những viên đá nhỏ tinh xảo. Sự kết hợp hài hòa giữa hình khối thanh lịch và ánh sáng lung linh tạo nên vẻ đẹp quý phái, tinh tế. Đây là món trang sức lý tưởng cho những dịp đặc biệt, giúp người đeo tỏa sáng và khẳng định phong cách thời thượng.', 'bt25.jpg', 3, 1, '1', '2026-02-25 16:08:10'),
(101, 'Vòng Tay Làn Sóng Ngọc Vàng', 'PNJVT001', 16500000.00, 15500000.00, 'Vàng 18K', 'Kim cương', 6.20, 'Chiếc vòng tay vàng kiểu cuff sang trọng, điểm xuyết bằng những viên đá vuông sáng rực rỡ xếp theo đường zigzag tinh xảo. Thiết kế mở hiện đại, vừa mạnh mẽ vừa thanh lịch, tạo hiệu ứng phản chiếu ánh sáng lung linh trên nền vàng quý phái. Đây là món trang sức lý tưởng để khẳng định phong cách thời thượng, giúp người đeo nổi bật trong mọi dịp đặc biệt.', 'vt01.jpg', 4, 1, '1', '2026-02-25 16:09:47'),
(102, 'Vòng Tay Hoàn Vàng Song Sắc', 'PNJVT002', 14000000.00, NULL, 'Vàng 18K', 'Không', 5.80, 'Chiếc vòng tay vàng kiểu bangle với thiết kế xen kẽ các ô trắng chữ nhật và đá sáng nhỏ, tạo nên nhịp điệu tinh tế quanh cổ tay. Bề mặt bóng mượt kết hợp cùng chi tiết đính đá mang đến vẻ đẹp sang trọng nhưng tối giản, dễ dàng phối hợp với nhiều phong cách thời trang. Đây là món trang sức lý tưởng cho những ai yêu thích sự thanh lịch hiện đại, vừa tinh tế vừa nổi bật.', 'vt02.jpg', 4, 1, '1', '2026-02-25 16:09:47'),
(103, 'Vòng Tay Hòa Điệu Ngọc Quang', 'PNJVT003', 28000000.00, 27000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 6.50, 'Chiếc vòng tay vàng kiểu bangle sang trọng, kết hợp xen kẽ các ô men trắng chữ nhật và hàng đá tròn nhỏ sáng lấp lánh. Thiết kế hiện đại, mang tính hình học tinh tế, vừa tối giản vừa quý phái. Bề mặt vàng bóng mượt cùng ánh sáng lung linh của đá tạo nên vẻ đẹp thanh lịch, dễ dàng trở thành điểm nhấn trong phong cách thời trang thời thượng. Đây là món trang sức lý tưởng cho những ai yêu thích sự tinh tế và sang trọng.', 'vt03.jpg', 4, 1, '1', '2026-02-25 16:09:47'),
(104, 'Vòng Tay Ngọc Trăng Vàng', 'PNJVT004', 8500000.00, NULL, 'Vàng 18K', 'Ngọc trai', 6.00, 'Chiếc vòng tay thanh mảnh với thiết kế tinh tế, kết hợp xen kẽ những viên ngọc trai trắng sáng và hạt vàng nhỏ óng ánh. Sự đối lập giữa sắc trắng tinh khôi và ánh vàng sang trọng tạo nên vẻ đẹp hài hòa, vừa lãng mạn vừa quý phái. Đây là món trang sức lý tưởng cho những ai yêu thích phong cách thanh lịch, dễ dàng trở thành điểm nhấn trong cả trang phục thường ngày lẫn những dịp đặc biệt.', 'vt04.jpg', 4, 1, '1', '2026-02-25 16:09:47'),
(105, 'Vòng Tay Ánh Sáng Tinh Khôi', 'PNJVT005', 2200000.00, 2000000.00, 'Bạc 925', 'Đá CZ', 4.20, 'Chiếc vòng tay bạc thanh mảnh, điểm xuyết hàng đá sáng lấp lánh chạy dọc phía trước, tạo hiệu ứng phản chiếu tinh tế. Thiết kế có dây điều chỉnh kèm charm hình trái tim nhỏ ở cuối, vừa nữ tính vừa sang trọng. Đây là món trang sức mang vẻ đẹp tinh khôi, hiện đại, dễ dàng trở thành quà tặng ý nghĩa hoặc điểm nhấn trong phong cách thời trang thanh lịch.', 'vt05.jpg', 4, 2, '1', '2026-02-25 16:09:47'),
(106, 'Vòng Tay Nơ Ngọc Thanh Khiết', 'PNJVT006', 17500000.00, NULL, 'Vàng trắng ', 'Không', 6.10, 'Chiếc vòng tay bạc tinh tế với thiết kế uốn lượn nhẹ nhàng, tạo cảm giác mềm mại và nữ tính. Điểm nhấn là hai charm nhỏ gần khóa: một hình nơ duyên dáng và một hạt tròn sáng bóng, mang đến sự kết hợp hài hòa giữa sự thanh lịch và nét đáng yêu. Đây là món trang sức lý tưởng để làm quà tặng hoặc phụ kiện cho những dịp đặc biệt, giúp người đeo khẳng định phong cách tinh tế và sang trọng.', 'vt06.jpg', 4, 1, '1', '2026-02-25 16:09:47'),
(107, 'Vòng Tay Vĩnh Hằng Ngọc Quang', 'PNJVT007', 30000000.00, 28500000.00, 'Vàng 18K', 'Kim cương', 6.80, 'Chiếc vòng tay vàng sang trọng với thiết kế xen kẽ mắt xích hình vô cực và vòng tròn, mỗi mắt xích đều được đính đá sáng lấp lánh. Sự kết hợp tinh tế giữa biểu tượng vô cực – tượng trưng cho tình yêu và sự vĩnh cửu – cùng ánh sáng lung linh của đá quý tạo nên vẻ đẹp quý phái, hiện đại. Đây là món trang sức lý tưởng cho những dịp đặc biệt, giúp người đeo khẳng định phong cách sang trọng và tinh tế.', 'vt07.jpg', 4, 1, '1', '2026-02-25 16:09:47'),
(108, 'Vòng Tay Nút Thắt Vàng', 'PNJVT008', 12000000.00, NULL, 'Vàng 14K', 'Không', 5.00, 'Chiếc vòng tay vàng kiểu mở với thiết kế tối giản, điểm nhấn là nút thắt nhỏ ở trung tâm, hai đầu chạm bi cầu tinh tế. Bề mặt vàng bóng mượt phản chiếu ánh sáng nhẹ nhàng, mang đến vẻ đẹp hiện đại nhưng vẫn sang trọng. Đây là món trang sức lý tưởng cho những ai yêu thích phong cách thanh lịch, tinh tế và dễ dàng phối hợp với nhiều trang phục khác nhau.', 'vt08.jpg', 4, 1, '1', '2026-02-25 16:09:47'),
(109, 'Vòng Tay Ánh Dương Khuyết', 'PNJVT009', 15500000.00, NULL, 'Vàng 18K', 'Đá CZ', 5.60, 'Không đi theo lối mòn của những thiết kế đối xứng, Duo-Stone Bangle gây ấn tượng mạnh bởi sự kết hợp ngẫu hứng giữa hai giác cắt đá Pear và Marquise rực rỡ. Thiết kế dạng vòng hở (Open Cuff) không chỉ mang lại sự hiện đại, trẻ trung mà còn giúp phái đẹp dễ dàng điều chỉnh vừa vặn với cổ tay. Đây là món phụ kiện hoàn hảo để tạo điểm nhấn cho bộ trang phục công sở thanh lịch hay những chiếc váy dạo phố đầy phong cách tại Luxury Jewelry.', 'vt09.jpg', 4, 1, '1', '2026-02-25 16:09:47'),
(110, 'Vòng Tay Song Lệ Hoàng Kim', 'PNJVT010', 19500000.00, NULL, 'Vàng 18K', 'Kim cương', 6.30, 'Vẻ đẹp kiêu sa từ những đường xoắn mang đến một định nghĩa mới về sự sang trọng với thân vòng được chế tác dạng xoắn thừng độc đáo, tạo độ bắt sáng đa chiều ở mọi góc nhìn. Hai viên đá Pear-cut rực rỡ ở hai đầu vòng như những giọt sương ban mai, tôn vinh nét thanh tú và quý phái của quý cô hiện đại. Thiết kế Open Cuff linh hoạt giúp bạn dễ dàng sử dụng và phối hợp cùng các món trang sức khác để tạo nên dấu ấn riêng biệt tại Luxury Jewelry.', 'vt10.jpg', 4, 1, '1', '2026-02-25 16:09:47'),
(111, 'Vòng Tay Ánh Dương Độc Bản', 'PNJVT011', 21000000.00, 20000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 6.40, 'Không cần đến những chi tiết rườm rà, Modern Solitaire Bangle khẳng định đẳng cấp qua bản vòng phẳng bóng gương hoàn hảo, làm nền cho viên đá chủ giác cắt tròn rực rỡ. Thiết kế chốt cài thông minh giúp vòng ôm sát cổ tay một cách êm ái, mang lại sự tự tin và phong thái chuyên nghiệp cho quý cô. Một món trang sức \"vượt thời gian\", dễ dàng đồng hành cùng bạn từ những buổi họp quan trọng đến những bữa tiệc tối sang trọng tại Luxury Jewelry.', 'vt11.jpg', 4, 1, '1', '2026-02-25 16:09:47'),
(112, 'Vòng Tay Nơ Xinh Xuống Phố', 'PNJVT012', 9800000.00, NULL, 'Vàng 14K', 'Không', 4.90, 'Lấy cảm hứng từ những dải ruy băng lụa mềm mại, Silk Ribbon Bangle là sự kết hợp hoàn hảo giữa nét chế tác 3D sống động và chất liệu vàng rực rỡ. Hình tượng chiếc nơ không chỉ là điểm nhấn phong cách mà còn tượng trưng cho sự gắn kết và những điều ngọt ngào trong cuộc sống. Thiết kế vòng hở linh hoạt giúp quý cô dễ dàng diện cùng trang phục hằng ngày hay những chiếc váy xòe điệu đà, khẳng định gu thẩm mỹ tinh tế tại Luxury Jewelry.', 'vt12.jpg', 4, 1, '1', '2026-02-25 16:09:47'),
(113, 'Vòng Tay Mosaic Ánh Kim:', 'PNJVT013', 14500000.00, NULL, 'Vàng 18K', 'Đá CZ', 5.40, 'Phá vỡ mọi quy tắc về sự đối xứng, Mosaic Bangle là lời tuyên ngôn cho gu thẩm mỹ độc bản của quý cô hiện đại. Từng viên đá với các giác cắt Round, Emerald và Heart được tuyển chọn kỹ lưỡng và sắp đặt tỉ mỉ trên nền vàng rực rỡ, tạo nên một dải hào quang đa chiều bao quanh cổ tay. Thiết kế dạng vòng hở mang lại sự tiện dụng và cá tính, giúp bạn dễ dàng trở thành tâm điểm của mọi ánh nhìn trong những buổi tiệc tối thượng lưu cùng Luxury Jewelry.', 'vt13.jpg', 4, 1, '1', '2026-02-25 16:09:47'),
(114, 'Vòng Tay Linh Xà Hoàng Kim', 'PNJVT014', 32000000.00, 31000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 7.00, 'Majestic Serpenti không chỉ là một món trang sức, mà là biểu tượng của sự quyến rũ đầy mê hoặc. Được chế tác tỉ mỉ với các đốt vảy vàng 18K đan xen dải đá tấm lấp lánh, chiếc vòng ôm trọn cổ tay bằng một sự mềm mại khó tin nhờ kỹ thuật cơ khí tinh vi bên trong. Thiết kế đầu rắn cách điệu nạm đá mang đến luồng ánh sáng rực rỡ, tôn vinh khí chất mạnh mẽ và vẻ đẹp đầy quyền năng của quý cô Luxury Jewelry.', 'vt14.jpg', 4, 1, '1', '2026-02-25 16:09:47'),
(115, 'Vòng Tay Infinity Bản Phẳng', 'PNJVT015', 13500000.00, NULL, 'Vàng 18K', 'Không', 5.30, 'Không chỉ đơn thuần là một món trang sức, Modern Infinity Bangle là lời khẳng định về một phong thái tự tin và tầm nhìn không giới hạn. Bản vòng phẳng với bề mặt bóng gương tinh xảo làm nền cho biểu tượng vô cực được chế tác tỉ mỉ, tạo điểm nhấn đầy cuốn hút trên cổ tay. Với thiết kế chốt cài kín đáo và chắc chắn, đây là món phụ kiện hoàn hảo để quý cô diện hằng ngày, mang lại năng lượng tích cực và sự sang trọng bền vững tại Luxury Jewelry.', 'vt15.jpg', 4, 1, '1', '2026-02-25 16:09:47'),
(116, '“Vòng Tennis Ánh Kim Vĩnh Cửu', 'PNJVT016', 18000000.00, NULL, 'Vàng 18K', 'Kim cương', 6.00, 'Chiếc vòng tay sang trọng này được chế tác tinh xảo từ vàng cao cấp, điểm xuyết bằng hàng loạt viên đá quý tròn sáng lấp lánh, tạo nên một dải ánh sáng liên tục như dòng chảy của thời gian. Mỗi viên đá được gắn kết hoàn hảo trong khung kim loại đối xứng, phản chiếu ánh sáng dịu dàng từ nền vải satin màu champagne, làm nổi bật vẻ đẹp thanh lịch và tinh tế của món trang sức.\r\n\r\nThiết kế vòng tennis cổ điển mang hơi thở hiện đại, tượng trưng cho sự bền bỉ, sức mạnh và vẻ đẹp vượt thời gian. Chiếc khóa cài chắc chắn thể hiện sự tỉ mỉ trong từng chi tiết, đảm bảo vừa vặn và an toàn khi đeo. Đây là món phụ kiện lý tưởng cho những ai yêu thích phong cách tinh tế, sang trọng nhưng vẫn muốn giữ nét nhẹ nhàng, thanh thoát.', 'vt16.jpg', 4, 1, '1', '2026-02-25 16:09:47'),
(117, 'Vòng Tay Trái  Tim Gắn Kết', 'PNJVT017', 8500000.00, NULL, 'Vàng 14K', 'Không', 4.70, 'Chiếc vòng tay bằng vàng nổi bật với thiết kế dây xoắn tinh tế, mang đến cảm giác vừa mạnh mẽ vừa mềm mại. Điểm nhấn đặc biệt là chiếc charm hình trái tim nhỏ xinh treo ở phần khóa, tượng trưng cho tình yêu, sự gắn bó và niềm hạnh phúc giản dị. Bề mặt vàng sáng bóng phản chiếu ánh sáng lung linh, tạo nên vẻ sang trọng và cuốn hút.\r\n\r\nNền đen huyền bí càng làm nổi bật sự tinh xảo trong từng chi tiết: từ đường xoắn mềm mại của dây vòng cho đến độ mịn màng hoàn hảo của trái tim. Đây không chỉ là một món trang sức, mà còn là lời nhắn gửi đầy ý nghĩa – dành cho những ai muốn lưu giữ tình cảm, hoặc làm quà tặng để thể hiện sự trân trọng và yêu thương.', 'vt17.jpg', 4, 1, '1', '2026-02-25 16:09:47'),
(118, 'Vòng Tay Ánh Kim Giao Thoa', 'PNJVT018', 24000000.00, 23000000.00, 'Vàng 18K', 'Kim cương', 6.60, 'Chiếc vòng tay bằng vàng mang thiết kế tinh tế với hai dải kim loại uốn cong giao nhau ở phần trung tâm, tạo nên điểm nhấn độc đáo và đầy nghệ thuật. Nơi giao thoa ấy được tô điểm bằng những viên đá sáng lấp lánh, tựa như những ngôi sao nhỏ phản chiếu ánh sáng, làm nổi bật vẻ sang trọng và quý phái. Các đường viền bên ngoài cũng được đính đá đều đặn, tạo nên sự cân đối và hài hòa trong tổng thể.\r\n\r\nNền màu be nhẹ nhàng cùng chi tiết trang trí trắng và chiếc lá xanh càng làm nổi bật vẻ đẹp thanh lịch của vòng tay, khiến nó trở thành món trang sức lý tưởng cho những ai yêu thích sự tinh xảo và sang trọng. Đây không chỉ là một phụ kiện thời trang, mà còn là biểu tượng của sự giao hòa – giữa hiện đại và cổ điển, giữa sức mạnh và sự mềm mại.', 'vt18.jpg', 4, 1, '1', '2026-02-25 16:09:47');
INSERT INTO `sanpham` (`id`, `ten_sp`, `ma_sp`, `gia`, `gia_khuyen_mai`, `chat_lieu`, `da_chinh`, `trong_luong`, `mo_ta`, `hinh_anh`, `danh_muc_id`, `thuong_hieu_id`, `trang_thai`, `ngay_tao`) VALUES
(119, 'Vòng Tay Nút Thắt Vĩnh Hằng', 'PNJVT019', 1800000.00, NULL, 'Bạc 925', 'Đá CZ', 4.00, 'Chiếc vòng tay bạc  mang thiết kế dạng vòng hở hiện đại, với hai dải song song được đính đầy những viên đá sáng lấp lánh, tạo nên hiệu ứng ánh sáng tinh tế và sang trọng. Tại trung tâm, hai dải vòng giao nhau bằng chi tiết nút thắt, cũng được phủ kín đá quý, tượng trưng cho sự gắn kết bền chặt và tình yêu vĩnh cửu.\r\n\r\nNền vải satin màu champagne cùng chiếc hộp sang trọng càng làm nổi bật vẻ đẹp thanh lịch của vòng tay, khiến nó trở thành món trang sức lý tưởng cho những ai yêu thích sự tinh xảo và đẳng cấp. Đây không chỉ là một phụ kiện thời trang, mà còn là biểu tượng của sự kết nối – giữa con người với con người, giữa phong cách hiện đại và giá trị truyền thống.', 'vt19.jpg', 4, 2, '1', '2026-02-25 16:09:47'),
(120, 'Vòng Tay Bạc Giao Thoa Tinh Khôi', 'PNJVT020', 1500000.00, NULL, 'Bạc 925', 'Không', 3.80, 'Chiếc vòng tay bạc mang phong cách tối giản nhưng đầy nghệ thuật, với thiết kế dạng vòng hở hiện đại. Hai đầu vòng được kết thúc bằng những viên bi nhỏ xinh, tạo điểm nhấn tinh tế và mềm mại. Phần thân vòng uốn lượn bất quy tắc, gợi cảm giác tự nhiên và phóng khoáng, như dòng chảy của sự sáng tạo không ngừng.\r\n\r\nBề mặt kim loại sáng bóng phản chiếu ánh sáng trên nền trắng tinh khôi, làm nổi bật vẻ đẹp thanh lịch và sang trọng. Thiết kế này vừa đơn giản, vừa độc đáo, phù hợp cho những ai yêu thích sự tinh tế nhưng vẫn muốn thể hiện cá tính riêng biệt. Đây không chỉ là một món trang sức, mà còn là biểu tượng của sự tự do, sự cân bằng giữa giản dị và nghệ thuật.', 'vt20.jpg', 4, 2, '1', '2026-02-25 16:09:47'),
(121, 'Vòng Tennis Kim Cương Vàng', 'PNJVT021', 22000000.00, NULL, 'Vàng 18K', 'Kim cương', 6.50, 'Chiếc vòng tay vàng tinh xảo mang phong cách tennis bracelet cổ điển, được chế tác từ vàng cao cấp và đính liên tục những viên đá tròn trắng sáng (kim cương hoặc đá quý nhân tạo) dọc theo toàn bộ chiều dài. Sự sắp xếp đều đặn và cân đối của các viên đá tạo nên một dải ánh sáng lung linh, phản chiếu vẻ đẹp sang trọng và thanh lịch.\r\n\r\nKhóa cài chắc chắn, bề mặt vàng bóng mịn cùng độ chính xác trong từng chi tiết thể hiện tay nghề thủ công bậc thầy. Thiết kế đơn giản nhưng đầy tinh tế này không chỉ tôn lên vẻ đẹp quý phái của người đeo, mà còn là biểu tượng của sự bền bỉ và phong cách vượt thời gian.\r\n\r\nĐây là món trang sức lý tưởng cho những dịp đặc biệt, từ tiệc sang trọng đến những khoảnh khắc đời thường, giúp người sở hữu luôn toát lên sự tự tin và đẳng cấp.', 'vt21.jpg', 4, 1, '1', '2026-02-25 16:09:47'),
(122, 'Vòng Tay Vàng Xoắn Thanh Lịch', 'PNJVT022', 11000000.00, NULL, 'Vàng 14K', 'Không', 5.10, 'Chiếc vòng tay vàng mang thiết kế xoắn độc đáo, tạo nên vẻ đẹp vừa hiện đại vừa nghệ thuật. Hai đầu vòng bo tròn mềm mại, kết hợp cùng đường xoắn tinh tế, gợi cảm giác uyển chuyển và sang trọng. Bề mặt vàng sáng bóng phản chiếu ánh sáng trên nền vải satin và hộp xám, làm nổi bật sự tinh xảo trong từng chi tiết.\r\n\r\nThiết kế này mang phong cách tối giản nhưng đầy cuốn hút, phù hợp cho những ai yêu thích sự thanh lịch và muốn thể hiện cá tính riêng. Vòng tay không chỉ là một món phụ kiện thời trang, mà còn là biểu tượng của sự cân bằng – giữa sự mạnh mẽ và mềm mại, giữa nghệ thuật và sự tinh tế.', 'vt22.jpg', 4, 1, '1', '2026-02-25 16:09:47'),
(123, 'Vòng Tay Hoa Vàng Lấp Lánh', 'PNJVT023', 35000000.00, 34000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 7.20, 'Chiếc vòng tay vàng tinh xảo mang thiết kế điểm nhấn là họa tiết hoa ở trung tâm, được đính những viên đá sáng lấp lánh tạo thành cánh hoa mềm mại và nhụy hoa rực rỡ. Các chi tiết nhỏ được chế tác tỉ mỉ, phản chiếu ánh sáng lung linh, làm nổi bật vẻ đẹp sang trọng và nữ tính. Phần thân vòng uốn cong thanh thoát, kết hợp cùng bề mặt vàng bóng mịn, tạo nên sự hài hòa giữa sự tinh tế và quý phái.\r\n\r\nKhóa cài chắc chắn, đường nét mềm mại và sự cân đối hoàn hảo khiến chiếc vòng trở thành món trang sức lý tưởng cho những ai yêu thích phong cách thanh lịch nhưng vẫn muốn giữ nét độc đáo riêng. Nền màu be ấm áp càng làm nổi bật sắc vàng sang trọng, khiến chiếc vòng trở thành biểu tượng của sự tinh khôi, tình yêu và vẻ đẹp vượt thời gian.\r\n\r\nĐây không chỉ là một phụ kiện thời trang, mà còn là món quà ý nghĩa – dành tặng cho những khoảnh khắc đặc biệt, như lời nhắn gửi về sự trân trọng và tình cảm vĩnh cửu.', 'vt23.jpg', 4, 1, '1', '2026-02-25 16:09:47'),
(124, 'Vòng Tay Bạc Hoa Sáng', 'PNJVT024', 2000000.00, NULL, 'Bạc 925', 'Đá CZ', 4.30, 'Chiếc vòng tay bạc tinh tế được thiết kế với hàng đá sáng lấp lánh chạy dọc phần mặt trước, tạo nên hiệu ứng ánh sáng lung linh và sang trọng. Phần dây vòng mang dáng vẻ thanh mảnh, bóng mịn, kết hợp cùng khóa cài và dây điều chỉnh tiện lợi, giúp phù hợp với nhiều kích thước cổ tay khác nhau.\r\n\r\nSự kết hợp giữa kim loại sáng bóng và những viên đá nhỏ li ti mang lại vẻ đẹp vừa hiện đại vừa cổ điển, khiến chiếc vòng trở thành điểm nhấn hoàn hảo cho mọi phong cách. Nền màu be nhẹ nhàng cùng chi tiết ruy băng mềm mại càng làm nổi bật sự tinh xảo và đẳng cấp của món trang sức.\r\n\r\nĐây không chỉ là một phụ kiện thời trang, mà còn là biểu tượng của sự thanh lịch và tinh khôi. Vòng tay bạc đính đá này sẽ là lựa chọn lý tưởng cho những dịp đặc biệt, hoặc làm món quà ý nghĩa dành tặng người thân yêu, như lời nhắn gửi về sự trân trọng và tình cảm bền lâu.', 'vt24.jpg', 4, 2, '1', '2026-02-25 16:09:47'),
(125, 'Vòng Tay Vàng Messika Ánh Sáng', 'PNJVT025', 19500000.00, NULL, 'Vàng 18K', 'Kim cương', 6.10, 'Chiếc vòng tay vàng tinh tế mang thiết kế hiện đại với sự kết hợp hài hòa giữa các đĩa tròn vàng bóng mịn và những viên kim cương đính theo kiểu bezel sáng lấp lánh. Sự xen kẽ nhịp nhàng giữa vàng và đá quý tạo nên hiệu ứng ánh sáng lung linh, vừa sang trọng vừa trẻ trung. Phần khóa lobster chắc chắn cùng tag nhỏ khắc tên thương hiệu MESSIKA khẳng định đẳng cấp và sự tinh xảo trong từng chi tiết.\r\n\r\nThiết kế này không chỉ tôn vinh vẻ đẹp thanh lịch mà còn mang đến sự khác biệt độc đáo, phù hợp cho những ai yêu thích phong cách thời thượng nhưng vẫn muốn giữ nét tinh tế. Vòng tay Messika là biểu tượng của sự sang trọng vượt thời gian, đồng hành cùng người đeo trong mọi khoảnh khắc – từ những buổi tiệc trang trọng đến những ngày thường giản dị.\r\n\r\nĐây là món trang sức lý tưởng để khẳng định phong cách cá nhân, đồng thời cũng là món quà đầy ý nghĩa dành tặng cho người thân yêu, như lời nhắn gửi về sự trân trọng và tình cảm vĩnh cửu.', 'vt25.jpg', 4, 1, '1', '2026-02-25 16:09:47'),
(126, 'Bộ Trang Sức Vàng Ánh Quang', 'PNJSET001', 35000000.00, 34000000.00, 'Vàng 18K', 'Kim cương', 12.50, 'Bộ trang sức gồm vòng cổ và đôi bông tai vàng tinh xảo, mang thiết kế hình tròn độc đáo. Phần trên của mỗi mặt trang sức là vàng trơn bóng mịn, trong khi nửa dưới được đính những viên đá cắt baguette xếp thành hình quạt, tạo nên hiệu ứng ánh sáng lung linh và sang trọng. Vòng cổ với dây vàng mảnh mai, kết hợp cùng đôi bông tai khóa gập chắc chắn, mang lại sự hài hòa và thanh lịch.\r\n\r\nSự kết hợp giữa vàng sáng bóng và đá quý trong bố cục cân đối khiến bộ trang sức trở thành điểm nhấn hoàn hảo cho phong cách hiện đại nhưng vẫn giữ nét cổ điển. Nền trắng tinh khôi càng làm nổi bật vẻ đẹp sang trọng, giúp bộ trang sức tỏa sáng trong mọi hoàn cảnh – từ những buổi tiệc sang trọng đến những khoảnh khắc đời thường.\r\n\r\nĐây không chỉ là phụ kiện thời trang, mà còn là biểu tượng của sự tinh tế và đẳng cấp. Bộ trang sức vàng ánh quang sẽ là lựa chọn lý tưởng cho những ai muốn khẳng định phong cách riêng, đồng thời cũng là món quà đầy ý nghĩa dành tặng người thân yêu.', 'set1.jpg', 5, 1, '1', '2026-02-25 16:13:13'),
(127, 'Bộ Trang Sức Vàng Lá Ngọc', 'PNJSET002', 28000000.00, 27000000.00, 'Vàng 18K', 'Ruby', 11.20, 'Bộ trang sức vàng tinh xảo gồm vòng cổ và đôi bông tai đồng bộ, mang thiết kế lá mềm mại đầy nghệ thuật. Mỗi chiếc lá được chạm khắc chi tiết gân nổi, tạo cảm giác tự nhiên và sống động, đồng thời phản chiếu ánh sáng nhẹ nhàng trên bề mặt vàng bóng mịn. Vòng cổ với dây mảnh thanh thoát kết hợp cùng mặt lá duyên dáng, trong khi đôi bông tai nhỏ gọn nhưng nổi bật, mang lại sự hài hòa và tinh tế.\r\n\r\nNền vải sáng màu càng làm nổi bật sắc vàng sang trọng, khiến bộ trang sức trở thành điểm nhấn hoàn hảo cho phong cách thanh lịch và nữ tính. Thiết kế lá tượng trưng cho sự tươi mới, sức sống và vẻ đẹp thuần khiết, phù hợp cho những ai yêu thích sự tinh tế nhưng vẫn muốn giữ nét độc đáo riêng.\r\n\r\nĐây không chỉ là phụ kiện thời trang, mà còn là món quà ý nghĩa – như lời nhắn gửi về sự trân trọng và tình yêu vĩnh cửu. Bộ trang sức vàng lá ngọc sẽ giúp người sở hữu tỏa sáng trong mọi khoảnh khắc, từ những buổi tiệc sang trọng đến những ngày thường giản dị.', 'set2.jpg', 5, 1, '1', '2026-02-25 16:13:13'),
(128, 'Bộ Trang Sức Bạc Nơ Ngọc', 'PNJSET003', 5500000.00, NULL, 'Bạc 925', 'Đá CZ', 8.50, 'Bộ trang sức bạc sang trọng gồm vòng cổ, nhẫn và đôi bông tai, mang thiết kế tinh tế với điểm nhấn là những viên đá quý sáng lấp lánh. Đôi bông tai và mặt dây chuyền nổi bật với viên đá vuông trong suốt, phía trên được tô điểm bằng chi tiết nơ nhỏ đính đá li ti, tạo nên vẻ đẹp nữ tính và duyên dáng. Chiếc nhẫn được chế tác với viên đá tròn ở trung tâm, bao quanh bởi những viên đá nhỏ dọc theo thân nhẫn, mang lại sự cân đối và sang trọng.\r\n\r\nSự kết hợp giữa đường nét mềm mại và ánh sáng lung linh từ đá quý tạo nên vẻ đẹp vừa hiện đại vừa cổ điển. Nền vải satin cùng cách bày trí tinh tế càng làm nổi bật sự đẳng cấp và tinh xảo của bộ trang sức. Đây là lựa chọn hoàn hảo cho những ai yêu thích phong cách thanh lịch, đồng thời muốn khẳng định cá tính riêng qua sự tinh tế trong từng chi tiết.\r\n\r\nBộ trang sức bạc nơ ngọc không chỉ là phụ kiện thời trang, mà còn là biểu tượng của sự sang trọng và tình yêu thuần khiết. Nó sẽ giúp người sở hữu tỏa sáng trong mọi khoảnh khắc – từ những buổi tiệc sang trọng đến những ngày thường giản dị.', 'set3.jpg', 5, 2, '1', '2026-02-25 16:13:13'),
(129, 'Bộ Trang Sức Vàng Oval Hoa Ngọc', 'PNJSET004', 18500000.00, NULL, 'Vàng 14K', 'Không', 10.00, 'Bộ trang sức vàng tinh xảo gồm vòng cổ và đôi bông tai đồng bộ, mang thiết kế oval sang trọng. Mỗi món đều được tô điểm bằng cụm đá sáng nhỏ xếp thành họa tiết hoa lá mềm mại ở một bên, tạo nên sự cân đối giữa sự thanh lịch và nét tự nhiên. Những viên đá lấp lánh phản chiếu ánh sáng lung linh, làm nổi bật sắc vàng bóng mịn và đường nét tinh tế.\r\n\r\nVòng cổ với dây mảnh thanh thoát kết hợp cùng mặt oval duyên dáng, trong khi đôi bông tai nhỏ gọn nhưng nổi bật, mang lại sự hài hòa và cuốn hút. Nền vải trắng tinh khôi càng làm nổi bật sự sang trọng, khiến bộ trang sức trở thành điểm nhấn hoàn hảo cho phong cách hiện đại nhưng vẫn giữ nét cổ điển.\r\n\r\nĐây không chỉ là phụ kiện thời trang, mà còn là biểu tượng của sự tinh tế và đẳng cấp. Bộ trang sức vàng oval hoa ngọc sẽ giúp người sở hữu tỏa sáng trong mọi khoảnh khắc – từ những buổi tiệc sang trọng đến những ngày thường giản dị, đồng thời cũng là món quà ý nghĩa dành tặng cho người thân yêu.', 'set4.jpg', 5, 1, '1', '2026-02-25 16:13:13'),
(130, 'Bộ Trang Sức Vàng Lam Ngọc', 'PNJSET005', 42000000.00, 41000000.00, 'Vàng 18K', 'Sapphire', 13.00, 'Bộ trang sức vàng sang trọng gồm vòng cổ và đôi bông tai đồng bộ, nổi bật với viên đá quý xanh lam hình chữ nhật được gắn trong khung vàng bốn chấu chắc chắn. Sắc xanh sâu thẳm của đá kết hợp cùng ánh vàng rực rỡ tạo nên sự tương phản đầy cuốn hút, vừa mạnh mẽ vừa tinh tế. Đôi bông tai còn được tô điểm thêm những viên đá trắng nhỏ ở phần gắn, mang lại sự lấp lánh nhẹ nhàng và cân đối.\r\n\r\nNền màu be ấm áp cùng chi tiết trang trí tự nhiên càng làm nổi bật vẻ đẹp thanh lịch và đẳng cấp của bộ trang sức. Thiết kế này mang hơi thở hiện đại nhưng vẫn giữ nét cổ điển, phù hợp cho những dịp đặc biệt, từ buổi tiệc sang trọng đến những khoảnh khắc quan trọng trong đời.\r\n\r\nĐây không chỉ là phụ kiện thời trang, mà còn là biểu tượng của sự quý phái và phong cách riêng. Bộ trang sức vàng lam ngọc sẽ giúp người sở hữu tỏa sáng, khẳng định cá tính và sự tự tin, đồng thời cũng là món quà đầy ý nghĩa dành tặng cho người thân yêu.', 'set5.jpg', 5, 1, '1', '2026-02-25 16:13:13'),
(131, 'Bộ Trang Sức Vàng Nút Thắt Thanh Lịch', 'PNJSET006', 25000000.00, NULL, 'Vàng 18K', 'Không', 9.80, 'Bộ trang sức vàng đồng bộ gồm vòng cổ, vòng tay và nhẫn, tất cả đều mang thiết kế nút thắt tròn tinh tế ở trung tâm. Kiểu dáng tối giản nhưng sang trọng, với dây mảnh và bề mặt vàng bóng mịn, tạo nên sự hài hòa và thanh lịch. Mỗi chi tiết đều phản chiếu ánh sáng nhẹ nhàng, làm nổi bật vẻ đẹp hiện đại nhưng vẫn giữ nét cổ điển.\r\n\r\nSự đồng bộ trong thiết kế giúp bộ trang sức trở thành điểm nhấn hoàn hảo, tôn vinh phong cách tinh tế và sự tự tin của người đeo. Hình ảnh nút thắt tượng trưng cho sự gắn kết, tình yêu và sự bền chặt, khiến bộ trang sức không chỉ là phụ kiện thời trang mà còn mang ý nghĩa sâu sắc.\r\n\r\nĐây là lựa chọn lý tưởng cho những ai yêu thích sự thanh lịch, muốn khẳng định phong cách riêng và đồng thời lưu giữ thông điệp về sự kết nối vĩnh cửu. Bộ trang sức vàng nút thắt thanh lịch sẽ giúp người sở hữu tỏa sáng trong mọi khoảnh khắc, từ công việc thường ngày đến những sự kiện đặc biệt.', 'set6.jpg', 5, 1, '1', '2026-02-25 16:13:13'),
(132, 'Bộ Trang Sức Vàng Giọt Ngọc', 'PNJSET007', 48000000.00, 47000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 14.20, 'Bộ trang sức vàng sang trọng gồm vòng cổ và đôi bông tai đồng bộ, mang thiết kế hình giọt nước tinh tế. Mỗi món đều nổi bật với viên đá tròn trong suốt ở trung tâm, được bao bọc bởi khung vàng mềm mại. Một đường cong đính đá nhỏ chạy dọc một bên giọt nước, tạo nên hiệu ứng ánh sáng lung linh và cân đối.\r\n\r\nVòng cổ với dây vàng mảnh mai kết hợp cùng mặt giọt nước duyên dáng, trong khi đôi bông tai mang cùng thiết kế, tạo sự hài hòa và đồng bộ. Nền vải be sang trọng càng làm nổi bật vẻ đẹp tinh xảo, khiến bộ trang sức trở thành điểm nhấn hoàn hảo cho phong cách thanh lịch và nữ tính.\r\n\r\nĐây không chỉ là phụ kiện thời trang, mà còn là biểu tượng của sự tinh tế và đẳng cấp. Bộ trang sức vàng giọt ngọc sẽ giúp người sở hữu tỏa sáng trong mọi khoảnh khắc – từ những buổi tiệc sang trọng đến những ngày thường giản dị, đồng thời cũng là món quà ý nghĩa dành tặng cho người thân yêu.', 'set7.jpg', 5, 1, '1', '2026-02-25 16:13:13'),
(133, 'Bộ Trang Sức Bạc Song Hoàn', 'PNJSET008', 6200000.00, NULL, 'Bạc 925', 'Không', 7.50, 'Bộ trang sức bạc tinh tế gồm vòng cổ, vòng tay và đôi bông tai đồng bộ, tất cả đều mang thiết kế hai vòng tròn lồng ghép – một vòng trơn bóng mịn và một vòng có bề mặt họa tiết. Sự kết hợp này tạo nên vẻ đẹp hài hòa giữa sự đơn giản và sự tinh xảo, tượng trưng cho sự gắn kết và cân bằng.\r\n\r\nVòng cổ với dây mảnh thanh thoát, vòng tay có dây điều chỉnh tiện lợi, và đôi bông tai nhỏ gọn nhưng nổi bật, tất cả đều phản chiếu ánh sáng lung linh trên nền tối sang trọng, làm nổi bật sự hiện đại và thanh lịch.\r\n\r\nThiết kế song hoàn không chỉ mang tính thẩm mỹ mà còn mang ý nghĩa sâu sắc – biểu tượng của sự kết nối, tình yêu và sự vĩnh cửu. Đây là bộ trang sức lý tưởng cho những ai yêu thích phong cách tối giản nhưng vẫn muốn khẳng định cá tính riêng.', 'set8.jpg', 5, 2, '1', '2026-02-25 16:13:13'),
(134, 'Bộ Trang Sức Vàng Hồng Ngọc', 'PNJSET009', 30000000.00, 29000000.00, 'Vàng 18K', 'Ruby', 11.80, 'Bộ trang sức vàng sang trọng gồm vòng cổ và đôi bông tai đồng bộ, nổi bật với viên đá đỏ hình vuông cắt sắc nét, được bao bọc trong khung vàng tinh xảo. Sắc đỏ rực rỡ của đá quý kết hợp cùng ánh vàng sang trọng tạo nên sự tương phản đầy cuốn hút, vừa mạnh mẽ vừa thanh lịch. Phía trên mỗi viên đá đỏ là một viên đá trắng nhỏ, mang lại điểm nhấn lấp lánh và cân đối, làm tăng thêm sự tinh tế cho thiết kế.\r\n\r\nNền satin trắng mềm mại càng làm nổi bật sắc đỏ và vàng, khiến bộ trang sức trở thành điểm nhấn hoàn hảo cho phong cách quý phái. Thiết kế này mang hơi thở hiện đại nhưng vẫn giữ nét cổ điển, phù hợp cho những dịp đặc biệt – từ buổi tiệc sang trọng đến những khoảnh khắc quan trọng trong đời.\r\n\r\nĐây không chỉ là phụ kiện thời trang, mà còn là biểu tượng của sự sang trọng và tình yêu nồng nhiệt. Bộ trang sức vàng hồng ngọc sẽ giúp người sở hữu tỏa sáng, khẳng định phong cách riêng và sự tự tin, đồng thời cũng là món quà đầy ý nghĩa dành tặng cho người thân yêu.', 'set9.jpg', 5, 1, '1', '2026-02-25 16:13:13'),
(135, 'Bộ Trang Sức Vàng Hoa Xuân', 'PNJSET010', 21000000.00, NULL, 'Vàng 14K', 'Không', 9.00, 'Bộ trang sức vàng tinh xảo gồm vòng cổ, vòng tay và đôi bông tai đồng bộ, tất cả đều mang thiết kế hoa nhỏ xinh với cánh tròn mềm mại. Mỗi bông hoa được chế tác cân đối, bề mặt vàng bóng mịn phản chiếu ánh sáng nhẹ nhàng, tạo nên vẻ đẹp thanh lịch và nữ tính. Vòng cổ nổi bật với chuỗi hoa liên kết trên dây vàng mảnh, vòng tay là dải hoa nối tiếp thành vòng tròn duyên dáng, trong khi đôi bông tai đơn giản nhưng tinh tế với một bông hoa duy nhất.\r\n\r\nNền vải sáng màu càng làm nổi bật sắc vàng sang trọng, khiến bộ trang sức trở thành điểm nhấn hoàn hảo cho phong cách hiện đại nhưng vẫn giữ nét cổ điển. Thiết kế hoa tượng trưng cho sự tươi mới, sức sống và vẻ đẹp thuần khiết, phù hợp cho những ai yêu thích sự tinh tế nhưng vẫn muốn khẳng định cá tính riêng.\r\n\r\nĐây không chỉ là phụ kiện thời trang, mà còn là món quà ý nghĩa – như lời nhắn gửi về sự trân trọng và tình yêu vĩnh cửu. Bộ trang sức vàng hoa xuân sẽ giúp người sở hữu tỏa sáng trong mọi khoảnh khắc, từ những buổi tiệc sang trọng đến những ngày thường giản dị.', 'set10.jpg', 5, 1, '1', '2026-02-25 16:13:13'),
(136, 'Vòng Tay Bạc Mèo May Mắn', 'PNJKID001', 650000.00, NULL, 'Bạc 925', 'Không', 2.00, 'Chiếc vòng bạc mèo may mắn dành cho bé, mang thiết kế nhỏ nhắn với charm mặt mèo đáng yêu. Ánh bạc sáng bóng kết hợp cùng chi tiết tinh xảo không chỉ tạo điểm nhấn thời trang, mà còn gửi gắm lời chúc bình an và niềm vui cho bé mỗi ngày.', 'kid1.jpg', 6, 2, '1', '2026-02-25 16:13:31'),
(137, 'Dây Chuyền Bạc Hello Kitty Bé Yêu', 'PNJKID002', 950000.00, NULL, 'Bạc 925', 'Đá CZ', 1.80, 'Chiếc vòng cổ bạc với mặt Hello Kitty này đúng là dòng trang sức trẻ em điển hình – vừa đáng yêu vừa mang tính biểu tượng. Thiết kế nhân vật quen thuộc khiến bé gái dễ dàng yêu thích, trong khi chất liệu bạc sáng bóng và những viên đá nhỏ lấp lánh tạo cảm giác sang trọng, phù hợp làm quà tặng trong các dịp đặc biệt.\r\n\r\nĐiểm cộng lớn là cách trình bày trong hộp nhung hồng và túi quà đồng bộ, giúp sản phẩm trở thành món quà hoàn hảo cho trẻ em – vừa an toàn, vừa tinh tế, lại gắn liền với nhân vật hoạt hình nổi tiếng.\r\n', 'kid2.jpg', 6, 2, '1', '2026-02-25 16:13:31'),
(138, 'Vòng Tay Bạc Cỏ Bốn Lá', 'PNJKID003', 720000.00, NULL, 'Bạc 925', 'Không', 2.20, 'Chiếc vòng tay bạc tinh tế với thiết kế hai dây song song, điểm xuyết những hạt bi nhỏ sáng bóng. Trung tâm nổi bật với ba charm hình cỏ bốn lá – biểu tượng của sự may mắn và hạnh phúc. Các chi tiết được chế tác tỉ mỉ, bề mặt bóng mịn phản chiếu ánh sáng nhẹ nhàng, mang lại vẻ đẹp thanh lịch nhưng vẫn trẻ trung.\r\n\r\nVòng tay có khóa chắc chắn, dễ dàng điều chỉnh, phù hợp cho cả người lớn và trẻ em. Đây không chỉ là phụ kiện thời trang, mà còn là món quà ý nghĩa – như lời chúc may mắn và bình an dành cho người thân yêu.', 'kid3.jpg', 6, 2, '1', '2026-02-25 16:13:31'),
(139, 'Khuyên Tai Nơ Bạc Bé Xinh', 'PNJKID004', 580000.00, NULL, 'Bạc 925', 'Đá CZ', 1.20, 'Đôi khuyên tai bạc nhỏ nhắn với thiết kế hình nơ duyên dáng, mang phong cách tối giản nhưng tinh tế. Bề mặt kim loại sáng bóng phản chiếu ánh sáng nhẹ nhàng, tạo nên vẻ đẹp thanh lịch và đáng yêu. Kích thước gọn gàng, phù hợp cho trẻ em hoặc những ai yêu thích sự nhẹ nhàng, nữ tính.\r\n\r\nĐây không chỉ là phụ kiện thời trang, mà còn là điểm nhấn xinh xắn giúp bé thêm tự tin và nổi bật trong mọi khoảnh khắc. Thích hợp làm quà tặng trong các dịp đặc biệt như sinh nhật, lễ hội hay phần thưởng khích lệ.', 'kid4.jpg', 6, 2, '1', '2026-02-25 16:13:31'),
(140, 'Nhẫn Bạc Trái Tim Bé Xinh', 'PNJKID005', 690000.00, NULL, 'Bạc 925', 'Không', 1.50, 'Chiếc nhẫn bạc thanh mảnh với thiết kế tối giản, nổi bật nhờ chi tiết trái tim mở ở phần trên. Đường nét mềm mại cùng ánh bạc sáng bóng mang lại vẻ đẹp tinh tế, nhẹ nhàng và đầy nữ tính. Kích thước nhỏ gọn, phù hợp cho trẻ em hoặc những ai yêu thích phong cách giản dị nhưng vẫn muốn giữ điểm nhấn đặc biệt.\r\n\r\nHình trái tim tượng trưng cho tình yêu và sự gắn kết, khiến chiếc nhẫn không chỉ là phụ kiện thời trang mà còn mang ý nghĩa tinh thần. Đây là món quà xinh xắn, thích hợp dành tặng bé trong các dịp đặc biệt như sinh nhật, lễ hội hay như một lời nhắn gửi yêu thương.', 'kid5.jpg', 6, 2, '1', '2026-02-25 16:13:31'),
(141, 'Vòng Tay Bạc Trái Tim Bé Xinh', 'PNJKID006', 750000.00, NULL, 'Bạc 925', 'Không', 2.40, 'Chiếc vòng tay bạc thanh lịch với thiết kế tối giản, gồm các mắt nối bóng mịn xen kẽ hạt tròn nhỏ. Điểm nhấn nằm ở charm hình trái tim treo giữa, mang ý nghĩa tượng trưng cho tình yêu và sự gắn kết. Ánh bạc sáng bóng phản chiếu nhẹ nhàng trên nền trung tính, làm nổi bật vẻ đẹp tinh tế và hiện đại.\r\n\r\nVòng tay có kiểu dáng gọn gàng, dễ đeo, phù hợp cho cả trẻ em và người lớn yêu thích phong cách nhẹ nhàng. Đây không chỉ là phụ kiện thời trang, mà còn là món quà ý nghĩa – như lời nhắn gửi yêu thương và sự trân trọng dành cho người thân yêu.', 'kid6.jpg', 6, 2, '1', '2026-02-25 16:13:31'),
(142, 'Dây Chuyền Bạc Trái Tim Niềm Tin', 'PNJKID007', 980000.00, NULL, 'Bạc 925', 'Đá CZ', 1.90, 'Chiếc dây chuyền bạc tinh tế với mặt hình trái tim, bên trong khắc họa chiếc xe đạp nhỏ xinh – biểu tượng cho hành trình và sự tự do. Viền ngoài trái tim được đính đá lấp lánh, một phần khắc dòng chữ truyền cảm hứng: “She believed she could so she did”. Thiết kế vừa mang tính thẩm mỹ, vừa chứa đựng thông điệp mạnh mẽ về niềm tin và nghị lực.\r\n\r\nNền vải màu cam đào mềm mại cùng điểm nhấn hoa khô càng làm nổi bật vẻ đẹp thanh lịch của món trang sức. Đây không chỉ là phụ kiện thời trang, mà còn là món quà ý nghĩa dành cho những ai đang theo đuổi ước mơ, như lời nhắn gửi khích lệ và động viên.', 'kid7.jpg', 6, 2, '1', '2026-02-25 16:13:31'),
(143, 'Vòng Tay Bạc Hoa Cúc Bé Xinh', 'PNJKID008', 800000.00, NULL, 'Bạc 925', 'Không', 2.30, 'Chiếc vòng tay bạc thanh mảnh với charm hoa cúc ở trung tâm, mang thiết kế tinh tế và đáng yêu. Những cánh hoa trắng nhỏ nhắn kết hợp cùng nhụy vàng nổi bật tạo nên vẻ đẹp tươi sáng, trong trẻo. Dây vòng gồm các mắt xích nhỏ gọn, có khóa điều chỉnh tiện lợi, phù hợp cho cổ tay bé gái.\r\n\r\nHình ảnh hoa cúc tượng trưng cho sự hồn nhiên, niềm vui và may mắn, khiến chiếc vòng không chỉ là phụ kiện thời trang mà còn là món quà ý nghĩa. Đây là lựa chọn hoàn hảo cho trẻ em trong các dịp đặc biệt như sinh nhật, lễ hội hoặc như một lời nhắn gửi yêu thương từ cha mẹ.', 'kid8.jpg', 6, 2, '1', '2026-02-25 16:13:31'),
(144, 'Khuyên Tai Bạc Nơ Xinh', 'PNJKID009', 600000.00, NULL, 'Bạc 925', 'Đá CZ', 1.30, 'Đôi khuyên tai bạc nhỏ nhắn với thiết kế hình nơ duyên dáng, mang phong cách tối giản nhưng tinh tế. Bề mặt kim loại sáng bóng phản chiếu ánh sáng nhẹ nhàng, tạo nên vẻ đẹp thanh lịch và đáng yêu. Kích thước gọn gàng, phù hợp cho trẻ em hoặc những ai yêu thích sự nhẹ nhàng, nữ tính.\r\n\r\nĐây không chỉ là phụ kiện thời trang, mà còn là điểm nhấn xinh xắn giúp bé thêm tự tin và nổi bật trong mọi khoảnh khắc. Thích hợp làm quà tặng trong các dịp đặc biệt như sinh nhật, lễ hội hay phần thưởng khích lệ.', 'kid9.jpg', 6, 2, '1', '2026-02-25 16:13:31'),
(145, 'Nhẫn Bạc Bướm Xinh', 'PNJKID010', 720000.00, NULL, 'Bạc 925', 'Không', 1.60, 'Chiếc nhẫn bạc tinh tế với thiết kế mở độc đáo, hai đầu nhẫn mang hai chi tiết trang trí khác nhau: một bên là chú bướm nhỏ với đôi cánh xanh men nổi bật, bên còn lại là hình cánh bướm nhỏ đính đá sáng lấp lánh. Sự kết hợp giữa sắc xanh dịu dàng và ánh sáng lung linh từ viên đá tạo nên vẻ đẹp hài hòa, vừa trẻ trung vừa sang trọng.\r\n\r\nKiểu dáng thanh mảnh, dễ đeo, phù hợp cho bé gái hoặc những ai yêu thích phong cách nhẹ nhàng, nữ tính. Hình ảnh bướm tượng trưng cho sự tự do và niềm vui, khiến chiếc nhẫn không chỉ là phụ kiện thời trang mà còn mang ý nghĩa tinh thần. Đây là món quà xinh xắn, thích hợp dành tặng trong các dịp đặc biệt như sinh nhật, lễ hội hay như một lời nhắn gửi yêu thương.', 'kid10.jpg', 6, 2, '1', '2026-02-25 16:13:31'),
(146, ' Nhẫn Cưới Vàng Gắn Kết', 'PNJWC001', 18500000.00, NULL, 'Vàng 18K', 'Không', 3.50, 'Cặp nhẫn cưới vàng đơn giản nhưng tinh tế, bề mặt bóng mượt phản chiếu ánh sáng sang trọng. Thiết kế tối giản mang ý nghĩa về sự thuần khiết và vĩnh cửu, tượng trưng cho tình yêu và sự gắn kết bền chặt. Đây là lựa chọn hoàn hảo cho các cặp đôi, vừa mang giá trị thẩm mỹ vừa chứa đựng thông điệp thiêng liêng về hôn nhân và hạnh phúc', 'pnj_wc001.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(147, 'Nhẫn Cưới Vàng Song Hành', 'PNJWC002', 21000000.00, NULL, 'Vàng 18K', 'Đá ECZ', 3.80, 'Cặp nhẫn cưới vàng tinh xảo với thiết kế xoắn nhẹ nhàng, mang lại cảm giác mềm mại và thanh lịch. Một chiếc nhẫn giữ nét đơn giản, bóng mượt, trong khi chiếc còn lại được điểm xuyết bằng những viên kim cương nhỏ lấp lánh, tạo sự hài hòa và bổ sung cho nhau. Bộ đôi nhẫn tượng trưng cho tình yêu song hành, sự đồng điệu và gắn kết vĩnh cửu, là lựa chọn hoàn hảo cho các cặp đôi trong ngày trọng đại.', 'pnj_wc002.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(148, 'Nhẫn Cưới Bạc Gắn Kết Vĩnh Cửu', 'PNJWC003', 17500000.00, NULL, 'Vàng 14K', 'Không', 3.20, 'Cặp nhẫn bạc sang trọng với thiết kế bóng mượt, điểm nhấn là chi tiết đan xen tinh tế tạo cảm giác gắn kết và đồng điệu. Bề mặt phản chiếu ánh sáng lấp lánh, mang lại vẻ đẹp hiện đại nhưng vẫn giữ nét thanh lịch. Bộ đôi nhẫn tượng trưng cho sự kết nối, tình yêu và lời hứa vĩnh cửu, là lựa chọn hoàn hảo cho các cặp đôi trong ngày trọng đại hoặc như một biểu tượng tình yêu lâu dài.', 'pnj_wc003.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(149, 'Nhẫn Cưới Vàng Song Nguyện', 'PNJWC004', 29500000.00, 28500000.00, 'Vàng 18K', 'Kim cương tự nhiên', 4.20, 'Cặp nhẫn cưới vàng tinh xảo với hai phong cách bổ sung cho nhau: một chiếc nhẫn đơn giản, thanh lịch với viên kim cương tròn ở giữa, trong khi chiếc còn lại được đính kim cương dọc thân, tạo nên vẻ lấp lánh rực rỡ. Sự kết hợp hài hòa giữa tối giản và sang trọng tượng trưng cho tình yêu song hành, sự đồng điệu và gắn kết vĩnh cửu. Đây là lựa chọn hoàn hảo cho các cặp đôi trong ngày trọng đại, vừa mang giá trị thẩm mỹ vừa chứa đựng thông điệp thiêng liêng về hôn nhân và hạnh phúc.', 'pnj_wc004.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(150, 'Nhẫn Cưới Vàng Vĩnh Kết', 'PNJWC005', 19000000.00, NULL, 'Vàng 18K', 'Không', 3.60, 'Cặp nhẫn cưới vàng đơn giản nhưng tinh tế, bề mặt bóng mượt phản chiếu ánh sáng sang trọng. Hai chiếc nhẫn có kích thước khác nhau, tượng trưng cho sự đồng điệu giữa nam và nữ, cùng nhau tạo nên một biểu tượng trọn vẹn của tình yêu và hôn nhân. Thiết kế tối giản mang ý nghĩa về sự thuần khiết và vĩnh cửu, là lựa chọn hoàn hảo cho các cặp đôi trong ngày trọng đại.', 'pnj_wc005.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(151, 'Nhẫn Cưới Vàng Hòa Âm', 'PNJWC006', 20500000.00, NULL, 'Vàng 18K', 'Không', 3.70, 'Cặp nhẫn cưới vàng với thiết kế độc đáo dạng giác cạnh, tạo nên hiệu ứng phản chiếu ánh sáng lấp lánh và sang trọng. Bề mặt được chế tác tinh xảo, vừa mang nét hiện đại vừa giữ sự thanh lịch truyền thống. Hai chiếc nhẫn song hành tượng trưng cho sự hòa hợp, gắn kết và tình yêu vĩnh cửu, là lựa chọn hoàn hảo cho các cặp đôi trong ngày trọng đại.', 'pnj_wc006.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(152, 'Nhẫn Cưới Vàng Song Hỷ', 'PNJWC007', 21500000.00, NULL, 'Vàng 18K', 'Đá ECZ', 3.90, 'Cặp nhẫn cưới vàng thanh lịch với hai phong cách bổ sung cho nhau: một chiếc nhẫn trơn bóng mượt, tối giản và tinh tế; chiếc còn lại được đính hàng kim cương nhỏ lấp lánh, mang lại vẻ sang trọng và rực rỡ. Sự kết hợp hài hòa giữa giản dị và cầu kỳ tượng trưng cho tình yêu song hành, sự đồng điệu và gắn kết vĩnh cửu. Đây là lựa chọn hoàn hảo cho các cặp đôi trong ngày trọng đại, vừa mang giá trị thẩm mỹ vừa chứa đựng thông điệp thiêng liêng về hôn nhân và hạnh phúc.', 'pnj_wc007.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(153, 'Nhẫn Cưới Vàng Viền Hạt', 'PNJWC008', 22500000.00, NULL, 'Vàng 18K', 'Không', 4.00, 'Cặp nhẫn cưới vàng sang trọng với thiết kế viền hạt tinh tế chạy dọc theo mép ngoài, tạo điểm nhấn độc đáo trên nền vàng bóng mượt. Bề mặt phản chiếu ánh sáng ấm áp, mang lại vẻ đẹp thanh lịch và cổ điển. Hai chiếc nhẫn song hành tượng trưng cho sự đồng điệu, gắn kết và tình yêu vĩnh cửu, là lựa chọn hoàn hảo cho các cặp đôi trong ngày trọng đại.', 'pnj_wc008.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(154, 'Nhẫn Cưới Vàng Tình Thâm', 'PNJWC009', 33000000.00, 32000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 4.50, 'Cặp nhẫn cưới vàng tinh tế với hai phong cách bổ sung cho nhau: một chiếc nhẫn trơn bóng mượt, đơn giản nhưng sang trọng; chiếc còn lại mang thiết kế cầu kỳ hơn với viên kim cương tròn ở giữa và những viên đá nhỏ đính dọc thân, tạo nên vẻ lấp lánh rực rỡ. Sự kết hợp hài hòa giữa giản dị và tinh xảo tượng trưng cho tình yêu song hành, sự đồng điệu và gắn kết vĩnh cửu. Đây là lựa chọn hoàn hảo cho các cặp đôi trong ngày trọng đại, vừa mang giá trị thẩm mỹ vừa chứa đựng thông điệp thiêng liêng về hôn nhân và hạnh phúc.', 'pnj_wc009.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(155, 'Nhẫn Cưới Vàng Dấu Ấn Tình Yêu', 'PNJWC010', 17000000.00, NULL, 'Vàng 18K', 'Không', 3.30, 'Cặp nhẫn cưới vàng độc đáo với thiết kế nửa trái tim khắc vân tay trên mỗi chiếc nhẫn. Khi đặt cạnh nhau, hai nửa ghép lại thành một trái tim hoàn chỉnh – biểu tượng thiêng liêng của tình yêu trọn vẹn và sự gắn kết vĩnh cửu. Bề mặt vàng bóng mượt kết hợp chi tiết khắc tinh xảo mang lại vẻ đẹp vừa hiện đại vừa đầy ý nghĩa cá nhân. Đây là lựa chọn lý tưởng cho các cặp đôi muốn lưu giữ dấu ấn riêng biệt trong ngày trọng đại.', 'pnj_wc010.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(156, 'Nhẫn Cưới Vàng Khắc Dấu Yêu', 'PNJWC011', 18000000.00, NULL, 'Vàng 18K', 'Không', 3.40, 'Cặp nhẫn cưới vàng tinh tế với thiết kế đơn giản nhưng đầy ý nghĩa, bên trong khắc tên và ngày đặc biệt của đôi lứa. Bề mặt vàng bóng mượt phản chiếu ánh sáng sang trọng, kết hợp cùng chi tiết khắc cá nhân hóa tạo nên dấu ấn riêng biệt. Đây không chỉ là trang sức mà còn là minh chứng cho tình yêu, sự gắn kết và kỷ niệm thiêng liêng của hai người.', 'pnj_wc011.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(157, 'Nhẫn Cưới Vàng Song Tinh', 'PNJWC012', 31000000.00, 30000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 4.30, 'Cặp nhẫn cưới vàng sang trọng với thiết kế tinh xảo, mỗi chiếc đều đính một viên kim cương tròn lấp lánh. Một chiếc mang phong cách mềm mại với đường cong nhẹ nhàng, viên kim cương được giữ bởi thế uốn lượn thanh thoát; chiếc còn lại cầu kỳ hơn với chi tiết trang trí và chấu kim cương nổi bật, tạo nên vẻ rực rỡ và cuốn hút. Sự kết hợp giữa đơn giản và tinh xảo tượng trưng cho tình yêu song hành, sự đồng điệu và gắn kết vĩnh cửu. Đây là lựa chọn hoàn hảo cho các cặp đôi muốn lưu giữ dấu ấn tình yêu trong ngày trọng đại.', 'pnj_wc012.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(158, 'Nhẫn Cưới Vàng Song Tâm', 'PNJWC013', 20000000.00, NULL, 'Vàng 18K', 'Đá ECZ', 3.80, 'Cặp nhẫn cưới vàng tinh tế với hai phong cách bổ sung cho nhau: một chiếc nhẫn đơn giản với viên kim cương nhỏ ở giữa, mang vẻ đẹp tối giản và thanh lịch; chiếc còn lại được đính hàng kim cương dọc thân, tạo nên sự lấp lánh sang trọng. Sự kết hợp hài hòa giữa giản dị và rực rỡ tượng trưng cho tình yêu song hành, sự đồng điệu và gắn kết vĩnh cửu. Đây là lựa chọn hoàn hảo cho các cặp đôi trong ngày trọng đại, vừa mang giá trị thẩm mỹ vừa chứa đựng thông điệp thiêng liêng về hôn nhân và hạnh phúc.', 'pnj_wc013.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(159, 'Nhẫn Cưới Vàng Hồng Song Hòa', 'PNJWC014', 19500000.00, NULL, 'Vàng hồng 18K', 'Không', 3.60, 'Cặp nhẫn cưới vàng hồng tinh tế với hai phong cách đối lập nhưng bổ sung cho nhau: một chiếc nhẫn mảnh mai, thanh lịch; chiếc còn lại bản rộng hơn với bề mặt nhám hiện đại. Sự kết hợp giữa mềm mại và mạnh mẽ tạo nên biểu tượng hoàn hảo cho tình yêu song hành, sự đồng điệu và gắn kết vĩnh cửu. Vàng hồng mang sắc ấm áp, tượng trưng cho tình yêu lãng mạn và bền lâu, là lựa chọn lý tưởng cho các cặp đôi trong ngày trọng đại.', 'pnj_wc014.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(160, 'Nhẫn Cưới Bạc Song Hành', 'PNJWC015', 20500000.00, NULL, 'Vàng trắng 18K', 'Không', 3.70, 'Cặp nhẫn bạc hiện đại với thiết kế độc đáo: phần giữa mang bề mặt nhám tinh tế, được viền bởi mép sáng bóng mượt mà. Sự kết hợp giữa nhám và bóng tạo nên vẻ đẹp đối lập nhưng hài hòa, tượng trưng cho sự đồng điệu và gắn kết vĩnh cửu của tình yêu đôi lứa. Đây là lựa chọn hoàn hảo cho các cặp đôi yêu thích phong cách thanh lịch, tinh tế nhưng vẫn mang nét cá tính riêng.', 'pnj_wc015.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(161, 'Nhẫn Cưới Vàng Song Vũ', 'PNJWC016', 34500000.00, 33500000.00, 'Vàng 18K', 'Kim cương tự nhiên', 4.60, 'Cặp nhẫn cưới vàng tinh xảo với hai phong cách bổ sung cho nhau: một chiếc nhẫn đơn giản, thanh lịch với viên kim cương tròn ở giữa; chiếc còn lại cầu kỳ hơn với thiết kế chữ V đính kim cương nhỏ lấp lánh, tạo nên vẻ sang trọng và rực rỡ. Sự kết hợp giữa tối giản và tinh xảo tượng trưng cho tình yêu song hành, sự đồng điệu và gắn kết vĩnh cửu. Đây là lựa chọn hoàn hảo cho các cặp đôi trong ngày trọng đại, vừa mang giá trị thẩm mỹ vừa chứa đựng thông điệp thiêng liêng về hôn nhân và hạnh phúc.', 'pnj_wc016.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(162, 'Nhẫn Cưới Vàng Song Vấn', 'PNJWC017', 21500000.00, NULL, 'Vàng 18K', 'Không', 3.90, 'Cặp nhẫn cưới vàng tinh tế với thiết kế xoắn nhẹ nhàng, tạo cảm giác mềm mại và uyển chuyển. Bề mặt vàng bóng mượt phản chiếu ánh sáng sang trọng, mang lại vẻ đẹp thanh lịch và hiện đại. Hai chiếc nhẫn song hành tượng trưng cho sự hòa hợp, gắn kết và tình yêu vĩnh cửu, là lựa chọn hoàn hảo cho các cặp đôi trong ngày trọng đại.', 'pnj_wc017.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(163, 'Nhẫn Cưới Vàng Song Tình', 'PNJWC018', 22000000.00, NULL, 'Vàng 18K', 'Đá ECZ', 4.00, 'Cặp nhẫn cưới vàng sang trọng với hai phong cách tinh tế: một chiếc nhẫn mang chi tiết trái tim nhỏ đính đá quý ở giữa, tượng trưng cho tình yêu lãng mạn; chiếc còn lại có thiết kế trơn bóng với đường rãnh nhẹ nhàng, tạo nên vẻ thanh lịch và hiện đại. Sự kết hợp giữa biểu tượng tình yêu và nét tối giản tinh xảo mang ý nghĩa về sự đồng điệu, gắn kết và hạnh phúc vĩnh cửu. Đây là lựa chọn hoàn hảo cho các cặp đôi trong ngày trọng đại.', 'pnj_wc018.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(164, 'Nhẫn Cưới Vàng Song Ngọc', 'PNJWC019', 32000000.00, 31000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 4.40, 'Cặp nhẫn cưới vàng tinh tế với hai phong cách bổ sung cho nhau: một chiếc nhẫn mảnh mai đính kim cương chạy vòng quanh, mang vẻ lấp lánh rực rỡ; chiếc còn lại bản dày hơn với viên kim cương tròn ở giữa, tạo điểm nhấn sang trọng và mạnh mẽ. Sự kết hợp giữa mềm mại và vững chắc tượng trưng cho tình yêu song hành, sự đồng điệu và gắn kết vĩnh cửu. Đây là lựa chọn hoàn hảo cho các cặp đôi trong ngày trọng đại, vừa mang giá trị thẩm mỹ vừa chứa đựng thông điệp thiêng liêng về hôn nhân và hạnh phúc.', 'pnj_wc019.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(165, 'Nhẫn Cưới Vàng Song Vấn Ánh Kim', 'PNJWC020', 23000000.00, NULL, 'Vàng 18K', 'Không', 4.10, 'Cặp nhẫn cưới vàng tinh xảo với thiết kế xoắn đan xen, kết hợp hài hòa giữa bề mặt bóng mượt và nhám mờ, tạo nên sự tương phản đầy nghệ thuật. Đường nét uyển chuyển tượng trưng cho sự hòa quyện của hai tâm hồn, gắn kết và đồng điệu trong tình yêu. Đây là lựa chọn hoàn hảo cho các cặp đôi yêu thích sự độc đáo, vừa mang vẻ đẹp hiện đại vừa chứa đựng thông điệp thiêng liêng về hôn nhân vĩnh cửu.', 'pnj_wc020.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(167, 'Nhẫn cưới bạc sang trọng', 'PNJWC022', 36000000.00, 35000000.00, 'vàng trắng', 'Kim cương tự nhiên', 4.80, 'Cặp nhẫn cưới bạc tinh tế đặt cạnh nhau trong ánh sáng vàng ấm áp. Một chiếc mang phong cách mạnh mẽ với đường nét hình học và những viên đá nhỏ viền quanh, chiếc còn lại thanh thoát hơn với dãy đá lấp lánh và viên kim cương tròn lớn ở trung tâm. Hình ảnh gợi lên sự gắn kết, tình yêu vĩnh cửu và sự sang trọng trong ngày trọng đại.', 'pnj_wc021.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(168, 'Nhẫn cưới vàng thủ công', 'PNJWC023', 17500000.00, NULL, 'Vàng 14K', 'Không', 3.20, 'Cặp nhẫn cưới vàng với bề mặt được chế tác theo phong cách búa gõ, tạo nên vẻ ngoài mộc mạc nhưng vẫn sang trọng. Một chiếc nhẫn lớn hơn, bản rộng, tượng trưng cho sự mạnh mẽ; chiếc còn lại nhỏ nhắn, thanh thoát, gợi sự tinh tế. Nền vải xám mềm mại cùng ánh sáng ấm áp làm nổi bật sắc vàng rực rỡ, mang đến cảm giác gần gũi và bền vững – như lời hứa gắn bó trọn đời của đôi lứa.', 'pnj_wc022\r\n.jpg', 10, 1, '1', '2026-02-25 16:18:56'),
(171, 'Lắc Tay Vàng Hạt Nhỏ', 'PNJLT001', 14500000.00, NULL, 'Vàng 18K', 'Không', 4.50, 'Chiếc lắc tay vàng tinh tế với thiết kế dây mảnh, điểm xuyết những hạt vàng nhỏ đều đặn dọc theo vòng. Kiểu dáng đơn giản nhưng sang trọng, kết hợp khóa móc chắc chắn cùng dây nối điều chỉnh, giúp dễ dàng vừa vặn với nhiều kích thước cổ tay.\r\n\r\nÁnh vàng óng ánh nổi bật trên nền vải satin, mang lại cảm giác thanh lịch và hiện đại. Đây là phụ kiện phù hợp cho cả trẻ em và người lớn yêu thích phong cách nhẹ nhàng, tối giản. Không chỉ là món trang sức thời trang, lắc tay vàng hạt nhỏ còn là lựa chọn hoàn hảo để làm quà tặng trong các dịp đặc biệt, gửi gắm lời chúc may mắn và yêu thương.', 'pnj_lt001.jpg', 7, 1, '1', '2026-02-25 16:22:13'),
(172, 'Lắc Tay Vàng Charm Tròn', 'PNJLT002', 16500000.00, NULL, 'Vàng 18K', 'Đá ECZ', 4.80, 'Chiếc lắc tay vàng thanh mảnh với thiết kế dây mảnh điều chỉnh bằng khóa trượt tiện lợi, hai đầu điểm xuyết hạt vàng nhỏ xinh. Trung tâm nổi bật với charm tròn đính đá lấp lánh, được bao quanh bởi hai hạt vàng bóng mịn, tạo nên sự cân đối và sang trọng.\r\n\r\nÁnh vàng óng ánh kết hợp cùng những viên đá sáng rực rỡ mang lại vẻ đẹp tinh tế, hiện đại nhưng vẫn trẻ trung. Đây là phụ kiện hoàn hảo cho bé gái hoặc những ai yêu thích phong cách nhẹ nhàng, thanh lịch. Không chỉ là món trang sức thời trang, lắc tay vàng charm tròn còn là món quà ý nghĩa, gửi gắm lời chúc may mắn và yêu thương trong các dịp đặc biệt.', 'pnj_lt002.jpg', 7, 1, '1', '2026-02-25 16:22:13'),
(173, 'Lắc Tay Vàng Đá Xanh', 'PNJLT003', 28500000.00, 27500000.00, 'Vàng 18K', 'Kim cương tự nhiên', 5.50, 'Chiếc lắc tay vàng sang trọng với thiết kế tinh xảo, nổi bật nhờ viên đá xanh hình chữ nhật ở trung tâm, được bao quanh bởi những viên đá trắng nhỏ lấp lánh. Dọc theo dây vòng là chuỗi đá tròn sáng rực rỡ, tạo nên vẻ đẹp hài hòa và cuốn hút. Khóa móc chắc chắn đi kèm dây nối điều chỉnh giúp dễ dàng vừa vặn với nhiều kích thước cổ tay.\r\n\r\nSự kết hợp giữa sắc vàng óng ánh và viên đá xanh quý phái mang lại cảm giác thanh lịch, hiện đại nhưng vẫn đầy tinh tế. Đây là món trang sức lý tưởng để làm quà tặng trong các dịp đặc biệt, gửi gắm lời chúc may mắn và yêu thương, đồng thời khẳng định phong cách sang trọng của người sở hữu.', 'pnj_lt003.jpg', 7, 1, '1', '2026-02-25 16:22:13'),
(174, 'Lắc Tay Vàng Bướm Xinh', 'PNJLT004', 13200000.00, NULL, 'Vàng 18K', 'Không', 4.20, 'Chiếc lắc tay vàng tinh tế với thiết kế dây mảnh, điểm xuyết những charm hình bướm nhỏ dọc theo vòng. Sự kết hợp giữa charm bướm đặc và charm bướm viền tạo nên vẻ đẹp hài hòa, vừa nhẹ nhàng vừa độc đáo. Dây vòng có khóa móc chắc chắn cùng phần nối điều chỉnh, giúp dễ dàng vừa vặn với nhiều kích thước cổ tay.\r\n\r\nÁnh vàng óng ánh nổi bật trên nền trung tính, mang lại cảm giác thanh lịch và hiện đại. Đây là phụ kiện hoàn hảo cho bé gái hoặc những ai yêu thích phong cách nữ tính, trẻ trung. Không chỉ là món trang sức thời trang, lắc tay vàng bướm xinh còn là món quà ý nghĩa, gửi gắm lời chúc may mắn và niềm vui trong các dịp đặc biệt.', 'pnj_lt004.jpg', 7, 1, '1', '2026-02-25 16:22:13'),
(175, 'Lắc Tay Vàng Đá Đỏ', 'PNJLT005', 21500000.00, NULL, 'Vàng 18K', 'Ruby', 5.10, 'Chiếc lắc tay vàng tinh xảo với thiết kế dây mảnh, điểm xuyết nhiều viên đá đỏ nổi bật được cắt gọt theo nhiều hình dạng khác nhau như vuông, chữ nhật và tròn. Sự kết hợp giữa sắc vàng ấm áp và màu đỏ rực rỡ tạo nên vẻ đẹp sang trọng, cuốn hút. Khóa móc chắc chắn cùng dây nối điều chỉnh giúp dễ dàng vừa vặn với nhiều kích thước cổ tay.\r\n\r\nĐây là món trang sức mang phong cách thanh lịch, hiện đại, đồng thời tượng trưng cho sự may mắn và tình yêu nồng nhiệt. Lắc tay vàng đá đỏ không chỉ là phụ kiện thời trang mà còn là món quà ý nghĩa dành tặng trong các dịp đặc biệt, gửi gắm lời chúc yêu thương và hạnh phúc.', 'pnj_lt005.jpg', 7, 1, '1', '2026-02-25 16:22:13'),
(176, 'Lắc Tay Vàng Đá Xanh – Trắng', 'PNJLT006', 24000000.00, NULL, 'Vàng 18K', 'Sapphire', 5.30, 'Chiếc lắc tay vàng tinh xảo với thiết kế mắt xích hình vô cực, xen kẽ các ô đá được cắt gọt cầu kỳ. Những viên đá xanh tròn nổi bật kết hợp cùng đá trắng vuông sáng lấp lánh tạo nên sự đối lập hài hòa, mang lại vẻ đẹp sang trọng và cuốn hút. Khóa móc chắc chắn cùng dây nối điều chỉnh giúp dễ dàng vừa vặn với nhiều kích thước cổ tay.\r\n\r\nSự kết hợp giữa sắc vàng óng ánh, xanh dịu mắt và trắng tinh khôi mang lại cảm giác thanh lịch, hiện đại nhưng vẫn đầy tinh tế. Đây là món trang sức lý tưởng để làm quà tặng trong các dịp đặc biệt, gửi gắm lời chúc may mắn và yêu thương, đồng thời khẳng định phong cách sang trọng của người sở hữu.', 'pnj_lt006.jpg', 7, 1, '1', '2026-02-25 16:22:13'),
(177, 'Lắc Tay Lá Xinh”', 'PNJLT007', 15800000.00, NULL, 'Vàng trắng ', 'Không', 4.60, 'Chiếc lắc tay bạc tinh tế với thiết kế xen kẽ các mắt xích hình lá và mắt xích họa tiết, tạo nên hoa văn phản chiếu ánh sáng đầy nghệ thuật. Bề mặt sáng bóng cùng đường nét mềm mại mang lại vẻ đẹp thanh lịch, hiện đại nhưng vẫn nhẹ nhàng, nữ tính.\r\n\r\nKhóa móc chắc chắn giúp dễ dàng đeo và tháo, phù hợp với nhiều kích thước cổ tay. Đây không chỉ là phụ kiện thời trang, mà còn là món quà ý nghĩa dành cho bé gái hoặc người thân yêu, tượng trưng cho sự tươi mới và may mắn.', 'pnj_lt007.jpg', 7, 1, '1', '2026-02-25 16:22:13'),
(178, 'Lắc Tay Vàng Hoa Văn Cỏ Bốn Lá', 'PNJLT008', 15000000.00, NULL, 'Vàng  18K', 'Không', 4.40, 'Chiếc lắc tay vàng thanh mảnh với thiết kế dây mảnh tinh tế, điểm xuyết bốn charm hình hoa văn cỏ bốn lá nhỏ nhắn, tạo nên vẻ đẹp hài hòa và sang trọng. Các chi tiết được chế tác từ hạt vàng li ti, mang lại hiệu ứng phản chiếu ánh sáng lung linh. Phần cuối dây vòng có charm hình trái tim nhỏ xinh, tăng thêm nét nữ tính và đáng yêu.\r\n\r\nSự kết hợp giữa sắc vàng óng ánh và họa tiết mềm mại mang lại cảm giác thanh lịch, hiện đại nhưng vẫn trẻ trung. Đây là món trang sức lý tưởng để làm quà tặng trong các dịp đặc biệt, gửi gắm lời chúc may mắn và yêu thương đến người thân yêu.', 'pnj_lt008.jpg', 7, 1, '1', '2026-02-25 16:22:13'),
(179, 'Lắc Tay Vàng Đính Đá Trắng', 'PNJLT009', 31000000.00, 30000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 5.80, 'Chiếc lắc tay vàng thanh mảnh với thiết kế dây hộp tinh tế, điểm nhấn là thanh cong mảnh mai ở trung tâm được đính một hàng đá trắng lấp lánh. Khóa trượt điều chỉnh tiện lợi với hai đầu mũi tên nhỏ giúp dễ dàng vừa vặn với nhiều kích thước cổ tay.\r\n\r\nSự kết hợp giữa sắc vàng sang trọng và ánh sáng lung linh từ những viên đá mang lại vẻ đẹp hiện đại, thanh lịch nhưng vẫn tinh tế. Đây là món trang sức lý tưởng để đeo hằng ngày hoặc trong những dịp đặc biệt, đồng thời cũng là món quà ý nghĩa gửi gắm lời chúc may mắn và yêu thương.', 'pnj_lt009.jpg', 7, 1, '1', '2026-02-25 16:22:13'),
(180, 'Lắc Tay Vàng Dây Xoắn', 'PNJLT010', 17000000.00, NULL, 'Vàng 18K', 'Không', 4.90, 'Chiếc lắc tay vàng sang trọng với thiết kế dây xoắn tinh xảo, tạo nên hiệu ứng ánh sáng phản chiếu đầy cuốn hút. Bề mặt vàng bóng mịn kết hợp cùng chi tiết chụp nhỏ ở hai đầu gần khóa móc càng làm tăng thêm sự tinh tế. Khóa móc chắc chắn giúp dễ dàng đeo và tháo, đồng thời đảm bảo độ an toàn khi sử dụng.\r\n\r\nPhong cách tối giản nhưng vẫn nổi bật, chiếc lắc tay vàng dây xoắn là phụ kiện hoàn hảo cho những ai yêu thích sự thanh lịch và hiện đại. Đây cũng là món quà ý nghĩa, gửi gắm lời chúc may mắn và yêu thương trong các dịp đặc biệt.', 'pnj_lt010.jpg', 7, 1, '1', '2026-02-25 16:22:13'),
(181, 'Lắc Tay Bạc Hạt Tròn', 'PNJLT011', 2100000.00, NULL, 'Bạc 925', 'Không', 3.00, 'Chiếc lắc tay bạc thanh mảnh với thiết kế dây mảnh điểm xuyết những hạt tròn nhỏ đều đặn dọc theo vòng. Khóa móc chắc chắn kết hợp dây nối điều chỉnh tiện lợi, giúp dễ dàng vừa vặn với nhiều kích thước cổ tay.\r\n\r\nPhong cách tối giản nhưng tinh tế, ánh bạc sáng bóng phản chiếu nhẹ nhàng tạo nên vẻ đẹp thanh lịch và hiện đại. Đây là phụ kiện phù hợp cho cả bé gái và người lớn yêu thích sự nhẹ nhàng, nữ tính. Không chỉ là món trang sức thời trang, lắc tay bạc hạt tròn còn là món quà ý nghĩa, gửi gắm lời chúc yêu thương và may mắn trong các dịp đặc biệt.', 'pnj_lt011.jpg', 7, 2, '1', '2026-02-25 16:22:13'),
(182, 'Lắc Tay Bạc Đính Đá', 'PNJLT012', 2500000.00, NULL, 'Bạc 925', 'Đá CZ', 3.20, 'Chiếc lắc tay bạc tinh tế với thiết kế dây mảnh, một phần được đính hàng đá sáng lấp lánh, tạo hiệu ứng phản chiếu lung linh. Khóa trượt điều chỉnh tiện lợi giúp dễ dàng vừa vặn với nhiều kích thước cổ tay, đồng thời mang lại sự thoải mái khi đeo.\r\n\r\nĐặt trong hộp trang sức sang trọng, chiếc lắc tay càng toát lên vẻ đẹp thanh lịch và hiện đại. Đây là món phụ kiện hoàn hảo để làm quà tặng trong các dịp đặc biệt, gửi gắm lời chúc yêu thương và may mắn, đồng thời khẳng định phong cách tinh tế của người sở hữu.', 'pnj_lt012.jpg', 7, 2, '1', '2026-02-25 16:22:13'),
(183, 'Lắc Tay Bạc Trái Tim', 'PNJLT013', 2300000.00, NULL, 'Bạc 925', 'Đá CZ', 3.10, 'Chiếc lắc tay bạc thanh mảnh với thiết kế dây mắt xích nhỏ, điểm xuyết năm charm hình trái tim bóng mịn, được sắp xếp đều đặn quanh vòng. Khóa móc chắc chắn kết hợp dây nối điều chỉnh tiện lợi, phần cuối dây có chi tiết giọt nước nhỏ xinh, tăng thêm nét duyên dáng.\r\n\r\nPhong cách nhẹ nhàng nhưng tinh tế, ánh bạc sáng bóng phản chiếu mềm mại tạo nên vẻ đẹp thanh lịch và nữ tính. Đây là món trang sức phù hợp cho bé gái hoặc những ai yêu thích sự ngọt ngào, đáng yêu. Không chỉ là phụ kiện thời trang, lắc tay bạc trái tim còn là món quà ý nghĩa, gửi gắm lời chúc yêu thương và hạnh phúc trong các dịp đặc biệt.', 'pnj_lt013.jpg', 7, 2, '1', '2026-02-25 16:22:13'),
(184, 'Lắc Tay Bạc Đính Đá Trắng', 'PNJLT014', 2400000.00, NULL, 'Bạc 925', 'Đá CZ', 3.30, 'Chiếc lắc tay bạc tinh tế với thiết kế dây mảnh, điểm nhấn là hàng đá trắng lấp lánh được gắn dọc theo phần giữa vòng. Ánh bạc sáng bóng kết hợp cùng những viên đá nhỏ tạo nên vẻ đẹp thanh lịch, sang trọng nhưng vẫn nhẹ nhàng, nữ tính.\r\n\r\nKhóa móc chắc chắn và dây nối điều chỉnh giúp dễ dàng vừa vặn với nhiều kích thước cổ tay. Đây là món trang sức hoàn hảo để đeo hằng ngày hoặc trong các dịp đặc biệt, đồng thời là món quà ý nghĩa gửi gắm lời chúc yêu thương và may mắn.', 'pnj_lt014.jpg', 7, 2, '1', '2026-02-25 16:22:13'),
(185, 'Vòng Tay Hoa Bạc Thanh Lịch', 'PNJLT015', 2600000.00, NULL, 'Bạc 925', 'Đá CZ', 3.40, 'Chiếc vòng tay được chế tác từ bạc sáng bóng, nổi bật với họa tiết hoa nhỏ tinh xảo xen kẽ cùng những hạt tròn bóng mượt. Thiết kế mang vẻ đẹp thanh thoát, nhẹ nhàng nhưng vẫn sang trọng, phù hợp để đeo hằng ngày hoặc trong những dịp đặc biệt. Phần dây điều chỉnh với móc khóa chắc chắn và điểm nhấn hình giọt nước ở cuối tạo thêm nét duyên dáng. Đây là món trang sức lý tưởng dành cho người yêu thích sự tinh tế và nữ tính.', 'pnj_lt015.jpg', 7, 2, '1', '2026-02-25 16:22:13'),
(186, 'Vòng Tay Bướm Vàng Tinh Khôi', 'PNJLT016', 15500000.00, NULL, 'Vàng 18K', 'Không', 4.70, 'Chiếc vòng tay được chế tác từ vàng với thiết kế dây mảnh thanh thoát, điểm xuyết những charm hình bướm nhỏ xinh, tạo cảm giác nhẹ nhàng và bay bổng. Kiểu dáng tối giản nhưng vẫn sang trọng, phù hợp cho người yêu thích sự tinh tế và nữ tính. Phần móc khóa chắc chắn kèm dây điều chỉnh giúp dễ dàng tùy chỉnh kích thước, mang lại sự thoải mái khi đeo. Đây là món trang sức lý tưởng để làm nổi bật phong cách thanh lịch trong các dịp thường ngày hoặc đặc biệt.', 'pnj_lt016.jpg', 7, 1, '1', '2026-02-25 16:22:13'),
(187, 'Vòng Tay Hoa Vàng Thanh Tú', 'PNJLT017', 22000000.00, NULL, 'Vàng 18K', 'Không', 5.20, 'Chiếc vòng tay vàng nổi bật với năm mắt hoa được chế tác tinh xảo, mỗi bông hoa có cánh dạng họa tiết nổi cùng hạt tròn nhỏ ở giữa, tạo cảm giác mềm mại và sang trọng. Các mắt hoa được nối bằng dây xích mảnh, mang lại sự cân đối và thanh lịch. Khóa móc chắc chắn với vòng phụ giúp cố định dễ dàng, đảm bảo sự thoải mái khi đeo. Thiết kế đối xứng và tinh tế khiến chiếc vòng trở thành điểm nhấn hoàn hảo cho phong cách nữ tính, thanh lịch trong mọi dịp.', 'pnj_lt017.jpg', 7, 1, '1', '2026-02-25 16:22:13'),
(188, 'Vòng Tay Kim Cương Ánh Vàng', 'PNJLT018', 33000000.00, 32000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 6.00, 'Chiếc vòng tay vàng tinh xảo với điểm nhấn là viên kim cương cắt tròn ở trung tâm, được giữ chắc chắn bằng bốn chấu. Hai bên viên đá chính là những viên kim cương nhỏ xếp đối xứng, tạo nên vẻ cân bằng và sang trọng. Dây vòng mảnh mai, khóa gọn nhẹ, kèm theo charm tròn khắc ký hiệu tinh tế gần chốt khóa, tăng thêm nét độc đáo. Thiết kế tối giản nhưng vẫn toát lên sự quý phái, phù hợp để làm điểm nhấn trong những dịp đặc biệt hoặc như món quà sang trọng dành cho người thân yêu.', 'pnj_lt018.jpg', 7, 1, '1', '2026-02-25 16:22:13');
INSERT INTO `sanpham` (`id`, `ten_sp`, `ma_sp`, `gia`, `gia_khuyen_mai`, `chat_lieu`, `da_chinh`, `trong_luong`, `mo_ta`, `hinh_anh`, `danh_muc_id`, `thuong_hieu_id`, `trang_thai`, `ngay_tao`) VALUES
(189, 'Vòng Tay Hoa Đá Vàng', 'PNJLT019', 17500000.00, NULL, 'Vàng 18K', 'Không', 4.90, 'Chiếc vòng tay vàng thanh mảnh được điểm xuyết xen kẽ giữa các mắt tròn và hoa nhỏ, mỗi mắt đều gắn đá sáng lấp lánh như kim cương, tạo hiệu ứng lung linh trên cổ tay. Thiết kế tinh tế với sự kết hợp hài hòa giữa họa tiết hoa và hình tròn mang lại vẻ đẹp vừa nữ tính vừa sang trọng. Khóa móc chắc chắn dạng lobster kèm dây nối điều chỉnh, cùng thẻ nhỏ khắc ký hiệu chất liệu, giúp người đeo yên tâm về độ bền và chất lượng. Đây là món trang sức lý tưởng để làm nổi bật phong cách thanh lịch trong những buổi tiệc hoặc khi kết hợp với trang phục thường ngày.', 'pnj_lt019.jpg', 7, 1, '1', '2026-02-25 16:22:13'),
(190, 'Vòng Tay Ngôi Sao Ánh Kim', 'PNJLT020', 34500000.00, 33500000.00, 'Vàng 18K', 'Kim cương tự nhiên', 6.20, 'Chiếc vòng tay vàng thanh mảnh với điểm nhấn là charm hình ngôi sao nhỏ ở trung tâm, được đính những viên đá sáng lấp lánh, tạo hiệu ứng lung linh như ánh sao trên cổ tay. Thiết kế tối giản nhưng tinh tế, mang lại vẻ đẹp hiện đại và sang trọng. Phần dây mảnh có khóa điều chỉnh với nhiều mắt xích, giúp dễ dàng tùy chỉnh kích thước phù hợp. Đây là món trang sức lý tưởng cho người yêu thích phong cách nhẹ nhàng nhưng vẫn nổi bật, thích hợp để đeo hằng ngày hoặc trong những dịp đặc biệt.', 'pnj_lt020.jpg', 7, 1, '1', '2026-02-25 16:22:13'),
(191, 'Lắc tay Hoa Ngọc Quý', 'PNJLT021', 16000000.00, NULL, 'Vàng 18K', 'Không', 4.60, 'Chiếc lắc tay tinh xảo được chế tác từ vàng, nổi bật với những họa tiết hoa nhỏ xinh gồm bốn viên đá trắng sáng lấp lánh, tạo thành hình cánh hoa mềm mại. Các hoa văn được kết nối bằng những mắt xích vàng xoắn nhẹ, mang lại sự thanh thoát và sang trọng. Thiết kế dây mảnh cùng khóa điều chỉnh giúp ôm vừa vặn cổ tay, tôn lên vẻ đẹp nữ tính và quý phái. Đây là món trang sức lý tưởng để làm điểm nhấn trong những dịp đặc biệt hoặc để khẳng định phong cách tinh tế hằng ngày.', 'pnj_lt021.jpg', 7, 1, '1', '2026-02-25 16:22:13'),
(192, 'Lắc tay Vàng Tinh Khôi', 'PNJLT022', 18000000.00, NULL, 'Vàng 18K', 'Không', 5.00, 'Chiếc lắc tay được chế tác từ vàng với thiết kế tối giản nhưng đầy tinh tế. Trên nền dây mảnh, bốn chi tiết oval bóng mượt được sắp xếp cân đối, tạo điểm nhấn sang trọng và hiện đại. Khóa móc chắc chắn giúp dễ dàng điều chỉnh, mang lại sự thoải mái khi đeo. Với phong cách thanh lịch, chiếc lắc tay này phù hợp cả khi đi làm, dạo phố hay trong những buổi tiệc trang nhã, tôn lên vẻ đẹp tinh khôi và sự tự tin của người phụ nữ.', 'pnj_lt022.jpg', 7, 1, '1', '2026-02-25 16:22:13'),
(193, 'Lắc tay Hoa Bạc Tinh Tú', 'PNJLT023', 2700000.00, NULL, 'Bạc 925', 'Đá CZ', 3.50, 'Chiếc lắc tay được chế tác từ bạc S925 cao cấp, nổi bật với chuỗi đá trắng nhỏ lấp lánh dọc theo dây. Tâm điểm của thiết kế là họa tiết hoa tinh xảo, ôm trọn viên đá sáng rực rỡ, tạo nên vẻ đẹp thanh lịch và sang trọng. Dây có khóa điều chỉnh cùng charm hình trái tim khắc S925, vừa tinh tế vừa tiện lợi khi đeo. Đây là món trang sức lý tưởng để tôn lên sự nữ tính, phù hợp cả trong những buổi tiệc trang nhã lẫn phong cách thường ngày.', 'pnj_lt023.jpg', 7, 2, '1', '2026-02-25 16:22:13'),
(194, ' Lắc tay Ngôi Sao Bạc', 'PNJLT024', 2800000.00, NULL, 'Bạc 925', 'Đá CZ', 3.60, 'Chiếc lắc tay bạc tinh tế với dây mảnh, điểm nhấn là charm hình tròn đính đá sáng lấp lánh, tạo hiệu ứng như một vì sao rực rỡ. Từ charm trung tâm, một ngôi sao sáu cánh nhỏ xinh cũng được đính đá tỉ mỉ, mang lại vẻ đẹp vừa hiện đại vừa huyền bí. Khóa móc chắc chắn giúp dễ dàng đeo và điều chỉnh. Thiết kế tối giản nhưng sang trọng, phù hợp để làm điểm nhấn trong phong cách thường ngày hoặc khi tham dự những buổi tiệc trang nhã.', 'pnj_lt024.jpg', 7, 2, '1', '2026-02-25 16:22:13'),
(195, 'Lắc tay Hoa Vàng Thanh Tú', 'PNJLT025', 25000000.00, NULL, 'Vàng 18K', 'Không', 5.40, 'Chiếc lắc tay vàng tinh xảo với thiết kế dây mảnh điểm xuyết những hạt vàng nhỏ, tạo cảm giác nhẹ nhàng và thanh lịch. Ba charm hình hoa được sắp xếp cân đối dọc theo dây, mang lại vẻ đẹp nữ tính và sang trọng. Khóa điều chỉnh tiện lợi cùng chi tiết trang trí nhỏ ở cuối dây giúp tăng thêm sự tinh tế. Đây là món trang sức lý tưởng để làm nổi bật phong cách thanh nhã, phù hợp cả khi đi làm, dự tiệc hay dạo phố.', 'pnj_lt025.jpg', 7, 1, '1', '2026-02-25 16:22:13'),
(221, 'Mặt dây Hoa Vàng Ký Ức', 'PNJMD001', 8500000.00, NULL, 'Vàng 18K', 'Không', 2.10, 'Mặt dây chuyền vàng oval với bề mặt bóng mượt, điểm xuyết hoa văn khắc tinh xảo ở trung tâm. Ngay giữa bông hoa là viên đá sáng lấp lánh, tạo nên điểm nhấn sang trọng và thanh lịch. Thiết kế cổ điển nhưng tinh tế, mang lại cảm giác vừa quý phái vừa gợi nhớ đến những kỷ niệm đáng trân trọng. Phần móc chắc chắn giúp dễ dàng kết hợp với nhiều loại dây chuyền, thích hợp để làm quà tặng ý nghĩa hoặc làm món trang sức gắn liền với dấu ấn cá nhân.', 'pnj_md001.jpg', 9, 1, '1', '2026-02-25 16:25:10'),
(222, 'Mặt dây Trái Tim Vàng Yêu Thương', 'PNJMD002', 9200000.00, NULL, 'Vàng 18K', 'Đá ECZ', 2.30, 'Mặt dây chuyền vàng sang trọng với thiết kế trái tim viền đá trắng lấp lánh, tạo nên vẻ đẹp tinh tế và nổi bật. Bên trong là ba trái tim vàng nhỏ xếp xen kẽ, tượng trưng cho tình yêu, sự gắn kết và hạnh phúc. Phần móc chắc chắn giúp dễ dàng kết hợp với nhiều loại dây chuyền, mang lại phong cách vừa hiện đại vừa lãng mạn. Đây là món trang sức lý tưởng để làm quà tặng cho người thân yêu hoặc để tự mình lưu giữ những khoảnh khắc ý nghĩa.', 'pnj_md002.jpg', 9, 1, '1', '2026-02-25 16:25:10'),
(223, 'Mặt dây Kim Cương Vàng Tinh Hoa', 'PNJMD003', 24500000.00, 23500000.00, 'Vàng 18K', 'Kim cương tự nhiên', 2.80, 'Mặt dây chuyền sang trọng với viên kim cương cắt tròn rực rỡ, được cố định bằng ba chấu vàng tinh xảo. Phần móc vàng bóng mượt tạo sự liền mạch và thanh lịch, dễ dàng kết hợp với nhiều loại dây chuyền khác nhau. Thiết kế tối giản nhưng đầy đẳng cấp, tôn vinh vẻ đẹp thuần khiết của kim cương và sự ấm áp của vàng. Đây là món trang sức lý tưởng để khẳng định phong cách tinh tế, đồng thời là lựa chọn hoàn hảo cho những dịp đặc biệt.', 'pnj_md003.jpg', 9, 1, '1', '2026-02-25 16:25:10'),
(224, 'Mặt dây Ánh Sáng Ngọc Vàng', 'PNJMD004', 7800000.00, NULL, 'Vàng 18K', 'Không', 1.90, 'Mặt dây chuyền vàng tinh tế với thiết kế tối giản, điểm nhấn là viên đá sáng lấp lánh ở trung tâm. Phần khung vàng bóng mượt ôm trọn viên đá, tạo nên vẻ đẹp sang trọng và thanh lịch. Thiết kế nhỏ gọn nhưng đầy tinh xảo, dễ dàng kết hợp với nhiều loại dây chuyền, phù hợp để làm điểm nhấn trong phong cách thường ngày hoặc trong những dịp đặc biệt.', 'pnj_md004.jpg', 9, 1, '1', '2026-02-25 16:25:10'),
(225, 'Mặt dây Hồng Ngọc Vàng Quý Phái', 'PNJMD005', 16800000.00, NULL, 'Vàng 18K', 'Ruby', 2.60, 'Mặt dây chuyền vàng sang trọng với viên đá đỏ cắt hình chữ nhật (emerald cut) nổi bật, tỏa sắc rực rỡ và sâu thẳm. Khung vàng bóng mượt ôm trọn viên đá, tạo nên sự kết hợp hoàn hảo giữa vẻ đẹp cổ điển và hiện đại. Phần móc chắc chắn giúp dễ dàng kết hợp với nhiều loại dây chuyền, mang lại phong cách tinh tế và đẳng cấp. Đây là món trang sức lý tưởng để làm điểm nhấn trong những dịp đặc biệt, đồng thời thể hiện sự tự tin và cá tính của người sở hữu.', 'pnj_md005.jpg', 9, 1, '1', '2026-02-25 16:25:10'),
(226, 'Mặt dây Lam Ngọc Thanh Tú', 'PNJMD006', 17500000.00, NULL, 'Vàng 18K', 'Sapphire', 2.70, 'Mặt dây chuyền bạc tinh tế với viên đá xanh oval cắt giác cạnh, tỏa sắc sâu thẳm và sang trọng. Viên đá được cố định bằng bốn chấu bạc chắc chắn, tạo nên sự cân đối và nổi bật. Khung bạc sáng bóng kết hợp cùng dây chuyền mảnh mai mang lại vẻ đẹp thanh lịch, dễ dàng phối hợp với nhiều phong cách khác nhau. Đây là món trang sức lý tưởng để làm điểm nhấn trong những dịp đặc biệt, đồng thời thể hiện sự tinh tế và đẳng cấp của người sở hữu.', 'pnj_md006.jpg', 9, 1, '1', '2026-02-25 16:25:10'),
(227, 'Mặt dây Nơ Bạc Duyên Dáng', 'PNJMD007', 9000000.00, NULL, 'Vàng trắng 18K', 'Không', 2.20, 'Mặt dây chuyền bạc tinh tế với thiết kế nơ cân đối, mềm mại, điểm xuyết viên đá sáng ở trung tâm. Khung bạc bóng mượt kết hợp cùng dây chuyền mảnh mai mang lại vẻ đẹp thanh lịch và nữ tính. Đây là món trang sức lý tưởng để làm nổi bật phong cách duyên dáng, phù hợp cả khi đi tiệc hay trong cuộc sống thường ngày.', 'pnj_md007.jpg', 9, 1, '1', '2026-02-25 16:25:10'),
(228, 'Mặt dây Trái Tim Vàng Tinh Khôi', 'PNJMD008', 8800000.00, NULL, 'Vàng  18K', 'Không', 2.10, 'Mặt dây chuyền vàng sang trọng với thiết kế trái tim bóng mượt, bề mặt nhẵn mịn phản chiếu ánh sáng lấp lánh. Sợi dây mảnh mai với các mắt xích tròn đều đặn càng làm nổi bật vẻ tinh tế và thanh lịch của chiếc mặt dây. Biểu tượng trái tim mang ý nghĩa về tình yêu và sự gắn kết, là món trang sức lý tưởng để làm quà tặng cho người thân yêu hoặc để tự mình lưu giữ những khoảnh khắc ý nghĩa.', 'pnj_md008.jpg', 9, 1, '1', '2026-02-25 16:25:10'),
(229, 'Mặt dây Vầng Sáng Vàng Kim Cương', 'PNJMD009', 28500000.00, 27500000.00, 'Vàng 18K', 'Kim cương tự nhiên', 3.00, 'Mặt dây chuyền vàng tinh xảo với thiết kế tròn sang trọng, tâm điểm là viên đá lớn lấp lánh, được bao quanh bởi vòng halo những viên đá nhỏ sáng rực rỡ. Khung vàng bóng mượt kết hợp cùng dây chuyền mảnh mai tạo nên sự kết hợp hoàn hảo giữa vẻ đẹp tinh tế và đẳng cấp. Thiết kế đối xứng, tỏa sáng như vầng hào quang, mang lại phong cách sang trọng và quý phái. Đây là món trang sức lý tưởng để làm nổi bật vẻ đẹp thanh lịch trong những dịp đặc biệt.', 'pnj_md009.jpg', 9, 1, '1', '2026-02-25 16:25:10'),
(230, ' Mặt dây Vô Cực Vàng Vĩnh Hằng', 'PNJMD010', 9600000.00, NULL, 'Vàng 18K', 'Không', 2.40, 'Mặt dây chuyền vàng tinh tế với thiết kế biểu tượng vô cực, bề mặt bóng mượt phản chiếu ánh sáng sang trọng. Hình dáng vòng lặp mềm mại tượng trưng cho tình yêu bất tận, sự gắn kết và trường tồn. Phần móc chắc chắn giúp dễ dàng kết hợp với nhiều loại dây chuyền, mang lại phong cách hiện đại nhưng vẫn đầy ý nghĩa. Đây là món trang sức lý tưởng để làm quà tặng cho người thân yêu, hoặc để tự mình lưu giữ thông điệp về sự vĩnh hằng và niềm tin.', 'pnj_md010.jpg', 9, 1, '1', '2026-02-25 16:25:10'),
(231, 'Mặt dây Trái Tim Bạc Tinh Khôi', 'PNJMD011', 1200000.00, NULL, 'Bạc 925', 'Không', 1.50, 'Mặt dây chuyền bạc thanh lịch với thiết kế trái tim bóng mượt, bề mặt phản chiếu ánh sáng lấp lánh. Sợi dây bạc mảnh mai với các mắt xích đều đặn càng làm nổi bật vẻ đẹp tinh tế và giản dị. Biểu tượng trái tim mang ý nghĩa tình yêu và sự gắn kết, là món trang sức lý tưởng để làm quà tặng cho người thân yêu hoặc để tự mình lưu giữ những khoảnh khắc ý nghĩa.', 'pnj_md011.jpg', 9, 2, '1', '2026-02-25 16:25:10'),
(232, ' Mặt dây Trái Tim Bạc Lấp Lánh', 'PNJMD012', 1500000.00, NULL, 'Bạc 925', 'Đá CZ', 1.70, 'Mặt dây chuyền bạc tinh tế với thiết kế trái tim sang trọng, nổi bật bởi viên đá tròn sáng rực rỡ ở trung tâm. Phần cong bên trái của trái tim được điểm xuyết thêm những viên đá nhỏ lấp lánh, tạo hiệu ứng ánh sáng lung linh và đầy cuốn hút. Sợi dây bạc mảnh mai càng làm nổi bật vẻ đẹp thanh lịch, phù hợp để đeo trong những dịp đặc biệt hoặc làm quà tặng ý nghĩa cho người thân yêu. Đây là món trang sức mang thông điệp tình yêu, sự gắn kết và vẻ đẹp vĩnh cửu.', 'pnj_md012.jpg', 9, 2, '1', '2026-02-25 16:25:10'),
(233, 'Mặt dây Trái Tim Kim Cương Vĩnh Cửu', 'PNJMD013', 1400000.00, NULL, 'Bạc 925', 'Đá CZ', 1.60, 'Mặt dây chuyền bạc tinh xảo với viên kim cương hình trái tim lớn, lấp lánh rực rỡ. Phần móc nối được đính thêm những viên đá nhỏ xếp dọc, tạo hiệu ứng ánh sáng lung linh và sang trọng. Sợi dây bạc mảnh mai càng làm nổi bật vẻ đẹp thanh lịch, mang lại phong cách tinh tế và đẳng cấp. Biểu tượng trái tim kết hợp cùng ánh sáng kim cương tượng trưng cho tình yêu vĩnh hằng, là món trang sức lý tưởng để làm quà tặng trong những dịp đặc biệt.', 'pnj_md013.jpg', 9, 2, '1', '2026-02-25 16:25:10'),
(234, 'Mặt dây Vương Miện Bạc Quyền Quý', 'PNJMD014', 1550000.00, NULL, 'Bạc 925', 'Đá CZ', 1.80, 'Mặt dây chuyền bạc tinh xảo với thiết kế vương miện sang trọng, điểm xuyết những viên đá nhỏ sáng lấp lánh ở phần chân và đỉnh. Sợi dây bạc dạng hạt tròn đều đặn càng làm nổi bật vẻ đẹp tinh tế và quý phái. Biểu tượng vương miện mang ý nghĩa về quyền lực, sự thành công và địa vị, là món trang sức lý tưởng để khẳng định phong cách cá nhân hoặc làm quà tặng tôn vinh người thân yêu.', 'pnj_md014.jpg', 9, 2, '1', '2026-02-25 16:25:10'),
(235, 'Mặt dây Ngôi Sao Bạc Lấp Lánh', 'PNJMD015', 1600000.00, NULL, 'Bạc 925', 'Đá CZ', 1.90, 'Mặt dây chuyền bạc tinh tế với thiết kế ngôi sao năm cánh dạng viền, được đính những viên đá nhỏ sáng rực rỡ, tạo hiệu ứng lung linh đầy cuốn hút. Sợi dây bạc mảnh mai càng làm nổi bật vẻ đẹp thanh lịch và hiện đại. Biểu tượng ngôi sao mang ý nghĩa về hy vọng, sự dẫn lối và tỏa sáng, là món trang sức lý tưởng để khẳng định phong cách cá nhân hoặc làm quà tặng ý nghĩa cho người thân yêu.', 'pnj_md015.jpg', 9, 2, '1', '2026-02-25 16:25:10'),
(236, 'Mặt dây Chữ P Vàng Cá Nhân', 'PNJMD016', 8900000.00, NULL, 'Vàng 18K', 'Không', 2.20, 'Mặt dây chuyền vàng sang trọng với thiết kế chữ p cách điệu, đường nét mềm mại và bóng mượt. Bề mặt sáng bóng phản chiếu ánh sáng tinh tế, mang lại vẻ đẹp hiện đại nhưng vẫn giữ nét thanh lịch. Phần móc nối chắc chắn giúp dễ dàng kết hợp với nhiều loại dây chuyền, tạo nên phong cách cá nhân độc đáo. Đây là món trang sức lý tưởng để thể hiện dấu ấn riêng, đồng thời là quà tặng ý nghĩa dành cho người mang tên hoặc chữ cái bắt đầu bằng P.', 'pnj_md016.jpg', 9, 1, '1', '2026-02-25 16:25:10'),
(237, 'Mặt dây Trái Tim Song Hành', 'PNJMD017', 15000000.00, NULL, 'Vàng 18K', 'Không', 2.60, 'Mặt dây chuyền vàng tinh tế với thiết kế trái tim mở duyên dáng, bên trong treo một trái tim nhỏ đầy ý nghĩa. Bề mặt vàng bóng mượt phản chiếu ánh sáng sang trọng, kết hợp cùng sợi dây mảnh mai tạo nên vẻ đẹp thanh lịch và hiện đại. Biểu tượng hai trái tim song hành tượng trưng cho tình yêu, sự gắn kết và đồng điệu, là món trang sức lý tưởng để làm quà tặng cho người thân yêu hoặc để tự mình lưu giữ những khoảnh khắc đáng nhớ.', 'pnj_md017.jpg', 9, 1, '1', '2026-02-25 16:25:10'),
(238, 'Mặt dây Kim Cương Vuông Tinh Tế', 'PNJMD018', 29500000.00, 28500000.00, 'Vàng 18K', 'Kim cương tự nhiên', 3.20, 'Mặt dây chuyền vàng sang trọng với viên đá vuông cắt kiểu princess, góc cạnh sắc nét và ánh sáng rực rỡ. Viên đá được cố định bằng bốn chấu vàng chắc chắn, tạo nên sự cân đối và nổi bật. Sợi dây vàng mảnh mai càng làm tăng vẻ đẹp thanh lịch, mang lại phong cách tối giản nhưng đầy đẳng cấp. Đây là món trang sức lý tưởng để làm điểm nhấn tinh tế trong những dịp đặc biệt, đồng thời thể hiện sự sang trọng và gu thẩm mỹ tinh tế của người sở hữu.', 'pnj_md018.jpg', 9, 1, '1', '2026-02-25 16:25:10'),
(239, 'Mặt dây Cỏ Bốn Lá Vàng May Mắn', 'PNJMD019', 10500000.00, NULL, 'Vàng 18K', 'Không', 2.50, 'Mặt dây chuyền vàng tinh tế với thiết kế cỏ bốn lá, mỗi lá mang hình trái tim mềm mại, bóng mượt và phản chiếu ánh sáng sang trọng. Sợi dây vàng xoắn độc đáo càng làm nổi bật vẻ đẹp thanh lịch và quý phái. Biểu tượng cỏ bốn lá từ lâu đã gắn liền với sự may mắn, hạnh phúc và thịnh vượng, là món trang sức lý tưởng để mang theo bên mình như một lời chúc tốt lành, hoặc làm quà tặng ý nghĩa cho người thân yêu.', 'pnj_md019.jpg', 9, 1, '1', '2026-02-25 16:25:10'),
(240, 'Mặt dây Ngôi Sao Vàng Tỏa Sáng', 'PNJMD020', 31000000.00, 30000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 3.40, 'Mặt dây chuyền vàng nhỏ nhắn với thiết kế ngôi sao năm cánh, tâm điểm là viên đá sáng lấp lánh ở giữa. Bề mặt vàng bóng mượt cùng đường nét tinh tế tạo nên vẻ đẹp tối giản nhưng sang trọng. Phần móc nối chắc chắn giúp dễ dàng kết hợp với nhiều loại dây chuyền, mang lại phong cách hiện đại và thanh lịch. Biểu tượng ngôi sao tượng trưng cho sự dẫn lối, hy vọng và tỏa sáng, là món trang sức lý tưởng để làm quà tặng ý nghĩa hoặc điểm nhấn cá nhân đầy tinh tế.', 'pnj_md020.jpg', 9, 1, '1', '2026-02-25 16:25:10'),
(241, 'Mặt dây Bướm Vàng Thanh Xuân', 'PNJMD021', 9800000.00, NULL, 'Vàng 18K', 'Không', 2.30, 'Mặt dây chuyền vàng tinh xảo với thiết kế hình bướm duyên dáng, đôi cánh khắc họa chi tiết mềm mại và đầy nghệ thuật. Sợi dây vàng mảnh mai càng làm nổi bật vẻ đẹp thanh lịch, nhẹ nhàng. Biểu tượng bướm mang ý nghĩa về sự biến đổi, tự do và vẻ đẹp của tuổi trẻ, là món trang sức lý tưởng để khẳng định phong cách cá nhân hoặc làm quà tặng ý nghĩa cho người thân yêu.', 'pnj_md021.jpg', 9, 1, '1', '2026-02-25 16:25:10'),
(242, 'Mặt dây Sóng Vàng Biển Cả', 'PNJMD022', 11000000.00, NULL, 'Vàng 18K', 'Không', 2.70, 'Mặt dây chuyền vàng độc đáo với thiết kế vòng tròn, bên trong khắc họa hình ảnh sóng biển cuộn trào đầy nghệ thuật. Bề mặt vàng bóng mượt kết hợp cùng chi tiết chạm khắc tinh xảo tạo nên cảm giác chuyển động sống động và mạnh mẽ. Sợi dây vàng thanh lịch càng làm nổi bật vẻ đẹp tự nhiên, mang lại phong cách phóng khoáng nhưng vẫn sang trọng. Biểu tượng sóng biển gợi nhắc đến sự tự do, sức mạnh và hành trình bất tận, là món trang sức lý tưởng cho những ai yêu thích thiên nhiên và khát vọng vươn xa.', 'pnj_md022.jpg', 9, 1, '1', '2026-02-25 16:25:10'),
(243, 'Mặt dây Hoa Bạc Thanh Khiết', 'PNJMD023', 1700000.00, NULL, 'Bạc 925', 'Đá CZ', 2.00, 'Mặt dây chuyền bạc tinh tế với thiết kế bông hoa năm cánh cân đối, mỗi cánh mang bề mặt bóng mượt phản chiếu ánh sáng sang trọng. Tâm hoa được điểm xuyết bằng viên đá nhỏ sáng lấp lánh, tạo điểm nhấn đầy cuốn hút. Sợi dây bạc dạng hộp mảnh mai càng làm nổi bật vẻ đẹp thanh lịch và nữ tính. Biểu tượng hoa mang ý nghĩa về sự tươi mới, vẻ đẹp tự nhiên và niềm hạnh phúc, là món trang sức lý tưởng để đeo hàng ngày hoặc trong những dịp đặc biệt.', 'pnj_md023.jpg', 9, 2, '1', '2026-02-25 16:25:10'),
(244, 'Mặt dây Vô Cực Song Sắc', 'PNJMD024', 1650000.00, NULL, 'Bạc 925', 'Đá CZ', 1.90, 'Mặt dây chuyền tinh xảo với thiết kế biểu tượng vô cực, một bên đính đá đen huyền bí, bên còn lại đính đá trắng lấp lánh. Sự tương phản giữa hai gam màu tạo nên hiệu ứng thị giác độc đáo, vừa sang trọng vừa cá tính. Sợi dây mảnh mai càng làm nổi bật vẻ đẹp thanh lịch, mang lại phong cách hiện đại và đầy ý nghĩa. Biểu tượng vô cực tượng trưng cho tình yêu bất tận, sự gắn kết và trường tồn, là món trang sức lý tưởng để khẳng định phong cách riêng hoặc làm quà tặng đặc biệt.', 'pnj_md024.jpg', 9, 2, '1', '2026-02-25 16:25:10'),
(245, 'Mặt dây Kim Cương Vàng Rực Rỡ', 'PNJMD025', 18500000.00, NULL, 'Vàng 18K', 'Không', 2.90, 'Mặt dây chuyền vàng sang trọng với viên kim cương cắt tròn sáng lấp lánh, được cố định bằng bốn chấu vàng chắc chắn. Thiết kế đơn giản nhưng tinh tế, tôn vinh vẻ đẹp thuần khiết của viên đá quý. Phần móc nối hình chữ V thanh lịch giúp dễ dàng kết hợp với nhiều loại dây chuyền, mang lại phong cách hiện đại và đẳng cấp. Đây là món trang sức lý tưởng để làm điểm nhấn trong những dịp đặc biệt, đồng thời thể hiện sự tinh tế và gu thẩm mỹ sang trọng của người sở hữu.', 'pnj_md025.jpg', 9, 1, '1', '2026-02-25 16:25:10'),
