(269, 'Lắc Tay Nam PNJ Royal', 'PNJNM324', 38500000.00, 36500000.00, 'Vàng 18K', 'Không', 17.50, 'Phong cách hoàng gia.', 'pnj_nm324.jpg', 11, 1, '1', '2026-02-25 16:27:30'),
(270, 'Nhẫn Nam PNJ Gold Minimal', 'PNJNM325', 18000000.00, NULL, 'Vàng 18K', 'Không', 6.50, 'Thiết kế tối giản hiện đại.', 'pnj_nm325.jpg', 11, 1, '1', '2026-02-25 16:27:30'),
(271, 'Charm trái tim vàng', 'PNJCH001', 5200000.00, NULL, 'Vàng 18K', 'Không', 1.20, 'Mặt charm hình trái tim bằng vàng, bề mặt bóng mịn phản chiếu ánh sáng sang trọng. Thiết kế đơn giản nhưng tinh tế, gắn liền với vòng tròn nối để dễ dàng kết hợp cùng dây chuyền hoặc vòng tay. Hình ảnh gợi lên sự ngọt ngào, tình yêu và sự gắn bó, phù hợp làm món quà ý nghĩa dành cho người thương.', 'pnj_ch001.jpg', 12, 1, '1', '2026-02-25 16:30:24'),
(272, 'Charm ngôi sao vàng', 'PNJCH002', 4800000.00, NULL, 'Vàng 18K', 'Không', 1.10, 'Mặt charm hình ngôi sao năm cánh bằng vàng, với họa tiết khắc nổi tỏa ra từ tâm tạo hiệu ứng ánh sáng rực rỡ. Thiết kế tinh xảo, gắn liền với vòng tròn nhỏ phía trên để dễ dàng kết hợp cùng dây chuyền hoặc vòng tay. Hình ảnh mang đến cảm giác tỏa sáng, may mắn và sang trọng – một biểu tượng hoàn hảo cho sự rực rỡ và niềm tin.', 'pnj_ch002.jpg', 12, 1, '1', '2026-02-25 16:30:24'),
(273, 'Charm hoa vàng', 'PNJCH003', 5500000.00, NULL, 'Vàng 18K', 'Không', 1.30, 'Mặt charm hình bông hoa năm cánh bằng vàng, thiết kế tối giản với cánh tròn mềm mại và tâm hoa nhỏ xinh. Bề mặt sáng bóng tạo cảm giác sang trọng, gắn liền với vòng nối chắc chắn để dễ dàng kết hợp cùng vòng tay hoặc dây chuyền. Hình ảnh mang đến sự thanh lịch, nữ tính và tươi mới – biểu tượng cho vẻ đẹp dịu dàng và sự khởi đầu đầy may mắn.', 'pnj_ch003.jpg', 12, 1, '1', '2026-02-25 16:30:24'),
(274, 'Charm cỏ 4 lá vàng', 'PNJCH004', 5100000.00, NULL, 'Vàng 18K', 'Không', 1.20, 'Mặt charm hình cỏ 4 lá bằng vàng, thiết kế bo tròn mềm mại với bề mặt sáng bóng phản chiếu ánh sáng sang trọng. Phần móc nối nhỏ gọn phía trên giúp dễ dàng gắn vào dây chuyền hoặc vòng tay. Biểu tượng cỏ 4 lá từ lâu được xem là dấu hiệu của may mắn, nay kết hợp cùng chất liệu vàng càng làm tăng thêm giá trị và ý nghĩa – vừa tinh tế, vừa mang thông điệp hạnh phúc và thịnh vượng.', 'pnj_ch004.jpg', 12, 1, '1', '2026-02-25 16:30:24'),
(275, 'Charm vô cực vàng', 'PNJCH005', 6000000.00, NULL, 'Vàng 18K', 'Không', 1.40, 'Mặt charm hình biểu tượng vô cực bằng vàng, thiết kế mềm mại với đường cong liền mạch và bề mặt sáng bóng phản chiếu ánh sáng sang trọng. Phần móc nối nhỏ gọn phía trên giúp dễ dàng gắn vào dây chuyền hoặc vòng tay. Biểu tượng vô cực từ lâu được xem là đại diện cho tình yêu vĩnh cửu, sự gắn bó không giới hạn và niềm tin bền chặt – một món trang sức vừa tinh tế vừa đầy ý nghĩa.', 'pnj_ch005.jpg', 12, 1, '1', '2026-02-25 16:30:24'),
(276, 'Charm đá vuông vàng', 'PNJCH006', 12500000.00, 12000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 1.50, 'Mặt charm vàng gắn viên đá trong suốt cắt vuông, tỏa sáng với những đường cắt tinh xảo phản chiếu ánh sáng lấp lánh. Khung vàng ôm trọn viên đá, kết hợp cùng móc nối nhỏ gọn phía trên để dễ dàng gắn vào dây chuyền. Thiết kế tối giản nhưng sang trọng, mang đến vẻ đẹp thanh lịch và hiện đại – biểu tượng cho sự tinh khiết và quý phái.', 'pnj_ch006.jpg', 12, 1, '1', '2026-02-25 16:30:24'),
(277, 'Charm hồng ngọc vàng', 'PNJCH007', 9800000.00, NULL, 'Vàng 18K', 'Ruby', 1.40, 'Mặt charm nhỏ nhắn bằng vàng, nổi bật với viên đá đỏ tròn cắt giác tinh xảo, tỏa ánh sáng rực rỡ. Khung vàng ôm trọn viên đá, kết hợp cùng móc nối gọn gàng phía trên để dễ dàng gắn vào dây chuyền, vòng tay hoặc khuyên tai. Sự kết hợp giữa sắc đỏ sâu thẳm và ánh vàng sang trọng mang đến vẻ đẹp quý phái, tượng trưng cho tình yêu nồng nhiệt và sự may mắn.', 'pnj_ch007.jpg', 12, 1, '1', '2026-02-25 16:30:24'),
(278, 'Charm sapphire vàng', 'PNJCH008', 9900000.00, NULL, 'Vàng 18K', 'Sapphire', 1.40, 'Mặt charm nhỏ nhắn bằng vàng, nổi bật với viên đá xanh đậm tròn cắt giác tinh xảo, tỏa ánh sáng lấp lánh. Khung vàng ôm trọn viên đá, kết hợp cùng móc nối gọn gàng phía trên để dễ dàng gắn vào dây chuyền hoặc vòng tay. Sự kết hợp giữa sắc xanh sâu thẳm và ánh vàng sang trọng mang đến vẻ đẹp thanh lịch, tượng trưng cho sự trí tuệ, niềm tin và sự vĩnh cửu.', 'pnj_ch008.jpg', 12, 1, '1', '2026-02-25 16:30:24'),
(279, 'Charm nơ bạc', 'PNJCH009', 5300000.00, NULL, 'Vàng trắng 18K', 'Không', 1.20, 'Mặt charm hình chiếc nơ nhỏ xinh bằng kim loại sáng bóng, thiết kế cân đối với hai vòng cung mềm mại và hai dải ruy băng buông xuống. Phần móc nối phía trên giúp dễ dàng gắn vào dây chuyền hoặc vòng tay. Hình ảnh mang đến cảm giác tinh tế, nữ tính và duyên dáng – biểu tượng cho sự ngọt ngào và thanh lịch trong phong cách trang sức.', 'pnj_ch009.jpg', 12, 1, '1', '2026-02-25 16:30:24'),
(280, 'Charm hoa hồng vàng', 'PNJCH010', 5400000.00, NULL, 'Vàng 18K', 'Không', 1.20, 'Mặt charm hình hoa hồng bằng vàng, thiết kế tinh xảo với cánh hoa mềm mại, thân và hai chiếc lá nhỏ tạo nên tổng thể duyên dáng. Phần móc nối phía trên giúp dễ dàng gắn vào dây chuyền hoặc vòng tay. Hình ảnh mang đến vẻ đẹp lãng mạn, sang trọng và đầy biểu tượng – hoa hồng vốn là biểu tượng của tình yêu, sự ngọt ngào và sự trân trọng.', 'pnj_ch010.jpg', 12, 1, '1', '2026-02-25 16:30:24'),
(281, 'Charm trái tim bạc', 'PNJCH011', 850000.00, NULL, 'Bạc 925', 'Không', 0.90, 'Mặt charm hình trái tim bằng bạc sáng bóng, thiết kế tối giản với đường nét mềm mại và bề mặt phản chiếu ánh sáng sang trọng. Phần móc nối tròn phía trên giúp dễ dàng gắn vào dây chuyền, vòng tay hoặc móc khóa. Hình ảnh mang đến vẻ đẹp tinh tế, hiện đại và ý nghĩa – biểu tượng cho tình yêu, sự gắn bó và sự thuần khiết.', 'pnj_ch011.jpg', 12, 2, '1', '2026-02-25 16:30:24'),
(282, 'Charm ngôi sao bạc ', 'PNJCH012', 900000.00, NULL, 'Bạc 925', 'Không', 0.90, 'Mặt charm hình ngôi sao bạc với thiết kế cắt rỗng ở giữa, tạo nên vẻ ngoài tối giản nhưng hiện đại. Các đường nét sắc sảo kết hợp cùng bề mặt sáng bóng mang lại cảm giác tinh tế và sang trọng. Phần móc nối nhỏ gọn phía trên giúp dễ dàng gắn vào dây chuyền hoặc vòng tay. Đây là biểu tượng cho sự tỏa sáng và khát vọng, phù hợp làm điểm nhấn nổi bật trong phong cách trang sức.', 'pnj_ch012.jpg', 12, 2, '1', '2026-02-25 16:30:24'),
(283, 'Charm cỏ 4 lá bạc', 'PNJCH013', 950000.00, NULL, 'Bạc 925', 'Đá CZ', 1.00, 'Mặt charm hình cỏ 4 lá bằng bạc sáng bóng, thiết kế tinh xảo với các đường khắc nhẹ nhàng tạo hình lá và thân. Phần móc nối phía trên giúp dễ dàng gắn vào dây chuyền, vòng tay hoặc móc khóa. Biểu tượng cỏ 4 lá vốn được xem là dấu hiệu của may mắn, nay kết hợp cùng chất liệu bạc càng làm tăng thêm vẻ đẹp thanh lịch và ý nghĩa – mang đến sự bình an, hạnh phúc và thịnh vượng cho người sở hữu.', 'pnj_ch013.jpg', 12, 2, '1', '2026-02-25 16:30:24'),
(284, 'Charm hoa lily bạc', 'PNJCH014', 980000.00, NULL, 'Bạc 925', 'Đá CZ', 1.00, 'Mặt charm hình hoa lily bằng bạc, thiết kế tinh xảo với cánh hoa mềm mại và nhụy hoa nổi bật, tạo cảm giác sống động như thật. Bề mặt sáng bóng phản chiếu ánh sáng sang trọng, kết hợp cùng móc nối nhỏ gọn phía trên để dễ dàng gắn vào dây chuyền hoặc vòng tay. Hoa lily vốn tượng trưng cho sự tinh khiết, thanh cao và niềm hy vọng, khiến món trang sức này trở thành điểm nhấn đầy ý nghĩa và thanh lịch.', 'pnj_ch014.jpg', 12, 2, '1', '2026-02-25 16:30:24'),
(285, 'Charm vương miện đá quý', 'PNJCH015', 1100000.00, NULL, 'Bạc 925', 'Đá CZ', 1.10, 'Mặt charm hình vương miện nhỏ nhắn, chế tác tinh xảo với các chi tiết hạt nổi và đường cong mềm mại. Ở trung tâm nổi bật viên đá trong suốt cắt giác, tỏa ánh sáng lấp lánh, tạo điểm nhấn sang trọng. Phần móc nối phía trên giúp dễ dàng gắn vào dây chuyền hoặc vòng tay. Vương miện vốn là biểu tượng của quyền lực, sự cao quý và thành công – khiến món trang sức này trở thành phụ kiện đầy ý nghĩa và đẳng cấp.', 'pnj_ch015.jpg', 12, 2, '1', '2026-02-25 16:30:24'),
(286, 'Charm mèo may mắn ', 'PNJCH016', 6200000.00, NULL, 'Vàng 18K', 'Không', 1.50, 'Mặt charm hình mèo may mắn (Maneki-neko) bằng vàng, thiết kế tinh xảo với dáng ngồi thẳng, một chân giơ cao và tay cầm đồng xu – biểu tượng truyền thống của sự thịnh vượng và tài lộc trong văn hóa Nhật Bản và Trung Hoa. Bề mặt sáng bóng phản chiếu ánh sáng sang trọng, kết hợp cùng móc nối nhỏ gọn phía trên để dễ dàng gắn vào dây chuyền hoặc vòng tay. Đây là món trang sức mang ý nghĩa phong thủy, vừa tinh tế vừa đem lại may mắn cho người sở hữu.', 'pnj_ch016.jpg', 12, 1, '1', '2026-02-25 16:30:24'),
(287, 'Charm túi vàng Phúc', 'PNJCH017', 6800000.00, NULL, 'Vàng 18K', 'Không', 1.60, 'Mặt charm hình túi vàng nhỏ nhắn, thiết kế tinh tế với phần thắt nơ ở miệng túi và bề mặt nhẵn mịn sang trọng. Trên thân charm khắc chữ “福” – biểu tượng cho phúc lộc, may mắn và thịnh vượng trong văn hóa Á Đông. Phần móc nối phía trên giúp dễ dàng gắn vào dây chuyền hoặc vòng tay. Đây là món trang sức mang ý nghĩa phong thủy, vừa thanh lịch vừa đem lại tài lộc cho người sở hữu.', 'pnj_ch017.jpg', 12, 1, '1', '2026-02-25 16:30:24'),
(288, 'Charm nơ vàng', 'PNJCH018', 6400000.00, NULL, 'Vàng 18K', 'Không', 1.50, 'Mặt charm hình chiếc nơ bằng vàng, thiết kế mềm mại với hai vòng cung cân đối và hai dải ruy băng buông xuống duyên dáng. Bề mặt sáng bóng phản chiếu ánh sáng sang trọng, kết hợp cùng móc nối nhỏ gọn phía trên để dễ dàng gắn vào dây chuyền hoặc vòng tay. Hình ảnh mang đến vẻ đẹp tinh tế, nữ tính và thanh lịch – biểu tượng cho sự duyên dáng và ngọt ngào trong phong cách trang sức.', 'pnj_ch018.jpg', 12, 1, '1', '2026-02-25 16:30:24'),
(289, 'Charm bạc Lucky', 'PNJCH019', 990000.00, NULL, 'Bạc 925', 'Đá CZ', 1.00, 'Mặt charm tròn bằng bạc với nền họa tiết khắc tinh xảo, nổi bật dòng chữ “Lucky 13” cùng các hoa văn nhỏ xung quanh. Viền ngoài thiết kế dạng scallop mềm mại, tạo cảm giác cổ điển và độc đáo. Phần móc nối phía trên giúp dễ dàng gắn vào dây chuyền hoặc vòng tay. Con số 13 thường gắn liền với sự mê tín, nhưng ở đây lại được biến thành biểu tượng may mắn, mang ý nghĩa phá cách và cá tính cho người sở hữu.', 'pnj_ch019.jpg', 12, 2, '1', '2026-02-25 16:30:24'),
(290, 'Charm vô cực bạc đính đá', 'PNJCH020', 1050000.00, NULL, 'Bạc 925', 'Đá CZ', 1.10, 'Mặt charm hình biểu tượng vô cực bằng bạc, thiết kế mềm mại với đường cong liền mạch. Tại điểm giao nhau, charm được đính hàng đá trong suốt cắt giác tinh xảo, tỏa ánh sáng lấp lánh, tạo điểm nhấn sang trọng. Phần móc nối phía trên giúp dễ dàng gắn vào dây chuyền hoặc vòng tay. Biểu tượng vô cực vốn tượng trưng cho tình yêu vĩnh cửu, sự gắn bó không giới hạn – một món trang sức vừa tinh tế vừa đầy ý nghĩa.', 'pnj_ch020.jpg', 12, 2, '1', '2026-02-25 16:30:24'),
(291, 'Charm bóng bay vàng số 8', 'PNJCH021', 5900000.00, NULL, 'Vàng 18K', 'Không', 1.30, 'Mặt charm hình ba quả bóng bay bằng vàng, thiết kế tinh xảo với bề mặt sáng bóng sang trọng. Một quả bóng nổi bật với số “8” khắc rõ nét, gợi liên tưởng đến ngày kỷ niệm, sinh nhật hoặc cột mốc đặc biệt. Phần móc nối nhỏ gọn phía trên giúp dễ dàng gắn vào dây chuyền hoặc vòng tay. Đây là món trang sức mang ý nghĩa vui tươi, hạnh phúc và kỷ niệm đáng nhớ, đồng thời tượng trưng cho sự thịnh vượng và may mắn.', 'pnj_ch021.jpg', 12, 1, '1', '2026-02-25 16:30:24'),
(292, 'Charm cánh thiên thần vàng', 'PNJCH022', 6100000.00, NULL, 'Vàng 18K', 'Không', 1.40, 'Mặt charm hình cánh thiên thần bằng vàng, thiết kế tinh xảo với từng đường khắc lông vũ mềm mại, tạo cảm giác sống động và sang trọng. Bề mặt sáng bóng phản chiếu ánh sáng rực rỡ, kết hợp cùng móc nối nhỏ gọn phía trên để dễ dàng gắn vào dây chuyền hoặc vòng tay. Cánh thiên thần vốn tượng trưng cho sự bảo hộ, tự do và tâm linh – một món trang sức vừa thanh lịch vừa mang ý nghĩa sâu sắc.', 'pnj_ch022.jpg', 12, 1, '1', '2026-02-25 16:30:24'),
(293, 'Charm trái tim bạc True Love', 'PNJCH023', 970000.00, NULL, 'Bạc 925', 'Đá CZ', 1.00, 'Mặt charm hình trái tim bằng bạc, khắc dòng chữ “true love” đầy ý nghĩa. Thiết kế tinh tế với một viên đá nhỏ sáng lấp lánh ở góc trên, tạo điểm nhấn sang trọng và lãng mạn. Phần móc nối phía trên giúp dễ dàng gắn vào dây chuyền hoặc vòng tay. Đây là món trang sức tượng trưng cho tình yêu chân thành, sự gắn bó và cam kết vĩnh cửu – một phụ kiện vừa tinh tế vừa giàu cảm xúc.', 'pnj_ch023.jpg', 12, 2, '1', '2026-02-25 16:30:24'),
(294, 'Charm vương miện vàng', 'PNJCH024', 7200000.00, 6500000.00, 'Vàng 18K', 'Không', 1.70, 'Mặt charm hình vương miện bằng vàng, chế tác tinh xảo với phần đế tròn khắc họa tiết nhỏ và các đường cong uốn lên tạo dáng vương miện sang trọng. Bề mặt sáng bóng phản chiếu ánh sáng lấp lánh, kết hợp cùng móc nối phía trên để dễ dàng gắn vào dây chuyền hoặc vòng tay. Vương miện vốn là biểu tượng của quyền lực, sự cao quý và thành công – một món trang sức vừa thanh lịch vừa mang ý nghĩa đặc biệt.', 'pnj_ch024.jpg', 12, 1, '0', '2026-02-25 16:30:24'),
(295, 'Charm ngôi sao vàng đính đá', 'PNJCH025', 13500000.00, 13000000.00, 'Vàng 18K', 'Kim cương tự nhiên', 1.60, 'Mặt charm hình ngôi sao bằng vàng, viền ngoài được đính những viên đá trong suốt lấp lánh, tạo hiệu ứng sang trọng và nổi bật. Thiết kế tinh tế kết hợp ánh sáng ấm áp của vàng cùng sự rực rỡ của đá quý, mang lại vẻ đẹp vừa thanh lịch vừa cuốn hút. Phần móc nối nhỏ gọn phía trên giúp dễ dàng gắn vào dây chuyền hoặc vòng tay. Ngôi sao vốn là biểu tượng của sự tỏa sáng, khát vọng và thành công – một món trang sức đầy ý nghĩa và phong cách.', 'pnj_ch025.jpg', 12, 1, '1', '2026-02-25 16:30:24'),
(296, 'đồng hồ Olym Pianus', 'PNJDH001', 12500000.00, NULL, 'Thép mạ vàng', 'Không', 85.00, 'Chiếc đồng hồ đeo tay Olym Pianus sang trọng với lớp vỏ và dây kim loại mạ vàng, mặt số trắng tinh tế cùng các cọc giờ và kim vàng nổi bật. Điểm nhấn là kim giây màu đỏ tạo sự khác biệt, cùng ô lịch ngày ở vị trí 3 giờ và mặt phụ hiển thị 24 giờ tại vị trí 9 giờ. Mặt kính sapphire chống trầy xước kết hợp bộ máy automatic chuẩn Nhật Bản, mang đến độ bền và sự chính xác cao. Đây là sự kết hợp hoàn hảo giữa thiết kế thanh lịch và công nghệ chế tác tinh xảo, phù hợp cho người yêu thích phong cách sang trọng và đẳng cấp.', 'pnj_dh001.jpg', 13, 1, '1', '2026-02-25 16:35:54'),
(297, 'Đồng Hồ Rolex Day-Date vàng đính kim cương', 'PNJDH002', 28500000.00, 27500000.00, 'Thép mạ vàng', 'Kim cương tự nhiên', 90.00, 'Chiếc đồng hồ Rolex sang trọng với dây và vỏ vàng nổi bật, mặt số cam rực rỡ tạo điểm nhấn độc đáo. Vành bezel đính kim cương lấp lánh, cùng các cọc số La Mã cũng được nạm đá quý, mang lại vẻ đẹp tinh xảo và đẳng cấp. Trên mặt số hiển thị lịch thứ ở vị trí 12 giờ và lịch ngày phóng đại ở vị trí 3 giờ, kết hợp bộ máy Oyster Perpetual Day-Date chuẩn xác, được chứng nhận Superlative Chronometer. Đây là biểu tượng của sự thành công, quyền lực và phong cách xa hoa.', 'pnj_dh002.jpg', 13, 1, '1', '2026-02-25 16:35:54'),
(298, 'Đồng hồ Rosefield vàng mặt vuông', 'PNJDH003', 18500000.00, NULL, 'Thép mạ vàng', 'Không', 88.00, 'Chiếc đồng hồ Rosefield với thiết kế hiện đại pha chút cổ điển, dây và vỏ vàng sang trọng cùng mặt số trắng tối giản. Các cọc số vàng tại vị trí 12, 3, 6, 9 kết hợp kim giờ và phút thanh mảnh, tạo nên vẻ tinh tế và thanh lịch. Dòng chữ “ROSEFIELD – AMS | NYC” trên mặt số khẳng định sự kết nối giữa Amsterdam và New York, mang phong cách thời thượng quốc tế. Thiết kế mặt vuông độc đáo giúp chiếc đồng hồ trở thành phụ kiện nổi bật, phù hợp cho người yêu thích sự tinh giản nhưng vẫn đẳng cấp.', 'pnj_dh003.jpg', 13, 1, '1', '2026-02-25 16:35:54'),
(299, 'Đồng Hồ Patek Philippe Tiffany vàng đính ruby', 'PNJDH004', 22000000.00, NULL, 'Thép không gỉ', 'Không', 95.00, 'Chiếc đồng hồ Patek Philippe sang trọng với dây và vỏ vàng, kết hợp mặt số tối giản đầy tinh tế. Vành bezel được nạm ruby đỏ rực rỡ, cùng các cọc số vàng xen kẽ đá quý tạo nên vẻ đẹp nổi bật và đẳng cấp. Trên mặt số in tên hai thương hiệu danh giá Patek Philippe – Tiffany & Co., khẳng định sự hợp tác hiếm có và giá trị sưu tầm đặc biệt. Ô lịch ngày ở vị trí 3 giờ tăng thêm tính tiện dụng, trong khi toàn bộ thiết kế toát lên sự xa hoa, quyền lực và phong cách tinh tế.', 'pnj_dh004.jpg', 13, 1, '1', '2026-02-25 16:35:54'),
(300, 'Đồng Hồ Patek Philippe vàng hồng mặt trắng', 'PNJDH005', 16500000.00, NULL, 'Thép mạ vàng hồng', 'Không', 82.00, 'Chiếc đồng hồ Patek Philippe đẳng cấp với dây và vỏ vàng hồng sang trọng, mặt số trắng trang trí họa tiết sóng ngang tinh tế. Các cọc số và kim vàng nổi bật trên nền sáng, kết hợp ô lịch ngày ở vị trí 6 giờ tiện dụng. Dòng chữ “Patek Philippe Genève” khẳng định thương hiệu chế tác đồng hồ hàng đầu thế giới, cùng dòng “Swiss Made” thể hiện sự chuẩn xác và chất lượng Thụy Sĩ. Thiết kế thanh lịch, sang trọng nhưng vẫn hiện đại, phù hợp cho người yêu thích phong cách tinh tế và đẳng cấp.', 'pnj_dh005.jpg', 13, 1, '1', '2026-02-25 16:35:54'),
(301, 'Đồng Hồ Piaget Automatic thép không gỉ', 'PNJDH006', 6500000.00, NULL, 'Thép không gỉ', 'Không', 80.00, 'Chiếc đồng hồ Piaget sang trọng với dây và vỏ thép không gỉ bóng bẩy, mặt số tròn màu bạc tinh tế. Thiết kế tối giản nhưng đẳng cấp với các cọc số và kim bạc sắc nét, cùng ô lịch ngày ở vị trí 6 giờ tiện dụng. Dòng chữ “Piaget – Automatic” khẳng định bộ máy cơ khí chuẩn xác, kết hợp phong cách thanh lịch và sự tinh xảo trong chế tác. Đây là mẫu đồng hồ lý tưởng cho người yêu thích sự sang trọng, hiện đại và độ bền vượt thời gian.', 'pnj_dh006.jpg', 13, 2, '1', '2026-02-25 16:35:54'),
(302, 'Đồng hồ tối giản B-logo', 'PNJDH007', 5900000.00, NULL, 'Thép không gỉ', 'Không', 78.00, 'Chiếc đồng hồ sang trọng với dây và vỏ kim loại bạc sáng bóng, thiết kế mặt số tròn tối giản. Các cọc số thanh mảnh cùng kim giờ và phút tinh tế, kết hợp ô lịch ngày ở vị trí 6 giờ tiện dụng. Điểm nhấn là logo chữ “B” ngay dưới vị trí 12 giờ, tạo dấu ấn thương hiệu hiện đại. Vành bezel có chi tiết khía mảnh tinh xảo, mang lại vẻ ngoài thanh lịch và tinh tế. Đây là mẫu đồng hồ lý tưởng cho người yêu thích phong cách tối giản – hiện đại – sang trọng.', 'pnj_dh007.jpg', 13, 2, '1', '2026-02-25 16:35:54'),
(303, 'Đồng Hồ IWC Schaffhausen Chronograph Automatic', 'PNJDH008', 8900000.00, NULL, 'Thép không gỉ', 'Không', 92.00, 'Chiếc đồng hồ IWC Schaffhausen cao cấp với dây và vỏ thép không gỉ sang trọng, mặt số trắng nổi bật cùng các chữ số Ả Rập màu xanh và kim xanh tinh tế. Thiết kế chronograph với hai mặt phụ tại vị trí 12 giờ và 6 giờ, kết hợp ô lịch ngày ở vị trí 6 giờ tiện dụng. Dòng chữ “Chronograph Automatic – IWC Schaffhausen – Swiss Made” khẳng định chất lượng chế tác Thụy Sĩ chuẩn xác. Đây là mẫu đồng hồ vừa mang tính thẩm mỹ tinh tế vừa thể hiện sự đẳng cấp và phong cách hiện đại.', 'pnj_dh008.jpg', 13, 2, '1', '2026-02-25 16:35:54'),
(304, 'Đồng Hồ Piaget Diamond Silver Dial', 'PNJDH009', 12500000.00, NULL, 'Thép không gỉ', 'Đá CZ', 85.00, 'Chiếc đồng hồ Piaget cao cấp với dây kim loại sáng bóng, thiết kế mặt số tròn bạc tối giản nhưng sang trọng. Các cọc số được nạm kim cương tinh xảo, kết hợp kim giờ và phút thanh mảnh, tạo nên vẻ đẹp thanh lịch. Vành bezel phủ kín kim cương lấp lánh, tôn lên sự xa hoa và đẳng cấp. Dòng chữ “Piaget – Swiss Made” khẳng định chất lượng chế tác chuẩn mực Thụy Sĩ. Đây là mẫu đồng hồ lý tưởng cho người yêu thích phong cách tinh tế, sang trọng và sự hoàn hảo trong từng chi tiết.', 'pnj_dh009.jpg', 13, 2, '1', '2026-02-25 16:35:54'),
(305, 'Đồng Hồ Carnival Moonphase Chronograph', 'PNJDH010', 14500000.00, NULL, 'Thép không gỉ', 'Không', 94.00, 'Chiếc đồng hồ Carnival sang trọng với dây thép không gỉ sáng bóng, mặt số trắng tinh tế kết hợp các cọc số La Mã và kim cương nhỏ. Thiết kế phức hợp với nhiều mặt phụ hiển thị giây, phút, giờ cùng chức năng moonphase ở vị trí 12 giờ, tạo nên vẻ đẹp vừa cổ điển vừa hiện đại. Dòng chữ “Carnival” khẳng định thương hiệu, trong khi toàn bộ chi tiết được chế tác tinh xảo, mang lại sự đẳng cấp và phong cách sang trọng. Đồng hồ được đặt trên gối da trắng trong hộp trưng bày, càng làm nổi bật giá trị và sự tinh tế của sản phẩm.', 'pnj_dh010.jpg', 13, 2, '1', '2026-02-25 16:35:54'),
(306, 'Đồng Hồ Patek Philippe Tourbillon ', 'PNJDH011', 13500000.00, NULL, 'Thép mạ vàng', 'Không', 83.00, 'Chiếc đồng hồ Patek Philippe đẳng cấp với vỏ vàng hồng sang trọng và dây da đen vân cá sấu tinh tế. Mặt số đen nổi bật với các cọc số và kim vàng, kết hợp ô lịch ngày ở vị trí 12 giờ. Điểm nhấn đặc biệt là mặt phụ hiển thị moonphase cùng cơ chế tourbillon tại vị trí 6 giờ, khẳng định sự tinh xảo và đỉnh cao trong nghệ thuật chế tác đồng hồ. Dòng chữ “Patek Philippe Genève – Tourbillon” khẳng định giá trị thương hiệu và độ chính xác tuyệt đối. Đây là mẫu đồng hồ dành cho người yêu thích sự sang trọng, quyền lực và kỹ thuật chế tác bậc thầy.', 'pnj_dh011.jpg', 13, 1, '1', '2026-02-25 16:35:54'),
(307, 'Đồng Hồ Chopard', 'PNJDH012', 15000000.00, NULL, 'Thép mạ vàng', 'Không', 87.00, 'Chiếc đồng hồ Chopard sang trọng với dây kim loại hai tông màu bạc và vàng hồng, tạo nên vẻ ngoài tinh tế và hiện đại. Mặt số khảm trai óng ánh, kết hợp các cọc số La Mã vàng ở vị trí 12, 3, 6, 9 cùng những viên kim cương nhỏ ở các vị trí còn lại, mang lại sự lấp lánh và đẳng cấp. Kim vàng thanh mảnh cùng logo “Chopard” viết tay tinh tế khẳng định thương hiệu xa xỉ Thụy Sĩ. Đây là mẫu đồng hồ lý tưởng cho người yêu thích sự kết hợp giữa sang trọng – nữ tính – tinh xảo.', 'pnj_dh012.jpg', 13, 1, '1', '2026-02-25 16:35:54'),
(308, 'Đồng Hồ Hublot Classic Fusion ', 'PNJDH013', 17500000.00, NULL, 'Thép mạ vàng', 'Không', 90.00, 'Chiếc đồng hồ Hublot sang trọng với vỏ vàng hồng nổi bật, viền bezel có ốc vít đặc trưng tạo dấu ấn mạnh mẽ. Mặt số đen tối giản nhưng tinh tế, kết hợp kim và cọc số vàng sang trọng cùng ô lịch ngày ở vị trí 3 giờ. Dây cao su đen mang lại sự thoải mái và phong cách thể thao hiện đại. Dòng chữ “Hublot – Automatic – Swiss Made” khẳng định chất lượng chế tác Thụy Sĩ chuẩn xác. Đây là mẫu đồng hồ lý tưởng cho người yêu thích sự kết hợp giữa sang trọng – cá tính – hiện đại.', 'pnj_dh013.jpg', 13, 1, '1', '2026-02-25 16:35:54'),
(309, 'Đồng Hồ Patek Philippe Perpetual Calendar Chronograph', 'PNJDH014', 29500000.00, NULL, 'Thép mạ vàng', 'Không', 96.00, 'Chiếc đồng hồ Patek Philippe đỉnh cao chế tác với vỏ vàng sang trọng và dây da đen vân cá sấu tinh tế. Mặt số màu kem nổi bật với nhiều chức năng phức tạp: hiển thị thứ và tháng ở vị trí 12 giờ, lịch ngày dạng vòng số kết hợp moonphase ở vị trí 6 giờ, cùng các mặt phụ chronograph chuẩn xác. Kim vàng kết hợp kim chronograph xanh tạo điểm nhấn độc đáo, trong khi cọc số baton vàng giữ nét thanh lịch. Dòng chữ “Patek Philippe Genève” khẳng định giá trị thương hiệu xa xỉ hàng đầu thế giới. Đây là mẫu đồng hồ dành cho người yêu thích sự tinh xảo – quyền lực – đẳng cấp.', 'pnj_dh014.jpg', 13, 1, '1', '2026-02-25 16:35:54'),
(310, 'Đồng Hồ Patek Philippe Skeleton', 'PNJDH015', 32000000.00, 31000000.00, 'Thép mạ vàng', 'Không', 98.00, 'Chiếc đồng hồ Patek Philippe sang trọng với vỏ và dây kim loại vàng nổi bật, thiết kế mặt số dạng skeleton phô diễn toàn bộ bộ máy cơ khí tinh xảo bên trong. Vành bezel khắc số chỉ phút/giây tạo phong cách thể thao mạnh mẽ, trong khi kim và cọc số vàng giữ nét thanh lịch. Sự kết hợp giữa kỹ thuật chế tác bậc thầy và vẻ ngoài xa hoa khiến chiếc đồng hồ trở thành biểu tượng của đẳng cấp – tinh xảo – sang trọng.', 'pnj_dh015.jpg', 13, 1, '1', '2026-02-25 16:35:54'),
(311, 'Đồng Hồ A. Lange & Söhne Tourbograph Perpetual', 'PNJDH016', 7200000.00, NULL, 'Thép không gỉ', 'Không', 79.00, 'Chiếc đồng hồ A. Lange & Söhne đỉnh cao chế tác với vỏ bạc sang trọng và dây da đen may viền tinh tế. Mặt số trắng nổi bật với các chi tiết phức tạp: hiển thị moonphase ở vị trí 12 giờ, nhiều mặt phụ chronograph chuẩn xác, cùng cơ chế tourbillon lộ diện ở vị trí 6 giờ. Các chữ số Ả Rập và kim xanh tạo điểm nhấn thanh lịch, trong khi dòng chữ “A. Lange & Söhne – Glashütte I/SA” khẳng định giá trị thương hiệu Đức danh tiếng. Đây là mẫu đồng hồ hội tụ những tinh hoa của nghệ thuật chế tác: lịch vạn niên – chronograph – tourbillon, mang lại sự xa xỉ và quyền lực tuyệt đối.', 'pnj_dh016.jpg', 13, 2, '1', '2026-02-25 16:35:54'),
(312, 'Đồng Hồ Rolex Datejust ', 'PNJDH017', 6800000.00, NULL, 'Thép không gỉ', 'Không', 77.00, 'Chiếc đồng hồ Rolex Datejust biểu tượng với dây Jubilee thép không gỉ sang trọng, vỏ và vành bezel khía đặc trưng. Mặt số đen tinh tế kết hợp cọc số và kim bạc sắc nét, cùng ô lịch ngày ở vị trí 3 giờ với kính phóng đại Cyclops tiện dụng. Dòng chữ “Rolex Oyster Perpetual Datejust – Superlative Chronometer Officially Certified” khẳng định chất lượng chuẩn xác và đẳng cấp chế tác Thụy Sĩ. Đây là mẫu đồng hồ mang phong cách kinh điển – sang trọng – bền bỉ, phù hợp cho mọi dịp từ công việc đến sự kiện trang trọng.', 'pnj_dh017.jpg', 13, 2, '1', '2026-02-25 16:35:54'),
(313, 'Đồng Hồ Patek Philippe Tourbillon Moonphase', 'PNJDH018', 9500000.00, NULL, 'Thép không gỉ', 'Không', 93.00, 'Chiếc đồng hồ Patek Philippe đẳng cấp với vỏ kim loại sáng bóng và dây da đen sang trọng. Mặt số đen nổi bật với nhiều chức năng phức tạp: hiển thị thứ và tháng, vòng lịch ngày 1–31, cùng mặt phụ moonphase kết hợp cơ chế tourbillon tinh xảo ở vị trí 6 giờ. Các cọc số và kim bạc thanh lịch, khẳng định sự chuẩn xác và nghệ thuật chế tác bậc thầy. Dòng chữ “Patek Philippe Genève – Tourbillon” khẳng định giá trị thương hiệu xa xỉ hàng đầu thế giới. Đây là mẫu đồng hồ dành cho người yêu thích sự tinh xảo – quyền lực – sang trọng.', 'pnj_dh018.jpg', 13, 2, '1', '2026-02-25 16:35:54'),
(314, 'Đồng Hồ Waldor & Co. Roman Silver', 'PNJDH019', 6200000.00, NULL, 'Thép không gỉ', 'Đá CZ', 76.00, 'Chiếc đồng hồ Waldor & Co. thanh lịch với dây kim loại bạc sáng bóng, thiết kế mắt xích oval độc đáo tạo nên vẻ ngoài tinh tế. Mặt số trắng tối giản, kết hợp các cọc số La Mã cổ điển cùng kim mảnh sắc nét, mang lại phong cách sang trọng và hiện đại. Logo thương hiệu “Waldor & Co.” cùng dòng chữ tinh tế dưới vị trí 12 giờ khẳng định giá trị chế tác cao cấp. Đây là mẫu đồng hồ lý tưởng cho người yêu thích sự tối giản – thanh lịch – tinh tế.', 'pnj_dh019.jpg', 13, 2, '1', '2026-02-25 16:35:54'),
(315, 'Đồng Hồ Qiluoshi Automatic Silver', 'PNJDH020', 7500000.00, NULL, 'Thép không gỉ', 'Không', 84.00, 'Chiếc đồng hồ Qiluoshi thanh lịch với dây kim loại bạc sáng bóng và mặt số trắng tinh tế. Các cọc số hình kim cương nhỏ gọn kết hợp kim bạc sắc nét, cùng ô lịch ngày ở vị trí 3 giờ tiện dụng. Dòng chữ “Qiluoshi – Automatic – Swiss Made” khẳng định bộ máy cơ khí chuẩn xác và chất lượng chế tác cao cấp. Đây là mẫu đồng hồ mang phong cách tối giản – sang trọng – hiện đại, phù hợp cho người yêu thích sự tinh tế và độ bền vượt thời gian.', 'pnj_dh020.jpg', 13, 2, '1', '2026-02-25 16:35:54'),
(316, 'Đồng Hồ Audemars Piguet Royal Oak Chronograph Amethyst', 'PNJDH021', 26000000.00, NULL, 'Thép mạ vàng', 'Không', 95.00, 'Chiếc đồng hồ Audemars Piguet sang trọng với vỏ và dây vàng hồng nổi bật, mặt số tím nhạt với họa tiết Grande Tapisserie đặc trưng. Vành bezel được nạm đá quý tím (amethyst/sapphire) lấp lánh, tạo điểm nhấn xa hoa. Mặt số gồm ba mặt phụ chronograph, kết hợp kim và cọc số vàng tinh tế. Dòng chữ “Audemars Piguet – Automatic – Swiss Made” khẳng định chất lượng chế tác Thụy Sĩ chuẩn xác. Đây là mẫu đồng hồ hội tụ sự xa xỉ – tinh xảo – thời thượng, dành cho người yêu thích phong cách nổi bật và đẳng cấp.', 'pnj_dh021.jpg', 13, 1, '1', '2026-02-25 16:35:54');
INSERT INTO `sanpham` (`id`, `ten_sp`, `ma_sp`, `gia`, `gia_khuyen_mai`, `chat_lieu`, `da_chinh`, `trong_luong`, `mo_ta`, `hinh_anh`, `danh_muc_id`, `thuong_hieu_id`, `trang_thai`, `ngay_tao`) VALUES
(317, 'Đồng Hồ Olym Pianus Automatic ', 'PNJDH022', 21000000.00, NULL, 'Thép mạ vàng', 'Không', 91.00, 'Chiếc đồng hồ Olym Pianus sang trọng với dây và vỏ vàng sáng bóng, mặt số đen tinh tế tạo sự tương phản mạnh mẽ. Các cọc số và kim vàng nổi bật, kết hợp ô lịch thứ/ngày ở vị trí 3 giờ tiện dụng. Logo “OP” cùng chữ ký thương hiệu “Olym Pianus” khẳng định giá trị và phong cách. Dòng chữ “Sapphire – Automatic” cho thấy mặt kính sapphire chống trầy và bộ máy cơ khí chuẩn xác. Đây là mẫu đồng hồ mang phong cách sang trọng – bền bỉ – tinh tế, phù hợp cho người yêu thích sự đẳng cấp và độ tin cậy.', 'pnj_dh022.jpg', 13, 1, '1', '2026-02-25 16:35:54'),
(318, 'Đồng Hồ Pagani Design GMT Automatic', 'PNJDH023', 10500000.00, NULL, 'Thép không gỉ', 'Không', 88.00, 'Chiếc đồng hồ Pagani Design sang trọng với dây thép không gỉ sáng bóng và mặt số bạc có họa tiết tinh tế. Vành bezel khắc thang 24 giờ cho chức năng GMT, giúp theo dõi nhiều múi giờ cùng lúc. Mặt số hiển thị logo thương hiệu, dòng chữ “GMT – Automatic”, cùng ô lịch ngày ở vị trí 3 giờ tiện dụng. Thiết kế tổng thể mang phong cách hiện đại, mạnh mẽ nhưng vẫn giữ nét thanh lịch, khẳng định sự chuẩn xác và độ bền của bộ máy cơ khí. Đây là mẫu đồng hồ lý tưởng cho người yêu thích sự đa năng – sang trọng – tinh tế.', 'pnj_dh023.jpg', 13, 2, '1', '2026-02-25 16:35:54'),
(319, 'Đồng Hồ Chopard Diamond Gold', 'PNJDH024', 27500000.00, 26500000.00, 'Thép mạ vàng', 'Kim cương tự nhiên', 89.00, 'Chiếc đồng hồ Chopard Diamond Gold mang vẻ đẹp sang trọng với thân và dây đeo bằng vàng nguyên khối, từng mắt xích được nạm kim cương tinh xảo. Vòng bezel phủ kín kim cương ôm trọn mặt số vàng rực rỡ, kết hợp chữ số La Mã cổ điển và cọc số kim cương. Bộ kim vàng nổi bật trên nền mặt số tỏa sáng, khẳng định sự tinh tế và đẳng cấp của một chiếc đồng hồ Chronometer Thụy Sĩ. Đây là món phụ kiện hoàn hảo cho những ai yêu thích sự xa hoa và phong cách vĩnh cửu', 'pnj_dh024.jpg', 13, 1, '1', '2026-02-25 16:35:54'),
(320, 'Đồng Hồ Silver Classic Date', 'PNJDH025', 7000000.00, NULL, 'Thép không gỉ', 'Không', 82.00, 'Chiếc đồng hồ Silver Classic Date mang phong cách hiện đại nhưng vẫn giữ nét thanh lịch cổ điển. Vỏ và dây đeo bằng thép không gỉ sáng bóng, mặt số trắng tinh tế với các cọc số bạc tối giản. Bộ kim ba chức năng (giờ, phút, giây) kết hợp cùng ô hiển thị ngày ở vị trí 3 giờ, tạo nên sự tiện dụng và cân đối. Thiết kế mặt vuông bo tròn các cạnh giúp đồng hồ vừa sang trọng vừa trẻ trung, phù hợp cho cả công việc lẫn phong cách thường ngày.', 'pnj_dh025.jpg', 13, 2, '1', '2026-02-25 16:35:54'),
(321, 'Bộ Trang Sức Đá Vuông Vàng', 'SET-PNJ-001', 12500000.00, 11800000.00, 'Vàng 18K', 'Đá thạch anh trắng vuông', 7.50, 'Bộ trang sức Đá Vuông Vàng mang vẻ đẹp hiện đại và tinh tế, gồm dây chuyền, nhẫn và hoa tai đồng bộ. Mỗi món đều nổi bật với viên đá vuông trong suốt, ánh sắc nhẹ nhàng, được bao quanh bởi khung vàng sang trọng. Thiết kế vuông vắn tối giản nhưng thanh lịch, tạo nên sự cân bằng giữa phong cách cổ điển và hiện đại. Đây là lựa chọn hoàn hảo cho những ai yêu thích sự sang trọng và muốn sở hữu một bộ trang sức mang dấu ấn tinh tế.', 'bst01.jpg', 14, 1, '1', '2026-03-08 14:10:00'),
(322, 'Bộ Trang Sức Cỏ Bốn Lá', 'BTS001', 5500000.00, 4950000.00, 'Vàng 18K', 'Không', 12.00, 'Bộ trang sức Bộ Cỏ Bốn Lá Vàng mang vẻ đẹp thanh lịch và đồng bộ, gồm nhẫn, vòng tay, dây chuyền và hoa tai. Mỗi món đều được chế tác từ vàng sáng bóng với họa tiết cỏ bốn lá lặp lại, biểu tượng của sự may mắn và hạnh phúc. Các chi tiết nhỏ tinh xảo kết nối bằng chuỗi mắt xích mảnh mai, tạo nên phong cách vừa hiện đại vừa cổ điển. Đây là lựa chọn hoàn hảo cho những ai yêu thích sự sang trọng và muốn sở hữu một bộ trang sức mang ý nghĩa đặc biệt.', 'SET-PNJ-002.jpg', 14, 1, '1', '2026-03-28 22:05:19'),
(326, 'Nhẫn Vàng Trái Tim Tinh Khôi', 'PNJNR025', 1500000.00, 1300000.00, 'Vàng 18K', 'Không ', NULL, 'Khẳng định sức hút từ vẻ đẹp không phô trương, Petit Heart Muse với thiết kế đai nhẫn siêu mảnh giúp tôn vinh trọn vẹn nét thon dài của đôi tay. Điểm nhấn trái tim trơn bóng mang lại vẻ ngọt ngào, tinh tế, dễ dàng phối hợp với mọi trang phục hàng ngày hoặc đeo chồng cùng các mẫu nhẫn khác để tạo nên phong cách riêng. Một món quà nhỏ mang ý nghĩa lớn lao dành cho bản thân hoặc người thương tại Luxury Jewelry.', 'nhan25.jpg', 1, 1, '1', '2026-04-07 19:41:07');
